INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-moon', 'Name a planet in our solar system.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are eight planets. Pluto was reclassified as a dwarf planet in 2006, so it does not count here.', 'https://science.nasa.gov/solar-system/planets/', 'NASA Solar System Exploration', '2026-11-21', 'NASA public domain', 'space', 1, 0, '[{"canonical":"Mercury","prior":8,"aliases":[]},{"canonical":"Venus","prior":10,"aliases":[]},{"canonical":"Earth","prior":12,"aliases":[]},{"canonical":"Mars","prior":24,"aliases":[]},{"canonical":"Jupiter","prior":20,"aliases":[]},{"canonical":"Saturn","prior":14,"aliases":[]},{"canonical":"Uranus","prior":4,"aliases":[]},{"canonical":"Neptune","prior":6,"aliases":[]}]', NULL, 'Think past the asteroid belt. Four giants live out there.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-giants', 'Name a country in Central America.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Seven sovereign states sit on the Central American isthmus, from Guatemala to Panama. Mexico is counted with North America in this sample. Pending verification.', 'https://en.wikipedia.org/wiki/Central_America', 'Wikipedia: Central America', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Belize","prior":2,"aliases":[]},{"canonical":"Costa Rica","prior":8,"aliases":[]},{"canonical":"El Salvador","prior":3,"aliases":[]},{"canonical":"Guatemala","prior":3,"aliases":[]},{"canonical":"Honduras","prior":3,"aliases":[]},{"canonical":"Nicaragua","prior":3,"aliases":[]},{"canonical":"Panama","prior":8,"aliases":[]}]', 'countries', 'Think of the narrow land bridge between the two Americas.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-orbits', 'Name a moon of Jupiter or Saturn.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Jupiter and Saturn have well over 150 known moons between them. The four big Galilean moons of Jupiter were spotted in 1610.', 'https://science.nasa.gov/solar-system/moons/', 'NASA Solar System Exploration', '2026-11-21', 'NASA public domain', 'space', 2, 0, '[{"canonical":"Titan","prior":22,"aliases":[]},{"canonical":"Europa","prior":20,"aliases":[]},{"canonical":"Io","prior":14,"aliases":[]},{"canonical":"Ganymede","prior":14,"aliases":[]},{"canonical":"Callisto","prior":8,"aliases":[]},{"canonical":"Enceladus","prior":8,"aliases":[]},{"canonical":"Mimas","prior":3,"aliases":[]},{"canonical":"Iapetus","prior":2,"aliases":[]},{"canonical":"Rhea","prior":2,"aliases":[]},{"canonical":"Dione","prior":2,"aliases":[]},{"canonical":"Tethys","prior":2,"aliases":[]},{"canonical":"Hyperion","prior":1,"aliases":[]},{"canonical":"Phoebe","prior":1,"aliases":[]},{"canonical":"Amalthea","prior":1,"aliases":[]},{"canonical":"Janus","prior":1,"aliases":[]},{"canonical":"Himalia","prior":0.5,"aliases":[]},{"canonical":"Pandora","prior":0.5,"aliases":[]},{"canonical":"Prometheus","prior":0.5,"aliases":[]},{"canonical":"Epimetheus","prior":0.5,"aliases":[]},{"canonical":"Thebe","prior":0.5,"aliases":[]},{"canonical":"Metis","prior":0.5,"aliases":[]},{"canonical":"Adrastea","prior":0.5,"aliases":[]}]', NULL, 'Jupiter''s big four were spotted by Galileo. Saturn''s moons are named after giants from Greek myth.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-light', 'Name one of the 88 official constellations.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The International Astronomical Union fixed 88 constellations in 1922. The Big Dipper is an asterism inside Ursa Major, not a constellation of its own.', 'https://www.iau.org/public/themes/constellations/', 'International Astronomical Union', '2026-11-21', 'IAU public information', 'space', 2, 0, '[{"canonical":"Orion","prior":25,"aliases":[]},{"canonical":"Ursa Major","prior":15,"aliases":["Great Bear"]},{"canonical":"Ursa Minor","prior":6,"aliases":["Little Bear"]},{"canonical":"Cassiopeia","prior":8,"aliases":[]},{"canonical":"Scorpius","prior":6,"aliases":["Scorpio"]},{"canonical":"Leo","prior":6,"aliases":[]},{"canonical":"Taurus","prior":4,"aliases":[]},{"canonical":"Gemini","prior":4,"aliases":[]},{"canonical":"Andromeda","prior":4,"aliases":[]},{"canonical":"Sagittarius","prior":3,"aliases":[]},{"canonical":"Cygnus","prior":3,"aliases":[]},{"canonical":"Pegasus","prior":3,"aliases":[]},{"canonical":"Crux","prior":3,"aliases":["Southern Cross"]},{"canonical":"Aries","prior":2,"aliases":[]},{"canonical":"Cancer","prior":2,"aliases":[]},{"canonical":"Virgo","prior":2,"aliases":[]},{"canonical":"Libra","prior":2,"aliases":[]},{"canonical":"Capricornus","prior":2,"aliases":["Capricorn"]},{"canonical":"Aquarius","prior":2,"aliases":[]},{"canonical":"Pisces","prior":2,"aliases":[]},{"canonical":"Lyra","prior":2,"aliases":[]},{"canonical":"Draco","prior":2,"aliases":[]},{"canonical":"Perseus","prior":2,"aliases":[]},{"canonical":"Centaurus","prior":2,"aliases":[]},{"canonical":"Canis Major","prior":2,"aliases":[]},{"canonical":"Hercules","prior":2,"aliases":[]},{"canonical":"Aquila","prior":1,"aliases":[]},{"canonical":"Auriga","prior":1,"aliases":[]},{"canonical":"Boötes","prior":1,"aliases":["Bootes"]},{"canonical":"Carina","prior":1,"aliases":[]},{"canonical":"Cepheus","prior":1,"aliases":[]},{"canonical":"Corvus","prior":1,"aliases":[]},{"canonical":"Delphinus","prior":1,"aliases":[]},{"canonical":"Hydra","prior":1,"aliases":[]},{"canonical":"Lupus","prior":1,"aliases":[]},{"canonical":"Ophiuchus","prior":1,"aliases":[]},{"canonical":"Phoenix","prior":1,"aliases":[]},{"canonical":"Canis Minor","prior":0.5,"aliases":[]},{"canonical":"Monoceros","prior":0.5,"aliases":[]},{"canonical":"Puppis","prior":0.5,"aliases":[]},{"canonical":"Vela","prior":0.5,"aliases":[]},{"canonical":"Sculptor","prior":0.5,"aliases":[]},{"canonical":"Fornax","prior":0.5,"aliases":[]},{"canonical":"Lepus","prior":0.5,"aliases":[]},{"canonical":"Columba","prior":0.5,"aliases":[]},{"canonical":"Eridanus","prior":0.5,"aliases":[]},{"canonical":"Corona Borealis","prior":0.5,"aliases":[]},{"canonical":"Serpens","prior":0.3,"aliases":[]},{"canonical":"Triangulum","prior":0.3,"aliases":[]},{"canonical":"Camelopardalis","prior":0.2,"aliases":[]},{"canonical":"Chamaeleon","prior":0.2,"aliases":[]},{"canonical":"Volans","prior":0.2,"aliases":[]},{"canonical":"Pavo","prior":0.2,"aliases":[]},{"canonical":"Tucana","prior":0.2,"aliases":[]},{"canonical":"Grus","prior":0.2,"aliases":[]}]', NULL, 'Think of the zodiac, then of heroes and beasts from Greek myth.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-year', 'Name a country with more than 100 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The UN World Population Prospects 2024 median estimate puts 16 countries over 100 million, from India and China down to Vietnam. Iran sits just under the line. This sample list is not editorially verified.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"India","prior":30,"aliases":["Bharat","Republic of India"]},{"canonical":"China","prior":26,"aliases":["PRC","People''s Republic of China"]},{"canonical":"United States","prior":18,"aliases":["USA","US","U.S.","U.S.A.","America","United States of America"]},{"canonical":"Indonesia","prior":3,"aliases":[]},{"canonical":"Pakistan","prior":2,"aliases":[]},{"canonical":"Nigeria","prior":2,"aliases":[]},{"canonical":"Brazil","prior":6,"aliases":[]},{"canonical":"Bangladesh","prior":2,"aliases":[]},{"canonical":"Russia","prior":5,"aliases":["Russian Federation"]},{"canonical":"Ethiopia","prior":1,"aliases":[]},{"canonical":"Mexico","prior":3,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"Philippines","prior":1,"aliases":[]},{"canonical":"Egypt","prior":1,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":1,"aliases":["DR Congo","DRC","Congo-Kinshasa","Democratic Republic of Congo"]},{"canonical":"Vietnam","prior":1,"aliases":["Viet Nam"]}]', 'countries', 'Think of South Asia and Africa, then of the far side of the Atlantic.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-everest', 'Name a mountain higher than 8,000 metres.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fourteen peaks rise above 8,000 metres, all in the Himalaya and the Karakoram. Reinhold Messner was the first to climb all of them, in 1986.', 'https://en.wikipedia.org/wiki/Eight-thousander', 'Wikipedia: Eight-thousander', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Mount Everest","prior":40,"aliases":["Everest","Sagarmatha","Chomolungma"]},{"canonical":"K2","prior":20,"aliases":["Mount Godwin-Austen","Chhogori"]},{"canonical":"Kangchenjunga","prior":8,"aliases":["Kanchenjunga"]},{"canonical":"Annapurna","prior":6,"aliases":["Annapurna I"]},{"canonical":"Lhotse","prior":4,"aliases":[]},{"canonical":"Nanga Parbat","prior":4,"aliases":[]},{"canonical":"Makalu","prior":3,"aliases":[]},{"canonical":"Cho Oyu","prior":2,"aliases":[]},{"canonical":"Dhaulagiri","prior":2,"aliases":["Dhaulagiri I"]},{"canonical":"Manaslu","prior":2,"aliases":[]},{"canonical":"Gasherbrum I","prior":1,"aliases":["Hidden Peak","Gasherbrum 1"]},{"canonical":"Broad Peak","prior":1,"aliases":[]},{"canonical":"Gasherbrum II","prior":1,"aliases":["Gasherbrum 2"]},{"canonical":"Shishapangma","prior":1,"aliases":["Xixabangma"]}]', NULL, 'All fourteen are in the Himalaya and the Karakoram, many of them on Nepal''s borders.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-seas', 'Name a noble gas.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The noble gases are helium, neon, argon, krypton, xenon, radon, and oganesson, the last of which is only predicted to behave like the group. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Helium","prior":10,"aliases":[]},{"canonical":"Neon","prior":10,"aliases":[]},{"canonical":"Argon","prior":6,"aliases":[]},{"canonical":"Krypton","prior":1,"aliases":[]},{"canonical":"Xenon","prior":1,"aliases":[]},{"canonical":"Radon","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements', 'They sit in the far right column of the periodic table.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-oceans', 'Name a sea that touches Europe.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Europe touches about two dozen seas, from the Mediterranean to the Arctic. The Caspian is technically a lake, but it is called a sea and is counted here.', 'https://en.wikipedia.org/wiki/List_of_seas', 'Wikipedia: List of seas', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Mediterranean Sea","prior":30,"aliases":["Mediterranean"]},{"canonical":"North Sea","prior":14,"aliases":[]},{"canonical":"Baltic Sea","prior":12,"aliases":["Baltic"]},{"canonical":"Black Sea","prior":12,"aliases":[]},{"canonical":"Adriatic Sea","prior":6,"aliases":["Adriatic"]},{"canonical":"Aegean Sea","prior":6,"aliases":["Aegean"]},{"canonical":"Caspian Sea","prior":3,"aliases":["Caspian"]},{"canonical":"Norwegian Sea","prior":2,"aliases":[]},{"canonical":"Irish Sea","prior":2,"aliases":[]},{"canonical":"Tyrrhenian Sea","prior":2,"aliases":["Tyrrhenian"]},{"canonical":"Ionian Sea","prior":2,"aliases":["Ionian"]},{"canonical":"Barents Sea","prior":2,"aliases":["Barents"]},{"canonical":"Ligurian Sea","prior":1,"aliases":["Ligurian"]},{"canonical":"Balearic Sea","prior":1,"aliases":[]},{"canonical":"White Sea","prior":1,"aliases":[]},{"canonical":"Celtic Sea","prior":1,"aliases":[]},{"canonical":"Sea of Azov","prior":1,"aliases":["Azov"]},{"canonical":"Sea of Marmara","prior":1,"aliases":["Marmara"]},{"canonical":"Alboran Sea","prior":0.5,"aliases":["Alboran"]},{"canonical":"Wadden Sea","prior":0.5,"aliases":[]},{"canonical":"Sea of the Hebrides","prior":0.2,"aliases":[]},{"canonical":"Kara Sea","prior":0.3,"aliases":[]},{"canonical":"Pechora Sea","prior":0.1,"aliases":[]}]', NULL, 'Think of the smaller seas between Italy, Greece and Turkey, and the cold seas of the far north.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-trench', 'Name a river longer than 3,000 km.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'River lengths depend on where the source is drawn, so lists disagree. The Nile and the Amazon trade first place depending on the survey.', 'https://en.wikipedia.org/wiki/List_of_rivers_by_length', 'Wikipedia: List of rivers by length', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Nile","prior":25,"aliases":["River Nile","Nile River"]},{"canonical":"Amazon","prior":22,"aliases":["Amazon River"]},{"canonical":"Yangtze","prior":10,"aliases":["Chang Jiang","Yangtze River"]},{"canonical":"Mississippi","prior":10,"aliases":["Mississippi River"]},{"canonical":"Yellow River","prior":4,"aliases":["Huang He"]},{"canonical":"Congo","prior":4,"aliases":["Congo River","Zaire River"]},{"canonical":"Mekong","prior":4,"aliases":[]},{"canonical":"Volga","prior":4,"aliases":[]},{"canonical":"Missouri","prior":3,"aliases":[]},{"canonical":"Indus","prior":3,"aliases":[]},{"canonical":"Yenisei","prior":2,"aliases":[]},{"canonical":"Ob","prior":2,"aliases":[]},{"canonical":"Paraná","prior":2,"aliases":["Parana"]},{"canonical":"Niger","prior":2,"aliases":["Niger River"]},{"canonical":"Brahmaputra","prior":2,"aliases":[]},{"canonical":"Amur","prior":1,"aliases":[]},{"canonical":"Lena","prior":1,"aliases":[]},{"canonical":"Mackenzie","prior":1,"aliases":[]},{"canonical":"Salween","prior":1,"aliases":[]},{"canonical":"Rio Grande","prior":1,"aliases":[]},{"canonical":"Yukon","prior":1,"aliases":[]},{"canonical":"Irtysh","prior":1,"aliases":[]},{"canonical":"Purus","prior":0.5,"aliases":[]},{"canonical":"Madeira","prior":0.5,"aliases":[]}]', NULL, 'Think of Siberia, China, Africa and the New World.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-peaks', 'Name a chemical element discovered after 1900.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Discovery years are conventional and a few were disputed for decades. This list starts with europium (1901) and runs through oganesson, and it leaves out radon, which was identified in 1900. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Europium","prior":1,"aliases":[]},{"canonical":"Lutetium","prior":1,"aliases":[]},{"canonical":"Protactinium","prior":1,"aliases":[]},{"canonical":"Hafnium","prior":1,"aliases":[]},{"canonical":"Rhenium","prior":1,"aliases":[]},{"canonical":"Technetium","prior":1,"aliases":[]},{"canonical":"Francium","prior":1,"aliases":[]},{"canonical":"Astatine","prior":1,"aliases":[]},{"canonical":"Promethium","prior":1,"aliases":[]},{"canonical":"Neptunium","prior":1,"aliases":[]},{"canonical":"Plutonium","prior":16,"aliases":[]},{"canonical":"Americium","prior":1,"aliases":[]},{"canonical":"Curium","prior":1,"aliases":[]},{"canonical":"Berkelium","prior":1,"aliases":[]},{"canonical":"Californium","prior":1,"aliases":[]},{"canonical":"Einsteinium","prior":4,"aliases":[]},{"canonical":"Fermium","prior":1,"aliases":[]},{"canonical":"Mendelevium","prior":1,"aliases":[]},{"canonical":"Nobelium","prior":1,"aliases":[]},{"canonical":"Lawrencium","prior":1,"aliases":[]},{"canonical":"Rutherfordium","prior":1,"aliases":[]},{"canonical":"Dubnium","prior":1,"aliases":[]},{"canonical":"Seaborgium","prior":1,"aliases":[]},{"canonical":"Bohrium","prior":1,"aliases":[]},{"canonical":"Hassium","prior":1,"aliases":[]},{"canonical":"Meitnerium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Roentgenium","prior":1,"aliases":[]},{"canonical":"Copernicium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Livermorium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements', 'Think of the bottom rows of the periodic table, and elements named after scientists.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-bones', 'Name a bone in the human body.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'An adult skeleton has 206 bones. The femur is the longest. The stapes in the middle ear is the smallest, about 3 mm long.', 'https://en.wikipedia.org/wiki/List_of_bones_of_the_human_skeleton', 'Wikipedia: List of bones of the human skeleton', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Femur","prior":25,"aliases":["Thigh bone","Thighbone"]},{"canonical":"Tibia","prior":8,"aliases":["Shin bone","Shinbone"]},{"canonical":"Humerus","prior":8,"aliases":[]},{"canonical":"Rib","prior":8,"aliases":["Ribs"]},{"canonical":"Skull","prior":6,"aliases":["Cranium"]},{"canonical":"Fibula","prior":5,"aliases":[]},{"canonical":"Radius","prior":5,"aliases":[]},{"canonical":"Ulna","prior":5,"aliases":[]},{"canonical":"Clavicle","prior":5,"aliases":["Collarbone","Collar bone"]},{"canonical":"Scapula","prior":4,"aliases":["Shoulder blade"]},{"canonical":"Sternum","prior":4,"aliases":["Breastbone"]},{"canonical":"Patella","prior":4,"aliases":["Kneecap","Knee cap"]},{"canonical":"Mandible","prior":4,"aliases":["Jawbone","Jaw bone","Jaw"]},{"canonical":"Pelvis","prior":3,"aliases":["Hip bone","Hipbone"]},{"canonical":"Vertebra","prior":3,"aliases":["Vertebrae","Spine"]},{"canonical":"Coccyx","prior":2,"aliases":["Tailbone","Tail bone"]},{"canonical":"Stapes","prior":2,"aliases":["Stirrup"]},{"canonical":"Incus","prior":1,"aliases":["Anvil"]},{"canonical":"Malleus","prior":1,"aliases":["Hammer"]},{"canonical":"Maxilla","prior":1,"aliases":[]},{"canonical":"Sacrum","prior":1,"aliases":[]},{"canonical":"Hyoid","prior":1,"aliases":["Hyoid bone"]},{"canonical":"Calcaneus","prior":1,"aliases":["Heel bone"]},{"canonical":"Phalanx","prior":1,"aliases":["Phalanges"]},{"canonical":"Talus","prior":0.5,"aliases":[]},{"canonical":"Carpal","prior":0.5,"aliases":["Carpals"]},{"canonical":"Metacarpal","prior":0.5,"aliases":["Metacarpals"]},{"canonical":"Metatarsal","prior":0.5,"aliases":["Metatarsals"]},{"canonical":"Scaphoid","prior":0.5,"aliases":[]},{"canonical":"Occipital bone","prior":0.5,"aliases":["Occipital"]},{"canonical":"Parietal bone","prior":0.5,"aliases":["Parietal"]},{"canonical":"Temporal bone","prior":0.5,"aliases":["Temporal"]},{"canonical":"Frontal bone","prior":0.5,"aliases":["Frontal"]},{"canonical":"Zygomatic bone","prior":0.5,"aliases":["Cheekbone","Zygomatic"]},{"canonical":"Nasal bone","prior":0.5,"aliases":[]},{"canonical":"Sphenoid","prior":0.3,"aliases":[]},{"canonical":"Ethmoid","prior":0.3,"aliases":[]},{"canonical":"Lacrimal bone","prior":0.3,"aliases":["Lacrimal"]},{"canonical":"Vomer","prior":0.3,"aliases":[]},{"canonical":"Palatine bone","prior":0.3,"aliases":["Palatine"]},{"canonical":"Atlas","prior":0.3,"aliases":[]},{"canonical":"Axis","prior":0.3,"aliases":[]},{"canonical":"Ilium","prior":0.4,"aliases":[]},{"canonical":"Ischium","prior":0.3,"aliases":[]},{"canonical":"Pubis","prior":0.3,"aliases":[]},{"canonical":"Lunate","prior":0.3,"aliases":[]},{"canonical":"Navicular","prior":0.3,"aliases":[]},{"canonical":"Cuboid","prior":0.3,"aliases":[]},{"canonical":"Cuneiform","prior":0.2,"aliases":[]},{"canonical":"Trapezium","prior":0.2,"aliases":[]},{"canonical":"Trapezoid","prior":0.2,"aliases":[]},{"canonical":"Hamate","prior":0.2,"aliases":[]},{"canonical":"Pisiform","prior":0.2,"aliases":[]},{"canonical":"Capitate","prior":0.2,"aliases":[]},{"canonical":"Triquetrum","prior":0.2,"aliases":[]}]', NULL, 'Think of the tiny bones in your ear, your wrist and your ankle.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-lungs', 'Name a halogen.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Group 17 is fluorine, chlorine, bromine, iodine, astatine, and tennessine. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Fluorine","prior":8,"aliases":[]},{"canonical":"Chlorine","prior":8,"aliases":[]},{"canonical":"Bromine","prior":1,"aliases":[]},{"canonical":"Iodine","prior":6,"aliases":[]},{"canonical":"Astatine","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]}]', 'elements', 'Think of what is in swimming pools and toothpaste, then of the heavier ones further down.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-counts', 'Name an organ of the human body.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Anatomists count roughly 78 organs, depending on how they are grouped. The skin is the largest by area and by weight.', 'https://en.wikipedia.org/wiki/List_of_organs_of_the_human_body', 'Wikipedia: List of organs of the human body', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Heart","prior":30,"aliases":[]},{"canonical":"Brain","prior":18,"aliases":[]},{"canonical":"Lung","prior":12,"aliases":["Lungs"]},{"canonical":"Liver","prior":10,"aliases":[]},{"canonical":"Kidney","prior":8,"aliases":["Kidneys"]},{"canonical":"Stomach","prior":6,"aliases":[]},{"canonical":"Skin","prior":4,"aliases":[]},{"canonical":"Pancreas","prior":3,"aliases":[]},{"canonical":"Intestine","prior":3,"aliases":["Intestines","Small intestine","Large intestine","Gut","Bowel"]},{"canonical":"Spleen","prior":2,"aliases":[]},{"canonical":"Bladder","prior":2,"aliases":["Urinary bladder"]},{"canonical":"Eye","prior":1.5,"aliases":["Eyes"]},{"canonical":"Gallbladder","prior":1,"aliases":["Gall bladder"]},{"canonical":"Appendix","prior":1,"aliases":[]},{"canonical":"Thyroid","prior":1,"aliases":["Thyroid gland"]},{"canonical":"Colon","prior":0.5,"aliases":[]},{"canonical":"Tongue","prior":0.5,"aliases":[]},{"canonical":"Oesophagus","prior":0.5,"aliases":["Esophagus","Gullet"]},{"canonical":"Uterus","prior":0.5,"aliases":["Womb"]},{"canonical":"Ovary","prior":0.5,"aliases":["Ovaries"]},{"canonical":"Prostate","prior":0.5,"aliases":["Prostate gland"]},{"canonical":"Testis","prior":0.3,"aliases":["Testes","Testicle","Testicles"]},{"canonical":"Thymus","prior":0.3,"aliases":[]},{"canonical":"Adrenal gland","prior":0.3,"aliases":["Adrenal glands","Adrenals"]},{"canonical":"Pituitary gland","prior":0.3,"aliases":["Pituitary"]},{"canonical":"Pineal gland","prior":0.2,"aliases":["Pineal"]},{"canonical":"Larynx","prior":0.3,"aliases":["Voice box"]},{"canonical":"Trachea","prior":0.3,"aliases":["Windpipe"]},{"canonical":"Diaphragm","prior":0.3,"aliases":[]},{"canonical":"Tonsil","prior":0.3,"aliases":["Tonsils"]}]', NULL, 'Think of glands, and organs you would only notice if they hurt.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-neurons', 'Name a part of the human brain.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The adult brain holds about 86 billion neurons. The cerebellum is about a tenth of the brain''s volume but contains more than half of its neurons.', 'https://en.wikipedia.org/wiki/Human_brain', 'Wikipedia: Human brain', '2026-11-21', 'CC BY-SA 4.0', 'body', 2, 0, '[{"canonical":"Cerebellum","prior":14,"aliases":[]},{"canonical":"Cerebrum","prior":12,"aliases":[]},{"canonical":"Hippocampus","prior":10,"aliases":[]},{"canonical":"Frontal lobe","prior":10,"aliases":[]},{"canonical":"Brainstem","prior":8,"aliases":["Brain stem"]},{"canonical":"Amygdala","prior":8,"aliases":[]},{"canonical":"Hypothalamus","prior":6,"aliases":[]},{"canonical":"Thalamus","prior":5,"aliases":[]},{"canonical":"Medulla oblongata","prior":4,"aliases":["Medulla"]},{"canonical":"Prefrontal cortex","prior":4,"aliases":[]},{"canonical":"Cerebral cortex","prior":4,"aliases":["Cortex"]},{"canonical":"Corpus callosum","prior":3,"aliases":[]},{"canonical":"Temporal lobe","prior":3,"aliases":[]},{"canonical":"Parietal lobe","prior":3,"aliases":[]},{"canonical":"Occipital lobe","prior":3,"aliases":[]},{"canonical":"Pituitary gland","prior":3,"aliases":["Pituitary"]},{"canonical":"Pons","prior":2,"aliases":[]},{"canonical":"Pineal gland","prior":2,"aliases":["Pineal"]},{"canonical":"Basal ganglia","prior":1,"aliases":[]},{"canonical":"Midbrain","prior":1,"aliases":["Mesencephalon"]},{"canonical":"Limbic system","prior":1,"aliases":[]},{"canonical":"Broca''s area","prior":1,"aliases":["Brocas area"]},{"canonical":"Wernicke''s area","prior":0.5,"aliases":["Wernickes area"]},{"canonical":"Motor cortex","prior":0.5,"aliases":[]},{"canonical":"Insula","prior":0.3,"aliases":[]},{"canonical":"Striatum","prior":0.3,"aliases":[]},{"canonical":"Substantia nigra","prior":0.3,"aliases":[]},{"canonical":"Ventricles","prior":0.3,"aliases":["Ventricle"]},{"canonical":"Fornix","prior":0.2,"aliases":[]},{"canonical":"Caudate nucleus","prior":0.2,"aliases":[]},{"canonical":"Putamen","prior":0.2,"aliases":[]},{"canonical":"Globus pallidus","prior":0.2,"aliases":[]}]', NULL, 'Think of the lobes, and the small parts deep inside that handle fear and memory.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-gut', 'Name an African country with more than 50 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Using the UN 2024 estimates, nine African countries are at or above 50 million: Nigeria, Ethiopia, Egypt, DR Congo, Tanzania, South Africa, Kenya, Sudan, and Uganda. Algeria sits just below. Pending verification.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"Nigeria","prior":24,"aliases":[]},{"canonical":"Ethiopia","prior":8,"aliases":[]},{"canonical":"Egypt","prior":10,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":4,"aliases":["DR Congo","DRC","Congo-Kinshasa","Democratic Republic of Congo"]},{"canonical":"Tanzania","prior":3,"aliases":[]},{"canonical":"South Africa","prior":6,"aliases":[]},{"canonical":"Kenya","prior":3,"aliases":[]},{"canonical":"Sudan","prior":1,"aliases":[]},{"canonical":"Uganda","prior":1,"aliases":[]}]', 'countries', 'Think of East Africa and the Nile valley.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-order', 'Name an invention from the 1800s.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Bell patented the telephone in 1876 and Edison''s practical light bulb followed in 1879. Earlier inventors made working versions of both, which is why the dates are argued over.', 'https://en.wikipedia.org/wiki/Timeline_of_historic_inventions', 'Wikipedia: Timeline of historic inventions', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0, '[{"canonical":"Telephone","prior":25,"aliases":["Phone"]},{"canonical":"Light bulb","prior":18,"aliases":["Lightbulb","Incandescent light bulb","Electric light"]},{"canonical":"Telegraph","prior":6,"aliases":["Electric telegraph"]},{"canonical":"Camera","prior":6,"aliases":["Photograph","Photography"]},{"canonical":"Automobile","prior":6,"aliases":["Car","Motor car"]},{"canonical":"Steam locomotive","prior":4,"aliases":["Locomotive","Steam train","Railway"]},{"canonical":"Bicycle","prior":3,"aliases":["Bike"]},{"canonical":"Phonograph","prior":3,"aliases":[]},{"canonical":"Radio","prior":3,"aliases":[]},{"canonical":"Typewriter","prior":2,"aliases":[]},{"canonical":"Dynamite","prior":2,"aliases":[]},{"canonical":"Sewing machine","prior":1.5,"aliases":[]},{"canonical":"Morse code","prior":1,"aliases":[]},{"canonical":"Stethoscope","prior":1,"aliases":[]},{"canonical":"Internal combustion engine","prior":1,"aliases":["Petrol engine","Gasoline engine"]},{"canonical":"Electric motor","prior":1,"aliases":[]},{"canonical":"Kinetoscope","prior":1,"aliases":["Motion picture camera","Film camera","Movie camera"]},{"canonical":"Diesel engine","prior":0.5,"aliases":[]},{"canonical":"X-ray machine","prior":0.5,"aliases":["X-ray","X-rays"]},{"canonical":"Gramophone","prior":0.5,"aliases":[]},{"canonical":"Refrigerator","prior":0.5,"aliases":["Fridge"]},{"canonical":"Safety elevator","prior":0.5,"aliases":["Elevator","Lift"]},{"canonical":"Friction match","prior":0.5,"aliases":["Match","Matches"]},{"canonical":"Revolver","prior":0.5,"aliases":[]},{"canonical":"Pasteurisation","prior":0.5,"aliases":["Pasteurization"]},{"canonical":"Zip","prior":0.3,"aliases":["Zipper","Clasp locker"]},{"canonical":"Postage stamp","prior":0.3,"aliases":["Stamp","Penny Black"]},{"canonical":"Blue jeans","prior":0.3,"aliases":["Jeans"]},{"canonical":"Fountain pen","prior":0.3,"aliases":[]},{"canonical":"Escalator","prior":0.2,"aliases":[]},{"canonical":"Dishwasher","prior":0.2,"aliases":[]},{"canonical":"Paper clip","prior":0.2,"aliases":["Paperclip"]},{"canonical":"Safety pin","prior":0.2,"aliases":[]},{"canonical":"Barbed wire","prior":0.2,"aliases":[]},{"canonical":"Ferris wheel","prior":0.2,"aliases":[]},{"canonical":"Stapler","prior":0.2,"aliases":[]}]', NULL, 'Think of sound, light, medicine and getting around in the 1800s.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-piano', 'Name a musical instrument with strings.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A piano is a string instrument too: each key throws a felt hammer at a stretched steel string. A concert grand has about 230 of them.', 'https://en.wikipedia.org/wiki/List_of_string_instruments', 'Wikipedia: List of string instruments', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Guitar","prior":35,"aliases":["Acoustic guitar","Electric guitar"]},{"canonical":"Violin","prior":18,"aliases":["Fiddle"]},{"canonical":"Cello","prior":8,"aliases":["Violoncello"]},{"canonical":"Harp","prior":7,"aliases":[]},{"canonical":"Piano","prior":4,"aliases":["Pianoforte"]},{"canonical":"Double bass","prior":4,"aliases":["Bass","Upright bass","Contrabass","Bass guitar"]},{"canonical":"Viola","prior":4,"aliases":[]},{"canonical":"Ukulele","prior":4,"aliases":["Uke"]},{"canonical":"Banjo","prior":3,"aliases":[]},{"canonical":"Mandolin","prior":2,"aliases":[]},{"canonical":"Sitar","prior":2,"aliases":[]},{"canonical":"Lute","prior":1,"aliases":[]},{"canonical":"Harpsichord","prior":1,"aliases":[]},{"canonical":"Zither","prior":0.5,"aliases":[]},{"canonical":"Lyre","prior":0.5,"aliases":[]},{"canonical":"Balalaika","prior":0.5,"aliases":[]},{"canonical":"Dulcimer","prior":0.3,"aliases":[]},{"canonical":"Koto","prior":0.3,"aliases":[]},{"canonical":"Erhu","prior":0.3,"aliases":[]},{"canonical":"Sarod","prior":0.3,"aliases":[]},{"canonical":"Veena","prior":0.3,"aliases":[]},{"canonical":"Oud","prior":0.3,"aliases":[]},{"canonical":"Bouzouki","prior":0.3,"aliases":[]},{"canonical":"Shamisen","prior":0.3,"aliases":[]},{"canonical":"Clavichord","prior":0.2,"aliases":[]},{"canonical":"Hurdy-gurdy","prior":0.2,"aliases":["Hurdy gurdy"]},{"canonical":"Pipa","prior":0.2,"aliases":[]},{"canonical":"Charango","prior":0.2,"aliases":[]},{"canonical":"Santoor","prior":0.2,"aliases":["Santur"]},{"canonical":"Tanpura","prior":0.2,"aliases":["Tambura"]},{"canonical":"Guzheng","prior":0.2,"aliases":[]},{"canonical":"Kora","prior":0.2,"aliases":[]}]', NULL, 'Think of Indian classical music, Japan and China, and medieval Europe.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-towers', 'Name an alkali metal.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The alkali metals are lithium, sodium, potassium, rubidium, caesium, and francium. Hydrogen is left off this list. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Lithium","prior":6,"aliases":[]},{"canonical":"Sodium","prior":8,"aliases":[]},{"canonical":"Potassium","prior":8,"aliases":[]},{"canonical":"Rubidium","prior":1,"aliases":[]},{"canonical":"Cesium","prior":1,"aliases":["Caesium"]},{"canonical":"Francium","prior":1,"aliases":[]}]', 'elements', 'They sit in the far left column of the periodic table, and they fizz or explode in water.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-empire', 'Name a programming language.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fortran, from 1957, is usually counted as the first widely used high-level language. HTML and CSS describe pages rather than programs, so they are not on the list.', 'https://en.wikipedia.org/wiki/List_of_programming_languages', 'Wikipedia: List of programming languages', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Python","prior":30,"aliases":[]},{"canonical":"Java","prior":15,"aliases":[]},{"canonical":"JavaScript","prior":12,"aliases":["JS","Java Script"]},{"canonical":"C++","prior":8,"aliases":["CPP","C plus plus"]},{"canonical":"C","prior":6,"aliases":[]},{"canonical":"C#","prior":4,"aliases":["C Sharp","CSharp"]},{"canonical":"Ruby","prior":2,"aliases":[]},{"canonical":"PHP","prior":2,"aliases":[]},{"canonical":"Swift","prior":2,"aliases":[]},{"canonical":"Go","prior":1.5,"aliases":["Golang"]},{"canonical":"Rust","prior":1.5,"aliases":[]},{"canonical":"Kotlin","prior":1,"aliases":[]},{"canonical":"R","prior":1,"aliases":[]},{"canonical":"TypeScript","prior":1,"aliases":["TS","Type Script"]},{"canonical":"SQL","prior":1,"aliases":[]},{"canonical":"MATLAB","prior":0.5,"aliases":[]},{"canonical":"Perl","prior":0.5,"aliases":[]},{"canonical":"Fortran","prior":0.5,"aliases":[]},{"canonical":"COBOL","prior":0.5,"aliases":[]},{"canonical":"BASIC","prior":0.5,"aliases":[]},{"canonical":"Assembly","prior":0.5,"aliases":["Assembly language","Assembler"]},{"canonical":"Lisp","prior":0.4,"aliases":[]},{"canonical":"Haskell","prior":0.4,"aliases":[]},{"canonical":"Scala","prior":0.3,"aliases":[]},{"canonical":"Pascal","prior":0.3,"aliases":[]},{"canonical":"Lua","prior":0.3,"aliases":[]},{"canonical":"Dart","prior":0.3,"aliases":[]},{"canonical":"Julia","prior":0.3,"aliases":[]},{"canonical":"Scratch","prior":0.3,"aliases":[]},{"canonical":"Objective-C","prior":0.3,"aliases":["Objective C","ObjC"]},{"canonical":"Visual Basic","prior":0.3,"aliases":["VB","VB.NET"]},{"canonical":"Bash","prior":0.2,"aliases":["Shell"]},{"canonical":"Prolog","prior":0.2,"aliases":[]},{"canonical":"Erlang","prior":0.2,"aliases":[]},{"canonical":"Elixir","prior":0.2,"aliases":[]},{"canonical":"OCaml","prior":0.1,"aliases":[]},{"canonical":"Smalltalk","prior":0.1,"aliases":[]},{"canonical":"Ada","prior":0.1,"aliases":[]},{"canonical":"Clojure","prior":0.1,"aliases":[]},{"canonical":"F#","prior":0.1,"aliases":["F Sharp"]},{"canonical":"Zig","prior":0.1,"aliases":[]},{"canonical":"Groovy","prior":0.1,"aliases":[]},{"canonical":"Racket","prior":0.1,"aliases":[]},{"canonical":"Scheme","prior":0.1,"aliases":[]},{"canonical":"APL","prior":0.05,"aliases":[]},{"canonical":"Simula","prior":0.05,"aliases":[]},{"canonical":"ALGOL","prior":0.05,"aliases":[]}]', NULL, 'Think of old languages from the 1950s and 60s, and the ones used to build phone apps.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-first', 'Name a country with fewer than 1 million people.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'A 2023 UN grouping of member states under 1 million runs from Fiji and Iceland through Tuvalu. This sample also accepts Vatican City, an observer state, and Vanuatu. Pending verification.', 'https://population.un.org/wpp/', 'United Nations population estimates, via UN member groupings', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"Iceland","prior":12,"aliases":[]},{"canonical":"Luxembourg","prior":8,"aliases":[]},{"canonical":"Malta","prior":4,"aliases":[]},{"canonical":"Brunei","prior":2,"aliases":["Brunei Darussalam"]},{"canonical":"Bahamas","prior":2,"aliases":["The Bahamas"]},{"canonical":"Maldives","prior":3,"aliases":[]},{"canonical":"Belize","prior":1,"aliases":[]},{"canonical":"Barbados","prior":2,"aliases":[]},{"canonical":"Fiji","prior":2,"aliases":[]},{"canonical":"Guyana","prior":1,"aliases":[]},{"canonical":"Suriname","prior":1,"aliases":[]},{"canonical":"Bhutan","prior":2,"aliases":[]},{"canonical":"Comoros","prior":1,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":[]},{"canonical":"Cabo Verde","prior":1,"aliases":["Cape Verde"]},{"canonical":"Vanuatu","prior":1,"aliases":[]},{"canonical":"Samoa","prior":1,"aliases":[]},{"canonical":"Andorra","prior":2,"aliases":[]},{"canonical":"Monaco","prior":3,"aliases":[]},{"canonical":"Liechtenstein","prior":2,"aliases":[]},{"canonical":"San Marino","prior":1,"aliases":[]},{"canonical":"Vatican City","prior":4,"aliases":["Holy See"]},{"canonical":"Palau","prior":1,"aliases":[]},{"canonical":"Nauru","prior":1,"aliases":[]},{"canonical":"Tuvalu","prior":1,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Seychelles","prior":1,"aliases":[]},{"canonical":"Grenada","prior":1,"aliases":[]},{"canonical":"Dominica","prior":1,"aliases":[]},{"canonical":"Saint Lucia","prior":1,"aliases":[]},{"canonical":"Antigua and Barbuda","prior":1,"aliases":[]},{"canonical":"Saint Kitts and Nevis","prior":1,"aliases":[]},{"canonical":"Saint Vincent and the Grenadines","prior":1,"aliases":["Saint Vincent and the Grenadines"]},{"canonical":"Marshall Islands","prior":1,"aliases":[]},{"canonical":"Micronesia","prior":1,"aliases":["Federated States of Micronesia"]},{"canonical":"Sao Tome and Principe","prior":1,"aliases":["São Tomé and Príncipe"]},{"canonical":"Montenegro","prior":2,"aliases":[]}]', 'countries', 'Think of tiny islands in the Pacific and the Caribbean, and the microstates of Europe.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-pyramid', 'Name one of the New Seven Wonders of the World.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The list came from a public vote run by the New7Wonders Foundation and announced in 2007. The Great Pyramid of Giza, the only ancient wonder still standing, was given an honorary place outside the seven.', 'https://en.wikipedia.org/wiki/New_7_Wonders_of_the_World', 'Wikipedia: New 7 Wonders of the World', '2026-11-21', 'CC BY-SA 4.0', 'landmarks', 2, 0, '[{"canonical":"Great Wall of China","prior":25,"aliases":["Great Wall","The Great Wall"]},{"canonical":"Taj Mahal","prior":18,"aliases":[]},{"canonical":"Machu Picchu","prior":14,"aliases":[]},{"canonical":"Colosseum","prior":14,"aliases":["Coliseum","Roman Colosseum"]},{"canonical":"Christ the Redeemer","prior":12,"aliases":["Cristo Redentor"]},{"canonical":"Petra","prior":8,"aliases":[]},{"canonical":"Chichén Itzá","prior":8,"aliases":["Chichen Itza"]}]', NULL, 'Think of South America, Mexico, Jordan and Italy.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-older', 'Name a member of the Group of Seven.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'The G7 is Canada, France, Germany, Italy, Japan, the United Kingdom, and the United States. The European Union attends but is not a country on this list. Pending verification.', 'https://www.international.gc.ca/world-monde/international_relations-relations_internationales/g7/index.aspx', 'Government of Canada: G7', '2026-11-21', 'Government of Canada public information', 'geography', 1, 0, '[{"canonical":"Canada","prior":4,"aliases":[]},{"canonical":"France","prior":8,"aliases":[]},{"canonical":"Germany","prior":4,"aliases":[]},{"canonical":"Italy","prior":4,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"United Kingdom","prior":4,"aliases":["UK","Britain"]},{"canonical":"United States","prior":8,"aliases":["USA","US","America"]}]', 'countries', 'Think of Europe''s biggest economies, plus two across the Atlantic and one in Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-timeline', 'Name a city that has hosted the Summer Olympics.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Twenty-three cities have hosted the Summer Games. London has hosted three times, in 1908, 1948 and 2012. Paris and Los Angeles will both reach three with 2024 and 2028.', 'https://en.wikipedia.org/wiki/List_of_Olympic_Games_host_cities', 'Wikipedia: List of Olympic Games host cities', '2026-11-21', 'CC BY-SA 4.0', 'culture', 2, 0, '[{"canonical":"London","prior":20,"aliases":[]},{"canonical":"Paris","prior":12,"aliases":[]},{"canonical":"Beijing","prior":10,"aliases":["Peking"]},{"canonical":"Tokyo","prior":10,"aliases":[]},{"canonical":"Los Angeles","prior":8,"aliases":["LA","L.A."]},{"canonical":"Athens","prior":8,"aliases":[]},{"canonical":"Rio de Janeiro","prior":6,"aliases":["Rio"]},{"canonical":"Sydney","prior":6,"aliases":[]},{"canonical":"Barcelona","prior":4,"aliases":[]},{"canonical":"Atlanta","prior":3,"aliases":[]},{"canonical":"Seoul","prior":3,"aliases":[]},{"canonical":"Moscow","prior":2,"aliases":[]},{"canonical":"Montreal","prior":2,"aliases":["Montréal"]},{"canonical":"Munich","prior":2,"aliases":["München"]},{"canonical":"Mexico City","prior":2,"aliases":[]},{"canonical":"Rome","prior":2,"aliases":[]},{"canonical":"Berlin","prior":2,"aliases":[]},{"canonical":"Melbourne","prior":1,"aliases":[]},{"canonical":"Helsinki","prior":1,"aliases":[]},{"canonical":"Amsterdam","prior":1,"aliases":[]},{"canonical":"Stockholm","prior":1,"aliases":[]},{"canonical":"Antwerp","prior":0.5,"aliases":[]},{"canonical":"St. Louis","prior":0.5,"aliases":["St Louis","Saint Louis"]}]', NULL, 'Think of the early 1900s, when Europe hosted almost every Games.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-liberty', 'Name a skyscraper taller than 400 metres, measured to its architectural top.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Burj Khalifa has held the record since 2010 at 828 metres. The Empire State Building''s roof is 381 metres, so its antenna does not count here.', 'https://www.skyscrapercenter.com/buildings', 'Council on Tall Buildings and Urban Habitat', '2026-11-21', 'CTBUH public listing', 'landmarks', 3, 0, '[{"canonical":"Burj Khalifa","prior":40,"aliases":[]},{"canonical":"One World Trade Center","prior":8,"aliases":["Freedom Tower","1 WTC","One WTC"]},{"canonical":"Shanghai Tower","prior":8,"aliases":[]},{"canonical":"Taipei 101","prior":6,"aliases":[]},{"canonical":"Petronas Towers","prior":6,"aliases":["Petronas Twin Towers","Petronas Tower"]},{"canonical":"Willis Tower","prior":4,"aliases":["Sears Tower"]},{"canonical":"Abraj Al-Bait","prior":2,"aliases":["Makkah Royal Clock Tower","Mecca Clock Tower","Abraj Al Bait"]},{"canonical":"Lotte World Tower","prior":1.5,"aliases":[]},{"canonical":"Ping An Finance Center","prior":1,"aliases":["Ping An Finance Centre"]},{"canonical":"Merdeka 118","prior":1,"aliases":[]},{"canonical":"Shanghai World Financial Center","prior":0.8,"aliases":[]},{"canonical":"International Commerce Centre","prior":0.5,"aliases":["ICC Hong Kong"]},{"canonical":"Central Park Tower","prior":0.5,"aliases":[]},{"canonical":"Lakhta Center","prior":0.5,"aliases":[]},{"canonical":"Goldin Finance 117","prior":0.3,"aliases":[]},{"canonical":"Guangzhou CTF Finance Centre","prior":0.3,"aliases":[]},{"canonical":"Tianjin CTF Finance Centre","prior":0.3,"aliases":[]},{"canonical":"CITIC Tower","prior":0.3,"aliases":["China Zun"]},{"canonical":"Landmark 81","prior":0.3,"aliases":["Vincom Landmark 81"]},{"canonical":"432 Park Avenue","prior":0.3,"aliases":[]},{"canonical":"Jin Mao Tower","prior":0.3,"aliases":[]},{"canonical":"Two International Finance Centre","prior":0.3,"aliases":["Two IFC","2 IFC"]},{"canonical":"Trump International Hotel and Tower","prior":0.2,"aliases":["Trump Tower Chicago"]},{"canonical":"Wuhan Greenland Center","prior":0.2,"aliases":[]}]', NULL, 'Think of China, the Gulf, and the tall towers of New York.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-statues', 'Name a country with an area greater than 1 million square kilometres.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Total area, land plus inland water, from the standard country-area tables. Twenty-nine countries clear 1 million km². Tanzania and Nigeria fall short. Greenland is not counted here because it is not a country. Pending verification.', 'https://en.wikipedia.org/wiki/List_of_countries_and_dependencies_by_area', 'Wikipedia: List of countries and dependencies by area', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Russia","prior":16,"aliases":["Russian Federation"]},{"canonical":"Canada","prior":14,"aliases":[]},{"canonical":"China","prior":12,"aliases":["PRC","People''s Republic of China"]},{"canonical":"United States","prior":12,"aliases":["USA","US","America","United States of America"]},{"canonical":"Brazil","prior":8,"aliases":[]},{"canonical":"Australia","prior":8,"aliases":[]},{"canonical":"India","prior":6,"aliases":["Bharat"]},{"canonical":"Argentina","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":2,"aliases":[]},{"canonical":"Algeria","prior":2,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":2,"aliases":["DR Congo","DRC","Democratic Republic of Congo"]},{"canonical":"Saudi Arabia","prior":2,"aliases":[]},{"canonical":"Mexico","prior":2,"aliases":[]},{"canonical":"Indonesia","prior":2,"aliases":[]},{"canonical":"Sudan","prior":1,"aliases":[]},{"canonical":"Libya","prior":2,"aliases":[]},{"canonical":"Iran","prior":2,"aliases":[]},{"canonical":"Mongolia","prior":2,"aliases":[]},{"canonical":"Peru","prior":1,"aliases":[]},{"canonical":"Chad","prior":1,"aliases":[]},{"canonical":"Niger","prior":1,"aliases":[]},{"canonical":"Angola","prior":1,"aliases":[]},{"canonical":"Mali","prior":1,"aliases":[]},{"canonical":"South Africa","prior":1,"aliases":[]},{"canonical":"Colombia","prior":1,"aliases":[]},{"canonical":"Ethiopia","prior":1,"aliases":[]},{"canonical":"Bolivia","prior":1,"aliases":[]},{"canonical":"Mauritania","prior":1,"aliases":[]},{"canonical":"Egypt","prior":1,"aliases":[]}]', 'countries', 'Think of the deserts of North Africa, Central Asia and the Andes.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-whale', 'Name a species of whale.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The blue whale is the largest animal known to have lived, up to about 30 metres. Orcas and pilot whales are technically large dolphins, but both are called whales and are accepted.', 'https://en.wikipedia.org/wiki/List_of_cetaceans', 'Wikipedia: List of cetaceans', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Blue whale","prior":30,"aliases":[]},{"canonical":"Humpback whale","prior":18,"aliases":["Humpback"]},{"canonical":"Orca","prior":12,"aliases":["Killer whale"]},{"canonical":"Sperm whale","prior":10,"aliases":[]},{"canonical":"Beluga","prior":6,"aliases":["Beluga whale","White whale"]},{"canonical":"Narwhal","prior":5,"aliases":[]},{"canonical":"Grey whale","prior":3,"aliases":["Gray whale"]},{"canonical":"Minke whale","prior":3,"aliases":["Minke"]},{"canonical":"Fin whale","prior":3,"aliases":["Finback"]},{"canonical":"Bowhead whale","prior":2,"aliases":["Bowhead"]},{"canonical":"Right whale","prior":2,"aliases":["North Atlantic right whale","Southern right whale"]},{"canonical":"Sei whale","prior":1,"aliases":[]},{"canonical":"Pilot whale","prior":1,"aliases":[]},{"canonical":"Bryde''s whale","prior":0.5,"aliases":["Brydes whale"]},{"canonical":"Pygmy sperm whale","prior":0.3,"aliases":[]},{"canonical":"Cuvier''s beaked whale","prior":0.3,"aliases":["Cuviers beaked whale"]},{"canonical":"Dwarf sperm whale","prior":0.2,"aliases":[]},{"canonical":"Pygmy right whale","prior":0.2,"aliases":[]},{"canonical":"False killer whale","prior":0.2,"aliases":[]},{"canonical":"Omura''s whale","prior":0.1,"aliases":["Omuras whale"]},{"canonical":"Baird''s beaked whale","prior":0.1,"aliases":["Bairds beaked whale"]},{"canonical":"Melon-headed whale","prior":0.1,"aliases":[]},{"canonical":"Northern bottlenose whale","prior":0.1,"aliases":[]}]', NULL, 'Think of toothed whales with odd heads, and the ones named after the people who found them.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-heavy', 'Name a country in Oceania.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'This sample accepts the sovereign states usually counted in Oceania, including Australia and New Zealand. Pending verification.', 'https://en.wikipedia.org/wiki/Oceania', 'Wikipedia: Oceania', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Australia","prior":16,"aliases":[]},{"canonical":"Fiji","prior":1,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Marshall Islands","prior":1,"aliases":[]},{"canonical":"Micronesia","prior":1,"aliases":[]},{"canonical":"Nauru","prior":1,"aliases":[]},{"canonical":"New Zealand","prior":8,"aliases":[]},{"canonical":"Palau","prior":1,"aliases":[]},{"canonical":"Papua New Guinea","prior":1,"aliases":[]},{"canonical":"Samoa","prior":1,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Tuvalu","prior":1,"aliases":[]},{"canonical":"Vanuatu","prior":1,"aliases":[]}]', 'countries', 'Think of the tiny island nations scattered across the Pacific.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-masses', 'Name a species of wild cat.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'There are about 40 wild cat species. The rusty-spotted cat is the smallest, around 1.5 kg. The tiger is the largest.', 'https://www.catsg.org/', 'IUCN Cat Specialist Group', '2026-11-21', 'IUCN SSC Cat Specialist Group public information', 'nature', 2, 0, '[{"canonical":"Lion","prior":30,"aliases":[]},{"canonical":"Tiger","prior":25,"aliases":[]},{"canonical":"Leopard","prior":12,"aliases":[]},{"canonical":"Jaguar","prior":10,"aliases":[]},{"canonical":"Cheetah","prior":10,"aliases":[]},{"canonical":"Snow leopard","prior":5,"aliases":[]},{"canonical":"Cougar","prior":4,"aliases":["Puma","Mountain lion"]},{"canonical":"Lynx","prior":1.5,"aliases":["Eurasian lynx","Canada lynx"]},{"canonical":"Clouded leopard","prior":1.5,"aliases":[]},{"canonical":"Bobcat","prior":0.5,"aliases":[]},{"canonical":"Ocelot","prior":0.5,"aliases":[]},{"canonical":"Serval","prior":0.5,"aliases":[]},{"canonical":"Caracal","prior":0.5,"aliases":[]},{"canonical":"Iberian lynx","prior":0.3,"aliases":[]},{"canonical":"Margay","prior":0.2,"aliases":[]},{"canonical":"Sand cat","prior":0.2,"aliases":[]},{"canonical":"Pallas''s cat","prior":0.2,"aliases":["Manul","Pallas cat"]},{"canonical":"Fishing cat","prior":0.2,"aliases":[]},{"canonical":"Black-footed cat","prior":0.2,"aliases":[]},{"canonical":"Jaguarundi","prior":0.2,"aliases":[]},{"canonical":"Rusty-spotted cat","prior":0.2,"aliases":[]},{"canonical":"Wildcat","prior":0.2,"aliases":["European wildcat","African wildcat"]},{"canonical":"Leopard cat","prior":0.1,"aliases":[]},{"canonical":"Jungle cat","prior":0.1,"aliases":[]},{"canonical":"Andean mountain cat","prior":0.1,"aliases":[]},{"canonical":"Kodkod","prior":0.1,"aliases":[]},{"canonical":"Oncilla","prior":0.1,"aliases":[]},{"canonical":"African golden cat","prior":0.1,"aliases":[]},{"canonical":"Asian golden cat","prior":0.1,"aliases":[]},{"canonical":"Flat-headed cat","prior":0.1,"aliases":[]},{"canonical":"Marbled cat","prior":0.1,"aliases":[]},{"canonical":"Geoffroy''s cat","prior":0.1,"aliases":["Geoffroys cat"]},{"canonical":"Bay cat","prior":0.05,"aliases":["Bornean bay cat"]}]', NULL, 'Think of small cats with big ears, the spotted cats of South America, and cats that go fishing.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-wings', 'Name a bird that cannot fly.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'About 60 living bird species are flightless. The kākāpō of New Zealand is the only flightless parrot, and the heaviest parrot in the world.', 'https://en.wikipedia.org/wiki/Flightless_bird', 'Wikipedia: Flightless bird', '2026-11-21', 'CC BY-SA 4.0', 'nature', 1, 0, '[{"canonical":"Penguin","prior":30,"aliases":["Penguins","Emperor penguin","King penguin","Adelie penguin","Gentoo penguin"]},{"canonical":"Ostrich","prior":25,"aliases":[]},{"canonical":"Emu","prior":15,"aliases":[]},{"canonical":"Kiwi","prior":12,"aliases":[]},{"canonical":"Dodo","prior":6,"aliases":[]},{"canonical":"Cassowary","prior":6,"aliases":[]},{"canonical":"Rhea","prior":2,"aliases":[]},{"canonical":"Kākāpō","prior":2,"aliases":["Kakapo"]},{"canonical":"Moa","prior":0.5,"aliases":[]},{"canonical":"Takahē","prior":0.5,"aliases":["Takahe"]},{"canonical":"Weka","prior":0.3,"aliases":[]},{"canonical":"Flightless cormorant","prior":0.3,"aliases":["Galapagos cormorant"]},{"canonical":"Great auk","prior":0.3,"aliases":[]},{"canonical":"Elephant bird","prior":0.3,"aliases":[]},{"canonical":"Steamer duck","prior":0.2,"aliases":[]},{"canonical":"Inaccessible Island rail","prior":0.1,"aliases":[]}]', NULL, 'Think of New Zealand, Australia and birds that islands lost long ago.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-gestation', 'Name a member of the European Union.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The European Union has 27 member states. The United Kingdom left in 2020, so it does not count. The list is the public membership roll and is still marked unverified in this sample.', 'https://european-union.europa.eu/principles-countries-history/country-profiles_en', 'European Union', '2026-11-21', 'European Union public information', 'geography', 1, 0, '[{"canonical":"Austria","prior":2,"aliases":[]},{"canonical":"Belgium","prior":3,"aliases":[]},{"canonical":"Bulgaria","prior":1,"aliases":[]},{"canonical":"Croatia","prior":1,"aliases":[]},{"canonical":"Cyprus","prior":1,"aliases":[]},{"canonical":"Czechia","prior":2,"aliases":["Czech Republic"]},{"canonical":"Denmark","prior":3,"aliases":[]},{"canonical":"Estonia","prior":1,"aliases":[]},{"canonical":"Finland","prior":2,"aliases":[]},{"canonical":"France","prior":14,"aliases":[]},{"canonical":"Germany","prior":14,"aliases":[]},{"canonical":"Greece","prior":4,"aliases":[]},{"canonical":"Hungary","prior":2,"aliases":[]},{"canonical":"Ireland","prior":3,"aliases":[]},{"canonical":"Italy","prior":8,"aliases":[]},{"canonical":"Latvia","prior":1,"aliases":[]},{"canonical":"Lithuania","prior":1,"aliases":[]},{"canonical":"Luxembourg","prior":2,"aliases":[]},{"canonical":"Malta","prior":1,"aliases":[]},{"canonical":"Netherlands","prior":4,"aliases":[]},{"canonical":"Poland","prior":4,"aliases":[]},{"canonical":"Portugal","prior":3,"aliases":[]},{"canonical":"Romania","prior":2,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Slovenia","prior":1,"aliases":[]},{"canonical":"Spain","prior":8,"aliases":[]},{"canonical":"Sweden","prior":3,"aliases":[]}]', 'countries', 'Think of the Baltic states, and the countries that joined after 2004.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-un', 'Name a landlocked country.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are 44 landlocked UN member and observer states, counting the Vatican. Liechtenstein and Uzbekistan are doubly landlocked: every neighbour is landlocked too.', 'https://en.wikipedia.org/wiki/Landlocked_country', 'Wikipedia: Landlocked country', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Switzerland","prior":12,"aliases":[]},{"canonical":"Bolivia","prior":6,"aliases":[]},{"canonical":"Nepal","prior":6,"aliases":[]},{"canonical":"Austria","prior":4,"aliases":[]},{"canonical":"Mongolia","prior":4,"aliases":[]},{"canonical":"Paraguay","prior":4,"aliases":[]},{"canonical":"Afghanistan","prior":3,"aliases":[]},{"canonical":"Bhutan","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":3,"aliases":[]},{"canonical":"Czechia","prior":2,"aliases":["Czech Republic"]},{"canonical":"Ethiopia","prior":2,"aliases":[]},{"canonical":"Hungary","prior":2,"aliases":[]},{"canonical":"Luxembourg","prior":2,"aliases":[]},{"canonical":"Vatican City","prior":2,"aliases":["Vatican","Holy See"]},{"canonical":"Laos","prior":1.5,"aliases":[]},{"canonical":"Andorra","prior":1,"aliases":[]},{"canonical":"Armenia","prior":1,"aliases":[]},{"canonical":"Azerbaijan","prior":1,"aliases":[]},{"canonical":"Belarus","prior":1,"aliases":[]},{"canonical":"Botswana","prior":1,"aliases":[]},{"canonical":"Burkina Faso","prior":1,"aliases":[]},{"canonical":"Chad","prior":1,"aliases":[]},{"canonical":"Kyrgyzstan","prior":1,"aliases":[]},{"canonical":"Lesotho","prior":1,"aliases":[]},{"canonical":"Liechtenstein","prior":1,"aliases":[]},{"canonical":"Mali","prior":1,"aliases":[]},{"canonical":"Moldova","prior":1,"aliases":[]},{"canonical":"Niger","prior":1,"aliases":[]},{"canonical":"Rwanda","prior":1,"aliases":[]},{"canonical":"San Marino","prior":1,"aliases":[]},{"canonical":"Serbia","prior":1,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Uganda","prior":1,"aliases":[]},{"canonical":"Uzbekistan","prior":1,"aliases":[]},{"canonical":"Zambia","prior":1,"aliases":[]},{"canonical":"Zimbabwe","prior":1,"aliases":[]},{"canonical":"Burundi","prior":0.5,"aliases":[]},{"canonical":"Central African Republic","prior":0.5,"aliases":[]},{"canonical":"Malawi","prior":0.5,"aliases":[]},{"canonical":"North Macedonia","prior":0.5,"aliases":["Macedonia"]},{"canonical":"South Sudan","prior":0.5,"aliases":[]},{"canonical":"Tajikistan","prior":0.5,"aliases":[]},{"canonical":"Turkmenistan","prior":0.5,"aliases":[]},{"canonical":"Eswatini","prior":0.3,"aliases":["Swaziland"]}]', 'countries', 'Think of Africa''s interior, Central Asia and the Alps.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-canada', 'Name a permanent member of the United Nations Security Council.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The five permanent members are China, France, Russia, the United Kingdom, and the United States. Pending verification.', 'https://www.un.org/securitycouncil/content/current-members', 'United Nations Security Council', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"China","prior":6,"aliases":["PRC"]},{"canonical":"France","prior":6,"aliases":[]},{"canonical":"Russia","prior":6,"aliases":["Russian Federation"]},{"canonical":"United Kingdom","prior":6,"aliases":["UK","Britain"]},{"canonical":"United States","prior":6,"aliases":["USA","US","America"]}]', 'countries', 'Think of the winners of the Second World War.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-areas', 'Name a country that borders China.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'China borders 14 countries, tied with Russia for the most of any country. Its shortest land border is with Afghanistan, about 76 km.', 'https://www.cia.gov/the-world-factbook/countries/china/', 'CIA World Factbook: China', '2026-11-21', 'CIA World Factbook public domain', 'geography', 2, 0, '[{"canonical":"India","prior":20,"aliases":[]},{"canonical":"Russia","prior":15,"aliases":["Russian Federation"]},{"canonical":"Mongolia","prior":8,"aliases":[]},{"canonical":"Pakistan","prior":8,"aliases":[]},{"canonical":"Nepal","prior":8,"aliases":[]},{"canonical":"North Korea","prior":6,"aliases":["DPRK"]},{"canonical":"Vietnam","prior":6,"aliases":["Viet Nam"]},{"canonical":"Myanmar","prior":4,"aliases":["Burma"]},{"canonical":"Bhutan","prior":3,"aliases":[]},{"canonical":"Kazakhstan","prior":3,"aliases":[]},{"canonical":"Afghanistan","prior":2,"aliases":[]},{"canonical":"Laos","prior":2,"aliases":[]},{"canonical":"Kyrgyzstan","prior":1,"aliases":[]},{"canonical":"Tajikistan","prior":1,"aliases":[]}]', 'countries', 'Think of the Central Asian republics, and the countries along the Himalaya.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-russia', 'Name a country whose English name starts with S.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twenty-six UN member states start with S, more than any other letter. Scotland is a country within the United Kingdom, not a UN member, so it is not on the list.', 'https://www.un.org/en/about-us/member-states', 'United Nations member states', '2026-11-21', 'United Nations public information', 'geography', 1, 0, '[{"canonical":"Spain","prior":20,"aliases":[]},{"canonical":"Sweden","prior":12,"aliases":[]},{"canonical":"Switzerland","prior":10,"aliases":[]},{"canonical":"Saudi Arabia","prior":8,"aliases":[]},{"canonical":"South Africa","prior":8,"aliases":[]},{"canonical":"Singapore","prior":6,"aliases":[]},{"canonical":"South Korea","prior":4,"aliases":["Korea, Republic of"]},{"canonical":"Sri Lanka","prior":4,"aliases":[]},{"canonical":"Syria","prior":3,"aliases":[]},{"canonical":"Somalia","prior":2,"aliases":[]},{"canonical":"Sudan","prior":2,"aliases":[]},{"canonical":"Senegal","prior":2,"aliases":[]},{"canonical":"Serbia","prior":2,"aliases":[]},{"canonical":"Slovakia","prior":1,"aliases":[]},{"canonical":"Slovenia","prior":1,"aliases":[]},{"canonical":"South Sudan","prior":1,"aliases":[]},{"canonical":"Suriname","prior":1,"aliases":[]},{"canonical":"Sierra Leone","prior":1,"aliases":[]},{"canonical":"Samoa","prior":0.5,"aliases":[]},{"canonical":"San Marino","prior":0.5,"aliases":[]},{"canonical":"Seychelles","prior":0.5,"aliases":[]},{"canonical":"Solomon Islands","prior":0.3,"aliases":[]},{"canonical":"Saint Lucia","prior":0.3,"aliases":["St Lucia","St. Lucia"]},{"canonical":"Sao Tome and Principe","prior":0.2,"aliases":["São Tomé and Príncipe"]},{"canonical":"Saint Kitts and Nevis","prior":0.2,"aliases":["St Kitts and Nevis"]},{"canonical":"Saint Vincent and the Grenadines","prior":0.2,"aliases":["St Vincent and the Grenadines"]}]', 'countries', 'Think of Africa and the Caribbean, and countries that begin with ''Saint'' or ''South''.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-brazil', 'Name a country in South America.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twelve sovereign countries sit on the South American continent. French Guiana is not a country, so it is not accepted. Pending verification.', 'https://en.wikipedia.org/wiki/South_America', 'Wikipedia: South America', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Argentina","prior":6,"aliases":[]},{"canonical":"Bolivia","prior":2,"aliases":[]},{"canonical":"Brazil","prior":16,"aliases":[]},{"canonical":"Chile","prior":2,"aliases":[]},{"canonical":"Colombia","prior":2,"aliases":[]},{"canonical":"Ecuador","prior":2,"aliases":[]},{"canonical":"Guyana","prior":2,"aliases":[]},{"canonical":"Paraguay","prior":2,"aliases":[]},{"canonical":"Peru","prior":2,"aliases":[]},{"canonical":"Suriname","prior":2,"aliases":[]},{"canonical":"Uruguay","prior":2,"aliases":[]},{"canonical":"Venezuela","prior":2,"aliases":[]}]', 'countries', 'Think of the small countries on the north coast, and the ones along the Andes.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-c14', 'Name a chemical element that is a gas at room temperature.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Eleven elements are gases at 25 °C and normal pressure: the six noble gases plus hydrogen, nitrogen, oxygen, fluorine and chlorine. Oganesson is too short-lived to say.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 1, 0, '[{"canonical":"Oxygen","prior":18,"aliases":[]},{"canonical":"Hydrogen","prior":15,"aliases":[]},{"canonical":"Helium","prior":14,"aliases":[]},{"canonical":"Nitrogen","prior":10,"aliases":[]},{"canonical":"Chlorine","prior":5,"aliases":[]},{"canonical":"Neon","prior":4,"aliases":[]},{"canonical":"Argon","prior":3,"aliases":[]},{"canonical":"Fluorine","prior":2,"aliases":[]},{"canonical":"Krypton","prior":2,"aliases":[]},{"canonical":"Xenon","prior":1.5,"aliases":[]},{"canonical":"Radon","prior":1,"aliases":[]}]', 'elements', 'Think of the right-hand side of the periodic table, and what the air is made of.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-melt', 'Name an alkaline earth metal.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Group 2 is beryllium, magnesium, calcium, strontium, barium, and radium. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Beryllium","prior":2,"aliases":[]},{"canonical":"Magnesium","prior":8,"aliases":[]},{"canonical":"Calcium","prior":8,"aliases":[]},{"canonical":"Strontium","prior":2,"aliases":[]},{"canonical":"Barium","prior":2,"aliases":[]},{"canonical":"Radium","prior":2,"aliases":[]}]', 'elements', 'They sit in the second column of the periodic table. One of them is in your bones.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-metals', 'Name a metal element used in coins.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Most modern coins are alloys. The US nickel is 75% copper, and the euro''s gold-coloured coins are Nordic gold: copper, aluminium, zinc and tin.', 'https://en.wikipedia.org/wiki/Coin_metal', 'Wikipedia: Coin metal', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '[{"canonical":"Copper","prior":20,"aliases":[]},{"canonical":"Gold","prior":15,"aliases":[]},{"canonical":"Silver","prior":15,"aliases":[]},{"canonical":"Nickel","prior":14,"aliases":[]},{"canonical":"Zinc","prior":8,"aliases":[]},{"canonical":"Aluminum","prior":4,"aliases":["Aluminium"]},{"canonical":"Iron","prior":2,"aliases":[]},{"canonical":"Tin","prior":2,"aliases":[]},{"canonical":"Manganese","prior":1,"aliases":[]},{"canonical":"Platinum","prior":1,"aliases":[]},{"canonical":"Palladium","prior":0.5,"aliases":[]},{"canonical":"Chromium","prior":0.3,"aliases":[]}]', 'elements', 'Think of what coins are plated with, and the metals that keep them from rusting.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-sound', 'Name a chemical element named after a place.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Four elements are named after one Swedish village, Ytterby: yttrium, ytterbium, terbium and erbium. Copper comes from the Latin for Cyprus.', 'https://en.wikipedia.org/wiki/List_of_chemical_element_name_etymologies', 'Wikipedia: List of chemical element name etymologies', '2026-11-21', 'CC BY-SA 4.0', 'science', 3, 0, '[{"canonical":"Francium","prior":8,"aliases":[]},{"canonical":"Polonium","prior":8,"aliases":[]},{"canonical":"Americium","prior":6,"aliases":[]},{"canonical":"Californium","prior":5,"aliases":[]},{"canonical":"Germanium","prior":4,"aliases":[]},{"canonical":"Europium","prior":3,"aliases":[]},{"canonical":"Gallium","prior":3,"aliases":[]},{"canonical":"Berkelium","prior":2,"aliases":[]},{"canonical":"Scandium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Hassium","prior":0.5,"aliases":[]},{"canonical":"Dubnium","prior":0.5,"aliases":[]},{"canonical":"Ruthenium","prior":0.5,"aliases":[]},{"canonical":"Strontium","prior":0.5,"aliases":[]},{"canonical":"Yttrium","prior":0.5,"aliases":[]},{"canonical":"Ytterbium","prior":0.5,"aliases":[]},{"canonical":"Terbium","prior":0.5,"aliases":[]},{"canonical":"Erbium","prior":0.5,"aliases":[]},{"canonical":"Lutetium","prior":0.3,"aliases":[]},{"canonical":"Hafnium","prior":0.3,"aliases":[]},{"canonical":"Holmium","prior":0.3,"aliases":[]},{"canonical":"Rhenium","prior":0.3,"aliases":[]},{"canonical":"Magnesium","prior":0.3,"aliases":[]},{"canonical":"Copper","prior":0.2,"aliases":[]}]', 'elements', 'Think of countries, US states, a Swedish village and whole continents.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-atomic', 'Name a chemical element whose symbol is a single letter.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fourteen elements use a one-letter symbol: H, B, C, N, O, F, P, S, K, V, Y, I, W, and U. Gold is Au and lead is Pb, so neither counts. Pending verification.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Hydrogen","prior":10,"aliases":[]},{"canonical":"Boron","prior":3,"aliases":[]},{"canonical":"Carbon","prior":12,"aliases":[]},{"canonical":"Nitrogen","prior":6,"aliases":[]},{"canonical":"Oxygen","prior":12,"aliases":[]},{"canonical":"Fluorine","prior":3,"aliases":[]},{"canonical":"Phosphorus","prior":2,"aliases":[]},{"canonical":"Sulfur","prior":3,"aliases":["Sulphur"]},{"canonical":"Potassium","prior":3,"aliases":[]},{"canonical":"Vanadium","prior":1,"aliases":[]},{"canonical":"Yttrium","prior":1,"aliases":[]},{"canonical":"Iodine","prior":4,"aliases":[]},{"canonical":"Tungsten","prior":2,"aliases":["Wolfram"]},{"canonical":"Uranium","prior":8,"aliases":[]}]', 'elements', 'Think of the elements your body is made of, and a few heavy metals.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-marathon', 'Name a sport at the Paris 2024 Summer Olympics.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Paris 2024 held 329 events across 32 sports. Breaking made its Olympic debut there and is not on the programme for Los Angeles 2028.', 'https://olympics.com/en/paris-2024/sports', 'Olympics.com: Paris 2024', '2026-11-21', 'IOC public information', 'culture', 1, 0, '[{"canonical":"Athletics","prior":20,"aliases":["Track and field","Running"]},{"canonical":"Swimming","prior":20,"aliases":[]},{"canonical":"Gymnastics","prior":12,"aliases":[]},{"canonical":"Basketball","prior":8,"aliases":[]},{"canonical":"Football","prior":8,"aliases":["Soccer"]},{"canonical":"Tennis","prior":5,"aliases":[]},{"canonical":"Boxing","prior":5,"aliases":[]},{"canonical":"Cycling","prior":4,"aliases":[]},{"canonical":"Volleyball","prior":4,"aliases":[]},{"canonical":"Rowing","prior":3,"aliases":[]},{"canonical":"Diving","prior":3,"aliases":[]},{"canonical":"Fencing","prior":2,"aliases":[]},{"canonical":"Archery","prior":2,"aliases":[]},{"canonical":"Judo","prior":2,"aliases":[]},{"canonical":"Wrestling","prior":2,"aliases":[]},{"canonical":"Weightlifting","prior":2,"aliases":[]},{"canonical":"Table tennis","prior":2,"aliases":["Ping pong"]},{"canonical":"Badminton","prior":2,"aliases":[]},{"canonical":"Sailing","prior":1,"aliases":[]},{"canonical":"Equestrian","prior":1,"aliases":["Horse riding","Show jumping","Dressage"]},{"canonical":"Shooting","prior":1,"aliases":[]},{"canonical":"Taekwondo","prior":1,"aliases":[]},{"canonical":"Handball","prior":1,"aliases":[]},{"canonical":"Hockey","prior":1,"aliases":["Field hockey"]},{"canonical":"Golf","prior":1,"aliases":[]},{"canonical":"Rugby sevens","prior":1,"aliases":["Rugby"]},{"canonical":"Canoeing","prior":1,"aliases":["Canoe","Kayaking"]},{"canonical":"Triathlon","prior":1,"aliases":[]},{"canonical":"Water polo","prior":1,"aliases":[]},{"canonical":"Skateboarding","prior":1,"aliases":[]},{"canonical":"Surfing","prior":1,"aliases":[]},{"canonical":"Beach volleyball","prior":1,"aliases":[]},{"canonical":"Sport climbing","prior":0.5,"aliases":["Climbing"]},{"canonical":"Breaking","prior":0.5,"aliases":["Breakdancing","Breakdance"]},{"canonical":"Modern pentathlon","prior":0.3,"aliases":["Pentathlon"]},{"canonical":"Artistic swimming","prior":0.3,"aliases":["Synchronised swimming","Synchronized swimming"]},{"canonical":"Trampoline","prior":0.3,"aliases":[]},{"canonical":"BMX","prior":0.3,"aliases":[]}]', NULL, 'Think of combat sports, sports on horseback, and the ones added in recent Games.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-premiere', 'Name a Nordic country.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'This sample treats the Nordic countries as Denmark, Finland, Iceland, Norway, and Sweden. Pending verification.', 'https://www.norden.org/en/information/facts-about-nordic-countries', 'Nordic Council', '2026-11-21', 'Nordic Council public information', 'geography', 1, 0, '[{"canonical":"Denmark","prior":4,"aliases":[]},{"canonical":"Finland","prior":4,"aliases":[]},{"canonical":"Iceland","prior":4,"aliases":[]},{"canonical":"Norway","prior":8,"aliases":[]},{"canonical":"Sweden","prior":8,"aliases":[]}]', 'countries', 'Think of Scandinavia and its neighbours out in the North Atlantic.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-works', 'Name a painting by Vincent van Gogh.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'Van Gogh made about 900 paintings in roughly a decade, most of them in his last two years. He sold very few while he was alive.', 'https://www.vangoghmuseum.nl/en/collection', 'Van Gogh Museum', '2026-11-21', 'Van Gogh Museum public collection', 'culture', 2, 0, '[{"canonical":"The Starry Night","prior":40,"aliases":["Starry Night"]},{"canonical":"Sunflowers","prior":20,"aliases":["The Sunflowers"]},{"canonical":"Self-Portrait with Bandaged Ear","prior":6,"aliases":["Self Portrait","Self-Portrait"]},{"canonical":"Café Terrace at Night","prior":4,"aliases":["Cafe Terrace at Night","Terrace of a Café at Night"]},{"canonical":"Bedroom in Arles","prior":4,"aliases":["The Bedroom"]},{"canonical":"The Potato Eaters","prior":3,"aliases":["Potato Eaters"]},{"canonical":"Irises","prior":3,"aliases":[]},{"canonical":"Wheatfield with Crows","prior":3,"aliases":["Wheat Field with Crows"]},{"canonical":"Almond Blossoms","prior":3,"aliases":["Almond Blossom"]},{"canonical":"Starry Night Over the Rhône","prior":2,"aliases":["Starry Night Over the Rhone"]},{"canonical":"The Night Café","prior":1.5,"aliases":["Night Cafe","The Night Cafe"]},{"canonical":"The Yellow House","prior":1,"aliases":[]},{"canonical":"Portrait of Dr. Gachet","prior":1,"aliases":["Dr Gachet","Portrait of Dr Gachet"]},{"canonical":"Wheat Field with Cypresses","prior":0.5,"aliases":[]},{"canonical":"The Red Vineyard","prior":0.5,"aliases":[]},{"canonical":"The Church at Auvers","prior":0.5,"aliases":[]},{"canonical":"Olive Trees","prior":0.5,"aliases":[]},{"canonical":"Cypresses","prior":0.3,"aliases":[]},{"canonical":"The Sower","prior":0.3,"aliases":[]},{"canonical":"Skull of a Skeleton with Burning Cigarette","prior":0.3,"aliases":[]},{"canonical":"Portrait of Joseph Roulin","prior":0.2,"aliases":[]},{"canonical":"L''Arlésienne","prior":0.2,"aliases":["LArlesienne","The Arlesienne"]},{"canonical":"The Mulberry Tree","prior":0.2,"aliases":[]},{"canonical":"Langlois Bridge","prior":0.2,"aliases":["The Langlois Bridge at Arles"]},{"canonical":"Peach Tree in Blossom","prior":0.1,"aliases":[]}]', NULL, 'Think of what he painted in Arles and at the asylum in Saint-Rémy.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-paintings', 'Name an Asian country with more than 50 million people.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'UN 2024 estimates. Russia is left off this sample list so the question stays about Asia. Egypt is counted with Africa. Pending verification.', 'https://population.un.org/wpp/', 'UN World Population Prospects 2024', '2026-11-21', 'United Nations public information', 'geography', 2, 0, '[{"canonical":"India","prior":24,"aliases":["Bharat"]},{"canonical":"China","prior":22,"aliases":["PRC","People''s Republic of China"]},{"canonical":"Indonesia","prior":6,"aliases":[]},{"canonical":"Pakistan","prior":4,"aliases":[]},{"canonical":"Bangladesh","prior":3,"aliases":[]},{"canonical":"Japan","prior":8,"aliases":[]},{"canonical":"Philippines","prior":2,"aliases":[]},{"canonical":"Vietnam","prior":2,"aliases":["Viet Nam"]},{"canonical":"Iran","prior":2,"aliases":[]},{"canonical":"Turkey","prior":3,"aliases":["Turkiye","Türkiye"]},{"canonical":"Thailand","prior":2,"aliases":[]},{"canonical":"Myanmar","prior":1,"aliases":["Burma"]},{"canonical":"South Korea","prior":3,"aliases":["Republic of Korea"]}]', 'countries', 'Think of the Middle East and Southeast Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-shakespeare', 'Name a play by William Shakespeare.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The First Folio of 1623 collected 36 plays. Modern editions usually add Pericles and The Two Noble Kinsmen, which Shakespeare co-wrote.', 'https://www.folger.edu/explore/shakespeares-works/', 'Folger Shakespeare Library', '2026-11-21', 'Folger Shakespeare Library public information', 'culture', 1, 0, '[{"canonical":"Romeo and Juliet","prior":30,"aliases":["Romeo & Juliet"]},{"canonical":"Hamlet","prior":25,"aliases":[]},{"canonical":"Macbeth","prior":15,"aliases":[]},{"canonical":"Othello","prior":6,"aliases":[]},{"canonical":"A Midsummer Night''s Dream","prior":6,"aliases":["Midsummer Nights Dream","A Midsummer Nights Dream"]},{"canonical":"King Lear","prior":5,"aliases":[]},{"canonical":"Julius Caesar","prior":4,"aliases":[]},{"canonical":"The Tempest","prior":3,"aliases":["Tempest"]},{"canonical":"The Merchant of Venice","prior":3,"aliases":["Merchant of Venice"]},{"canonical":"Twelfth Night","prior":2,"aliases":[]},{"canonical":"Much Ado About Nothing","prior":2,"aliases":[]},{"canonical":"As You Like It","prior":1.5,"aliases":[]},{"canonical":"The Taming of the Shrew","prior":1.5,"aliases":["Taming of the Shrew"]},{"canonical":"Richard III","prior":1,"aliases":["Richard the Third"]},{"canonical":"Henry V","prior":1,"aliases":["Henry the Fifth"]},{"canonical":"Antony and Cleopatra","prior":1,"aliases":[]},{"canonical":"The Winter''s Tale","prior":0.5,"aliases":["Winters Tale"]},{"canonical":"The Comedy of Errors","prior":0.4,"aliases":["Comedy of Errors"]},{"canonical":"Coriolanus","prior":0.3,"aliases":[]},{"canonical":"Titus Andronicus","prior":0.3,"aliases":[]},{"canonical":"Measure for Measure","prior":0.3,"aliases":[]},{"canonical":"All''s Well That Ends Well","prior":0.3,"aliases":["Alls Well That Ends Well"]},{"canonical":"Richard II","prior":0.3,"aliases":[]},{"canonical":"Henry IV, Part 1","prior":0.3,"aliases":["Henry IV","Henry IV Part 1"]},{"canonical":"Love''s Labour''s Lost","prior":0.2,"aliases":["Loves Labours Lost"]},{"canonical":"The Two Gentlemen of Verona","prior":0.2,"aliases":["Two Gentlemen of Verona"]},{"canonical":"The Merry Wives of Windsor","prior":0.2,"aliases":["Merry Wives of Windsor"]},{"canonical":"Henry IV, Part 2","prior":0.1,"aliases":["Henry IV Part 2"]},{"canonical":"Henry VI, Part 1","prior":0.1,"aliases":["Henry VI","Henry VI Part 1"]},{"canonical":"Henry VI, Part 2","prior":0.05,"aliases":["Henry VI Part 2"]},{"canonical":"Henry VI, Part 3","prior":0.05,"aliases":["Henry VI Part 3"]},{"canonical":"Henry VIII","prior":0.1,"aliases":[]},{"canonical":"King John","prior":0.1,"aliases":[]},{"canonical":"Troilus and Cressida","prior":0.1,"aliases":[]},{"canonical":"Timon of Athens","prior":0.1,"aliases":[]},{"canonical":"Pericles, Prince of Tyre","prior":0.1,"aliases":["Pericles"]},{"canonical":"Cymbeline","prior":0.1,"aliases":[]},{"canonical":"The Two Noble Kinsmen","prior":0.05,"aliases":["Two Noble Kinsmen"]}]', NULL, 'Think of the history plays about English kings, and the comedies.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-equator', 'Name a country the equator passes through.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The equator crosses 13 countries'' land or waters. Ecuador is named after it. In the Maldives it passes only through water between the atolls, so it is not counted here.', 'https://en.wikipedia.org/wiki/Equator', 'Wikipedia: Equator', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Ecuador","prior":25,"aliases":[]},{"canonical":"Brazil","prior":20,"aliases":[]},{"canonical":"Kenya","prior":10,"aliases":[]},{"canonical":"Indonesia","prior":10,"aliases":[]},{"canonical":"Colombia","prior":8,"aliases":[]},{"canonical":"Uganda","prior":5,"aliases":[]},{"canonical":"Democratic Republic of the Congo","prior":4,"aliases":["DR Congo","DRC","Congo-Kinshasa"]},{"canonical":"Gabon","prior":2,"aliases":[]},{"canonical":"Republic of the Congo","prior":2,"aliases":["Congo-Brazzaville","Congo"]},{"canonical":"Somalia","prior":2,"aliases":[]},{"canonical":"Kiribati","prior":1,"aliases":[]},{"canonical":"Sao Tome and Principe","prior":1,"aliases":["São Tomé and Príncipe"]}]', 'countries', 'Think of the middle of Africa, an island country in Southeast Asia, and the Pacific.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-span', 'Name a sovereign country in the Caribbean.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sovereign Caribbean states only. Territories such as Puerto Rico are not countries on this list. Pending verification.', 'https://en.wikipedia.org/wiki/Caribbean', 'Wikipedia: Caribbean', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Antigua and Barbuda","prior":2,"aliases":[]},{"canonical":"Bahamas","prior":2,"aliases":["The Bahamas"]},{"canonical":"Barbados","prior":2,"aliases":[]},{"canonical":"Cuba","prior":8,"aliases":[]},{"canonical":"Dominica","prior":2,"aliases":[]},{"canonical":"Dominican Republic","prior":2,"aliases":[]},{"canonical":"Grenada","prior":2,"aliases":[]},{"canonical":"Haiti","prior":2,"aliases":[]},{"canonical":"Jamaica","prior":8,"aliases":[]},{"canonical":"Saint Kitts and Nevis","prior":2,"aliases":[]},{"canonical":"Saint Lucia","prior":2,"aliases":[]},{"canonical":"Saint Vincent and the Grenadines","prior":2,"aliases":[]},{"canonical":"Trinidad and Tobago","prior":2,"aliases":[]}]', 'countries', 'Think of the islands that call themselves ''Saint'' or come in pairs.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-rocky', 'Name a desert.', 'name_one', NULL, 'lower', NULL, '[]', '[]', 'A desert is defined by how little rain falls, not by heat. By that measure the largest desert on Earth is Antarctica, and the Sahara is the largest hot one.', 'https://en.wikipedia.org/wiki/List_of_deserts_by_area', 'Wikipedia: List of deserts by area', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Sahara","prior":35,"aliases":["Sahara Desert"]},{"canonical":"Gobi","prior":12,"aliases":["Gobi Desert"]},{"canonical":"Kalahari","prior":8,"aliases":[]},{"canonical":"Atacama","prior":8,"aliases":[]},{"canonical":"Mojave","prior":5,"aliases":["Mohave"]},{"canonical":"Arabian Desert","prior":4,"aliases":["Arabian"]},{"canonical":"Antarctic Desert","prior":3,"aliases":["Antarctica","Antarctic"]},{"canonical":"Sonoran","prior":3,"aliases":[]},{"canonical":"Thar","prior":3,"aliases":["Great Indian Desert"]},{"canonical":"Namib","prior":3,"aliases":[]},{"canonical":"Taklamakan","prior":1.5,"aliases":["Taklimakan"]},{"canonical":"Great Victoria Desert","prior":1,"aliases":["Great Victoria"]},{"canonical":"Chihuahuan","prior":1,"aliases":[]},{"canonical":"Patagonian Desert","prior":1,"aliases":["Patagonian"]},{"canonical":"Arctic Desert","prior":1,"aliases":["Arctic"]},{"canonical":"Gibson Desert","prior":0.5,"aliases":["Gibson"]},{"canonical":"Simpson Desert","prior":0.5,"aliases":["Simpson"]},{"canonical":"Great Basin Desert","prior":0.5,"aliases":["Great Basin"]},{"canonical":"Karakum","prior":0.5,"aliases":["Kara Kum"]},{"canonical":"Syrian Desert","prior":0.5,"aliases":[]},{"canonical":"Rub'' al Khali","prior":0.5,"aliases":["Empty Quarter","Rub al Khali"]},{"canonical":"Great Sandy Desert","prior":0.5,"aliases":["Great Sandy"]},{"canonical":"Negev","prior":0.5,"aliases":[]},{"canonical":"Kyzylkum","prior":0.3,"aliases":["Kyzyl Kum"]},{"canonical":"Danakil","prior":0.3,"aliases":[]},{"canonical":"Tanami","prior":0.3,"aliases":[]},{"canonical":"Dasht-e Kavir","prior":0.2,"aliases":[]},{"canonical":"Dasht-e Lut","prior":0.2,"aliases":["Lut Desert"]},{"canonical":"Painted Desert","prior":0.2,"aliases":[]}]', NULL, 'Think of the poles, Australia''s interior and the deserts of Central Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-elements', 'Name a chemical element whose symbol comes from its Latin or German name.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Eleven elements have symbols that do not match their English names. Au is from the Latin aurum, Fe from ferrum, and W from the German Wolfram.', 'https://www.rsc.org/periodic-table', 'Royal Society of Chemistry periodic table', '2026-11-21', 'Royal Society of Chemistry periodic table', 'science', 2, 0, '[{"canonical":"Gold","prior":15,"aliases":[]},{"canonical":"Sodium","prior":15,"aliases":[]},{"canonical":"Iron","prior":14,"aliases":[]},{"canonical":"Potassium","prior":12,"aliases":[]},{"canonical":"Silver","prior":12,"aliases":[]},{"canonical":"Lead","prior":10,"aliases":[]},{"canonical":"Copper","prior":8,"aliases":[]},{"canonical":"Mercury","prior":8,"aliases":[]},{"canonical":"Tin","prior":4,"aliases":[]},{"canonical":"Tungsten","prior":4,"aliases":[]},{"canonical":"Antimony","prior":2,"aliases":[]}]', 'elements', 'Think of the metals people have known since ancient times.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-trenches', 'Name a chemical element with an atomic number greater than 92.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Uranium is 92. Everything past it, from neptunium to oganesson, was made in a lab or a reactor. The names follow the IUPAC table. Pending verification.', 'https://iupac.org/what-we-do/periodic-table-of-elements/', 'IUPAC', '2026-11-21', 'IUPAC', 'science', 2, 0, '[{"canonical":"Neptunium","prior":1,"aliases":[]},{"canonical":"Plutonium","prior":18,"aliases":[]},{"canonical":"Americium","prior":1,"aliases":[]},{"canonical":"Curium","prior":1,"aliases":[]},{"canonical":"Berkelium","prior":1,"aliases":[]},{"canonical":"Californium","prior":1,"aliases":[]},{"canonical":"Einsteinium","prior":1,"aliases":[]},{"canonical":"Fermium","prior":1,"aliases":[]},{"canonical":"Mendelevium","prior":1,"aliases":[]},{"canonical":"Nobelium","prior":1,"aliases":[]},{"canonical":"Lawrencium","prior":1,"aliases":[]},{"canonical":"Rutherfordium","prior":1,"aliases":[]},{"canonical":"Dubnium","prior":1,"aliases":[]},{"canonical":"Seaborgium","prior":1,"aliases":[]},{"canonical":"Bohrium","prior":1,"aliases":[]},{"canonical":"Hassium","prior":1,"aliases":[]},{"canonical":"Meitnerium","prior":1,"aliases":[]},{"canonical":"Darmstadtium","prior":1,"aliases":[]},{"canonical":"Roentgenium","prior":1,"aliases":[]},{"canonical":"Copernicium","prior":1,"aliases":[]},{"canonical":"Nihonium","prior":1,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Moscovium","prior":1,"aliases":[]},{"canonical":"Livermorium","prior":1,"aliases":[]},{"canonical":"Tennessine","prior":1,"aliases":[]},{"canonical":"Oganesson","prior":1,"aliases":[]}]', 'elements', 'Think of the bottom row, where elements are named after scientists, places and labs.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-moonwalkers', 'Name one of the twelve people who have walked on the Moon.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twelve men walked on the Moon between 1969 and 1972, all of them American. Gene Cernan was the last to climb back in, in December 1972, and Harrison Schmitt, a geologist, was the only professional scientist among them.', 'https://en.wikipedia.org/wiki/List_of_Apollo_astronauts', 'Wikipedia: List of Apollo astronauts', '2026-11-21', 'CC BY-SA 4.0', 'space', 2, 0, '[{"canonical":"Neil Armstrong","prior":50,"aliases":["Armstrong","Neil"]},{"canonical":"Buzz Aldrin","prior":30,"aliases":["Aldrin","Buzz","Edwin Aldrin"]},{"canonical":"Alan Shepard","prior":3,"aliases":["Shepard"]},{"canonical":"Pete Conrad","prior":2,"aliases":["Conrad","Charles Conrad"]},{"canonical":"Alan Bean","prior":2,"aliases":["Bean"]},{"canonical":"John Young","prior":2,"aliases":["Young"]},{"canonical":"Gene Cernan","prior":2,"aliases":["Eugene Cernan","Cernan"]},{"canonical":"Edgar Mitchell","prior":1,"aliases":["Mitchell"]},{"canonical":"David Scott","prior":1,"aliases":["Dave Scott","Scott"]},{"canonical":"James Irwin","prior":1,"aliases":["Jim Irwin","Irwin"]},{"canonical":"Charles Duke","prior":1,"aliases":["Charlie Duke","Duke"]},{"canonical":"Harrison Schmitt","prior":1,"aliases":["Jack Schmitt","Schmitt"]}]', NULL, 'Six Apollo missions landed, with two moonwalkers each. Think past the first crew.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-space-stars', 'Name a star other than the Sun.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sirius is the brightest star in the night sky. Polaris, the North Star, is only about the 48th brightest: it is famous for staying put, not for shining. Betelgeuse, Orion''s red shoulder, is so big that in the Sun''s place it would reach past the asteroid belt.', 'https://en.wikipedia.org/wiki/List_of_brightest_stars', 'Wikipedia: List of brightest stars', '2026-11-21', 'CC BY-SA 4.0', 'space', 1, 0, '[{"canonical":"Sirius","prior":18,"aliases":["Dog Star"]},{"canonical":"Polaris","prior":18,"aliases":["North Star","Pole Star","Dhruv","Dhruva","Dhruv Tara"]},{"canonical":"Betelgeuse","prior":10,"aliases":["Betelgeux"]},{"canonical":"Alpha Centauri","prior":8,"aliases":["Rigil Kentaurus"]},{"canonical":"Proxima Centauri","prior":6,"aliases":["Proxima"]},{"canonical":"Vega","prior":5,"aliases":[]},{"canonical":"Rigel","prior":5,"aliases":[]},{"canonical":"Arcturus","prior":3,"aliases":[]},{"canonical":"Aldebaran","prior":3,"aliases":[]},{"canonical":"Antares","prior":3,"aliases":[]},{"canonical":"Canopus","prior":3,"aliases":["Agastya"]},{"canonical":"Altair","prior":2,"aliases":[]},{"canonical":"Deneb","prior":2,"aliases":[]},{"canonical":"Capella","prior":1,"aliases":[]},{"canonical":"Procyon","prior":1,"aliases":[]},{"canonical":"Spica","prior":1,"aliases":["Chitra"]},{"canonical":"Pollux","prior":1,"aliases":[]},{"canonical":"Castor","prior":1,"aliases":[]},{"canonical":"Fomalhaut","prior":1,"aliases":[]},{"canonical":"Regulus","prior":1,"aliases":[]},{"canonical":"Bellatrix","prior":1,"aliases":[]},{"canonical":"Mizar","prior":0.5,"aliases":["Vashistha","Vasishtha"]},{"canonical":"Alcor","prior":0.5,"aliases":["Arundhati"]},{"canonical":"Algol","prior":0.5,"aliases":[]},{"canonical":"Mira","prior":0.5,"aliases":[]},{"canonical":"Achernar","prior":0.5,"aliases":[]},{"canonical":"Barnard''s Star","prior":0.5,"aliases":[]},{"canonical":"Eta Carinae","prior":0.5,"aliases":[]},{"canonical":"UY Scuti","prior":0.5,"aliases":[]},{"canonical":"VY Canis Majoris","prior":0.5,"aliases":[]}]', NULL, 'Think of the brightest dots in the night sky, the star sailors steer by, and Orion''s shoulders.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-five-oceans', 'Name one of Earth''s five oceans.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'They are really one connected world ocean. The Southern Ocean, around Antarctica, was the last to get a map of its own: National Geographic only started drawing it in 2021. The Pacific alone is bigger than all of Earth''s land put together.', 'https://en.wikipedia.org/wiki/Ocean', 'Wikipedia: Ocean', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Pacific Ocean","prior":30,"aliases":["Pacific"]},{"canonical":"Atlantic Ocean","prior":26,"aliases":["Atlantic"]},{"canonical":"Indian Ocean","prior":24,"aliases":["Indian"]},{"canonical":"Arctic Ocean","prior":12,"aliases":["Arctic"]},{"canonical":"Southern Ocean","prior":8,"aliases":["Southern","Antarctic Ocean","Antarctic"]}]', NULL, 'Think of the two poles.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-earth-layers', 'Name a layer of Earth''s atmosphere.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Nearly all weather happens in the troposphere, the bottom 8 to 15 km, and planes cruise near its top. The ozone layer sits in the stratosphere, and most meteors burn up in the mesosphere. The dashed lines on your Ballpark climb mark where one layer hands over to the next.', 'https://en.wikipedia.org/wiki/Atmosphere_of_Earth', 'Wikipedia: Atmosphere of Earth', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Troposphere","prior":26,"aliases":[]},{"canonical":"Stratosphere","prior":24,"aliases":[]},{"canonical":"Mesosphere","prior":12,"aliases":[]},{"canonical":"Thermosphere","prior":12,"aliases":[]},{"canonical":"Exosphere","prior":10,"aliases":[]},{"canonical":"Ionosphere","prior":8,"aliases":[]},{"canonical":"Ozone layer","prior":6,"aliases":["Ozone"]},{"canonical":"Homosphere","prior":0.5,"aliases":[]},{"canonical":"Heterosphere","prior":0.5,"aliases":[]}]', NULL, 'Most of them end in -sphere.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-muscle', 'Name a muscle in the human body. Flexing while you answer is optional.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The gluteus maximus is the body''s biggest muscle, and the masseter in your jaw is often called the strongest for its size. The smallest is the stapedius, about a millimetre long, which steadies the tiniest bone in your ear.', 'https://en.wikipedia.org/wiki/List_of_skeletal_muscles_of_the_human_body', 'Wikipedia: List of skeletal muscles of the human body', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Biceps","prior":26,"aliases":["Bicep","Biceps brachii"]},{"canonical":"Triceps","prior":12,"aliases":["Tricep","Triceps brachii"]},{"canonical":"Heart","prior":6,"aliases":["Cardiac muscle"]},{"canonical":"Quadriceps","prior":6,"aliases":["Quads","Quad","Quadricep"]},{"canonical":"Abdominals","prior":6,"aliases":["Abs","Rectus abdominis","Six pack"]},{"canonical":"Hamstrings","prior":5,"aliases":["Hamstring"]},{"canonical":"Pectoralis major","prior":5,"aliases":["Pecs","Pectorals","Pectoral","Chest muscle"]},{"canonical":"Gluteus maximus","prior":5,"aliases":["Glutes","Glute","Gluteus"]},{"canonical":"Deltoid","prior":4,"aliases":["Deltoids","Delts","Shoulder muscle"]},{"canonical":"Calf muscle","prior":4,"aliases":["Calf","Calves","Gastrocnemius"]},{"canonical":"Trapezius","prior":3,"aliases":["Traps","Trap"]},{"canonical":"Diaphragm","prior":3,"aliases":[]},{"canonical":"Tongue","prior":3,"aliases":[]},{"canonical":"Latissimus dorsi","prior":2,"aliases":["Lats","Lat"]},{"canonical":"Obliques","prior":1,"aliases":["Oblique","External oblique"]},{"canonical":"Masseter","prior":1,"aliases":["Jaw muscle"]},{"canonical":"Sartorius","prior":0.5,"aliases":[]},{"canonical":"Soleus","prior":0.5,"aliases":[]},{"canonical":"Stapedius","prior":0.5,"aliases":[]}]', NULL, 'Think of the jaw, the ear and the thigh, and one muscle that never rests.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-body-hormone', 'Name a hormone your body makes.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Ghrelin, made in your stomach, says you are hungry and leptin, made by fat cells, says you are full. Insulin was the first hormone used as a medicine: in January 1922 a 14-year-old boy in Toronto became the first person treated with it.', 'https://en.wikipedia.org/wiki/List_of_human_hormones', 'Wikipedia: List of human hormones', '2026-11-21', 'CC BY-SA 4.0', 'body', 1, 0, '[{"canonical":"Adrenaline","prior":20,"aliases":["Epinephrine"]},{"canonical":"Insulin","prior":18,"aliases":[]},{"canonical":"Testosterone","prior":12,"aliases":[]},{"canonical":"Oestrogen","prior":10,"aliases":["Estrogen","Estradiol","Oestradiol"]},{"canonical":"Dopamine","prior":8,"aliases":[]},{"canonical":"Serotonin","prior":6,"aliases":[]},{"canonical":"Cortisol","prior":6,"aliases":[]},{"canonical":"Melatonin","prior":5,"aliases":[]},{"canonical":"Oxytocin","prior":5,"aliases":[]},{"canonical":"Growth hormone","prior":3,"aliases":["Human growth hormone","HGH","Somatotropin"]},{"canonical":"Thyroxine","prior":3,"aliases":["Thyroid hormone","T4"]},{"canonical":"Progesterone","prior":3,"aliases":[]},{"canonical":"Glucagon","prior":2,"aliases":[]},{"canonical":"Endorphins","prior":2,"aliases":["Endorphin"]},{"canonical":"Leptin","prior":1,"aliases":[]},{"canonical":"Ghrelin","prior":1,"aliases":[]},{"canonical":"Noradrenaline","prior":1,"aliases":["Norepinephrine"]},{"canonical":"Prolactin","prior":1,"aliases":[]},{"canonical":"Vasopressin","prior":0.5,"aliases":["Antidiuretic hormone","ADH"]},{"canonical":"Erythropoietin","prior":0.5,"aliases":["EPO"]},{"canonical":"Aldosterone","prior":0.5,"aliases":[]},{"canonical":"Calcitonin","prior":0.5,"aliases":[]},{"canonical":"Parathyroid hormone","prior":0.5,"aliases":["PTH"]}]', NULL, 'Think of hunger, sleep, stress, growth and love.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-woodwind', 'Name a woodwind instrument. Some of them are made of metal, awkwardly.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'What makes a woodwind is how the note starts, by blowing across an edge or through a reed, not what it is made of. That is why the metal flute and saxophone count, while the wooden didgeridoo, played by buzzing the lips, is closer to a trumpet.', 'https://en.wikipedia.org/wiki/Woodwind_instrument', 'Wikipedia: Woodwind instrument', '2026-11-21', 'CC BY-SA 4.0', 'music', 1, 0, '[{"canonical":"Flute","prior":26,"aliases":["Flutes"]},{"canonical":"Clarinet","prior":18,"aliases":[]},{"canonical":"Saxophone","prior":14,"aliases":["Sax"]},{"canonical":"Oboe","prior":8,"aliases":[]},{"canonical":"Bassoon","prior":6,"aliases":[]},{"canonical":"Recorder","prior":6,"aliases":[]},{"canonical":"Piccolo","prior":4,"aliases":[]},{"canonical":"Bansuri","prior":4,"aliases":[]},{"canonical":"Shehnai","prior":3,"aliases":["Shehnaai","Shahnai"]},{"canonical":"Bagpipes","prior":2,"aliases":["Bagpipe"]},{"canonical":"Cor anglais","prior":1,"aliases":["English horn"]},{"canonical":"Pan flute","prior":1,"aliases":["Panpipes","Pan pipes"]},{"canonical":"Nadaswaram","prior":1,"aliases":["Nagaswaram","Nathaswaram"]},{"canonical":"Ocarina","prior":1,"aliases":[]},{"canonical":"Contrabassoon","prior":0.5,"aliases":["Double bassoon"]},{"canonical":"Fife","prior":0.5,"aliases":[]},{"canonical":"Tin whistle","prior":0.5,"aliases":["Penny whistle"]},{"canonical":"Duduk","prior":0.5,"aliases":[]}]', NULL, 'Think of Indian weddings, Scottish pipers and Andean bands.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-inv-browser', 'Name a web browser, past or present. Pour one out for the fallen.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The first browser, WorldWideWeb, was written by Tim Berners-Lee in 1990 and later renamed Nexus. Mosaic made the web point-and-click in 1993, and part of its team went on to build Netscape. Google, for the record, is a search engine.', 'https://en.wikipedia.org/wiki/History_of_the_web_browser', 'Wikipedia: History of the web browser', '2026-11-21', 'CC BY-SA 4.0', 'technology', 1, 0, '[{"canonical":"Google Chrome","prior":30,"aliases":["Chrome"]},{"canonical":"Mozilla Firefox","prior":14,"aliases":["Firefox"]},{"canonical":"Safari","prior":12,"aliases":["Apple Safari"]},{"canonical":"Microsoft Edge","prior":10,"aliases":["Edge"]},{"canonical":"Internet Explorer","prior":10,"aliases":["IE","Explorer"]},{"canonical":"Opera","prior":6,"aliases":["Opera Mini","Opera GX"]},{"canonical":"Brave","prior":4,"aliases":[]},{"canonical":"UC Browser","prior":4,"aliases":["UC"]},{"canonical":"Netscape Navigator","prior":2,"aliases":["Netscape"]},{"canonical":"Samsung Internet","prior":2,"aliases":[]},{"canonical":"DuckDuckGo","prior":1,"aliases":[]},{"canonical":"Tor Browser","prior":1,"aliases":["Tor"]},{"canonical":"Vivaldi","prior":1,"aliases":[]},{"canonical":"Arc","prior":1,"aliases":["Arc browser"]},{"canonical":"Mosaic","prior":0.5,"aliases":["NCSA Mosaic"]},{"canonical":"WorldWideWeb","prior":0.5,"aliases":["Nexus"]},{"canonical":"Chromium","prior":0.5,"aliases":[]},{"canonical":"Lynx","prior":0.5,"aliases":[]},{"canonical":"Yandex Browser","prior":0.5,"aliases":["Yandex"]},{"canonical":"Konqueror","prior":0.5,"aliases":[]}]', NULL, 'Think of the 1990s, browsers built for privacy, and the one that came with your phone.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-pyramids', 'Name a country with ancient pyramids. The one with the most is not the one you think.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sudan has roughly 200 to 255 Nubian pyramids, built for the kings and queens of Kush, around double Egypt''s count. They are smaller and steeper. Rome has one too: the Pyramid of Cestius, a tomb from about 12 BC.', 'https://en.wikipedia.org/wiki/Nubian_pyramids', 'Wikipedia: Nubian pyramids', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0, '[{"canonical":"Egypt","prior":50,"aliases":[]},{"canonical":"Mexico","prior":18,"aliases":[]},{"canonical":"Sudan","prior":5,"aliases":[]},{"canonical":"Guatemala","prior":5,"aliases":[]},{"canonical":"Peru","prior":3,"aliases":[]},{"canonical":"Belize","prior":2,"aliases":[]},{"canonical":"Honduras","prior":2,"aliases":[]},{"canonical":"China","prior":2,"aliases":[]},{"canonical":"El Salvador","prior":1,"aliases":[]},{"canonical":"Italy","prior":1,"aliases":[]},{"canonical":"Cambodia","prior":1,"aliases":[]}]', 'countries', 'Think of Central America, Egypt''s southern neighbour, and Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-land-disney', 'Name a city with a Disney theme park.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Six Disney resorts hold twelve theme parks between them. Tokyo''s is the only one Disney does not own; a Japanese company runs it under licence. A seventh resort, on Yas Island in Abu Dhabi, was announced in 2025.', 'https://en.wikipedia.org/wiki/Walt_Disney_Parks_and_Resorts', 'Wikipedia: Walt Disney Parks and Resorts', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Orlando","prior":26,"aliases":["Florida","Walt Disney World","Disney World","Lake Buena Vista"]},{"canonical":"Paris","prior":22,"aliases":["Disneyland Paris","Marne-la-Vallée","Euro Disney"]},{"canonical":"Anaheim","prior":18,"aliases":["Los Angeles","LA","California","Disneyland"]},{"canonical":"Tokyo","prior":14,"aliases":["Urayasu","Tokyo Disneyland","Tokyo DisneySea"]},{"canonical":"Hong Kong","prior":10,"aliases":["Hong Kong Disneyland","Lantau"]},{"canonical":"Shanghai","prior":8,"aliases":["Shanghai Disneyland","Pudong"]}]', NULL, 'Think of both coasts of the United States, and three cities in East Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-ape', 'Name an ape. Monkeys need not apply.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Apes have no tail, which is the quickest way to tell them from monkeys. India has exactly one wild ape, the hoolock gibbon of the northeast, plus about 1.4 billion of the other kind.', 'https://en.wikipedia.org/wiki/Ape', 'Wikipedia: Ape', '2026-11-21', 'CC BY-SA 4.0', 'animals', 1, 0, '[{"canonical":"Chimpanzee","prior":28,"aliases":["Chimp","Chimps","Chimpanzees","Common chimpanzee"]},{"canonical":"Gorilla","prior":26,"aliases":["Gorillas","Mountain gorilla","Western gorilla","Eastern gorilla"]},{"canonical":"Orangutan","prior":18,"aliases":["Orangutans","Orang-utan","Orangutang"]},{"canonical":"Gibbon","prior":8,"aliases":["Gibbons","Hoolock gibbon","Hoolock"]},{"canonical":"Bonobo","prior":6,"aliases":["Pygmy chimpanzee"]},{"canonical":"Human","prior":4,"aliases":["Humans","Homo sapiens","People"]},{"canonical":"Siamang","prior":1,"aliases":[]}]', NULL, 'Think of the small apes that swing through the forests of Southeast Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-nat-shark', 'Name a kind of shark. Baby Shark does not count.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Sharks are older than trees: they show up in the fossil record around 450 million years ago, and the first trees came along about 385 million years ago. The whale shark is the biggest fish in the sea and lives mostly on plankton.', 'https://en.wikipedia.org/wiki/Shark', 'Wikipedia: Shark', '2026-11-21', 'CC BY-SA 4.0', 'animals', 1, 0, '[{"canonical":"Great white shark","prior":30,"aliases":["Great white","White shark"]},{"canonical":"Hammerhead shark","prior":18,"aliases":["Hammerhead","Great hammerhead"]},{"canonical":"Tiger shark","prior":10,"aliases":[]},{"canonical":"Whale shark","prior":10,"aliases":[]},{"canonical":"Bull shark","prior":6,"aliases":[]},{"canonical":"Mako shark","prior":4,"aliases":["Mako","Shortfin mako"]},{"canonical":"Basking shark","prior":3,"aliases":[]},{"canonical":"Nurse shark","prior":3,"aliases":[]},{"canonical":"Megalodon","prior":2,"aliases":[]},{"canonical":"Blue shark","prior":2,"aliases":[]},{"canonical":"Lemon shark","prior":2,"aliases":[]},{"canonical":"Thresher shark","prior":2,"aliases":["Thresher"]},{"canonical":"Greenland shark","prior":2,"aliases":[]},{"canonical":"Goblin shark","prior":2,"aliases":[]},{"canonical":"Blacktip reef shark","prior":1,"aliases":["Blacktip shark","Blacktip"]},{"canonical":"Oceanic whitetip shark","prior":1,"aliases":["Oceanic whitetip","Whitetip"]},{"canonical":"Leopard shark","prior":1,"aliases":[]},{"canonical":"Zebra shark","prior":1,"aliases":[]},{"canonical":"Dogfish","prior":1,"aliases":["Spiny dogfish","Spurdog"]},{"canonical":"Wobbegong","prior":0.5,"aliases":["Carpet shark"]},{"canonical":"Cookiecutter shark","prior":0.5,"aliases":["Cookiecutter"]},{"canonical":"Megamouth shark","prior":0.5,"aliases":["Megamouth"]},{"canonical":"Sand tiger shark","prior":0.5,"aliases":["Sand tiger","Grey nurse shark"]},{"canonical":"Frilled shark","prior":0.5,"aliases":[]},{"canonical":"Angel shark","prior":0.5,"aliases":[]},{"canonical":"Ganges shark","prior":0.5,"aliases":[]}]', NULL, 'Think of deep-sea oddballs, reef sharks named for their fins, and the biggest fish of all.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-red-white', 'Name a country whose flag uses only red and white.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Denmark''s Dannebrog is said to be the oldest national flag still in use. Monaco and Indonesia fly almost the same flag, red over white, and only the proportions differ; Poland''s is the same pair the other way up.', 'https://en.wikipedia.org/wiki/Flag_of_Denmark', 'Wikipedia: Flag of Denmark', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Japan","prior":22,"aliases":[]},{"canonical":"Canada","prior":20,"aliases":[]},{"canonical":"Switzerland","prior":10,"aliases":[]},{"canonical":"Poland","prior":8,"aliases":[]},{"canonical":"Indonesia","prior":8,"aliases":[]},{"canonical":"Denmark","prior":6,"aliases":[]},{"canonical":"Turkey","prior":6,"aliases":["Turkiye","Türkiye"]},{"canonical":"Austria","prior":5,"aliases":[]},{"canonical":"Singapore","prior":4,"aliases":[]},{"canonical":"Peru","prior":3,"aliases":[]},{"canonical":"Monaco","prior":3,"aliases":[]},{"canonical":"Tunisia","prior":2,"aliases":[]},{"canonical":"Bahrain","prior":2,"aliases":[]},{"canonical":"Latvia","prior":2,"aliases":[]},{"canonical":"Georgia","prior":2,"aliases":[]},{"canonical":"Tonga","prior":1,"aliases":[]},{"canonical":"Qatar","prior":1,"aliases":[]}]', 'countries', 'Think of the Gulf, Southeast Asia and the Baltics.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-geo-germany', 'Name a country that shares a land border with Germany.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Germany has nine neighbours, more than any other country that lies wholly in Europe. Denmark is its only neighbour to the north, and the Czech border runs along the Ore Mountains.', 'https://en.wikipedia.org/wiki/Germany', 'Wikipedia: Germany', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"France","prior":22,"aliases":[]},{"canonical":"Poland","prior":16,"aliases":[]},{"canonical":"Austria","prior":14,"aliases":[]},{"canonical":"Switzerland","prior":12,"aliases":[]},{"canonical":"Netherlands","prior":10,"aliases":["Holland"]},{"canonical":"Belgium","prior":8,"aliases":[]},{"canonical":"Denmark","prior":6,"aliases":[]},{"canonical":"Czechia","prior":6,"aliases":["Czech Republic"]},{"canonical":"Luxembourg","prior":4,"aliases":[]}]', 'countries', 'Think of the small countries to the west, and the ones to the east and south.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-people-elements', 'Name a chemical element named after a scientist.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Seaborgium and oganesson are the only elements named after people who were alive at the time. Glenn Seaborg liked to say he could get mail addressed in elements: seaborgium, lawrencium (for his lab), berkelium, californium, americium.', 'https://en.wikipedia.org/wiki/List_of_chemical_elements_named_after_people', 'Wikipedia: List of chemical elements named after people', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '[{"canonical":"Einsteinium","prior":24,"aliases":[]},{"canonical":"Curium","prior":14,"aliases":[]},{"canonical":"Mendelevium","prior":12,"aliases":[]},{"canonical":"Nobelium","prior":12,"aliases":[]},{"canonical":"Fermium","prior":6,"aliases":[]},{"canonical":"Rutherfordium","prior":6,"aliases":[]},{"canonical":"Bohrium","prior":5,"aliases":[]},{"canonical":"Copernicium","prior":4,"aliases":[]},{"canonical":"Meitnerium","prior":3,"aliases":[]},{"canonical":"Roentgenium","prior":2,"aliases":[]},{"canonical":"Seaborgium","prior":2,"aliases":[]},{"canonical":"Lawrencium","prior":2,"aliases":[]},{"canonical":"Oganesson","prior":2,"aliases":[]},{"canonical":"Flerovium","prior":1,"aliases":[]},{"canonical":"Gadolinium","prior":1,"aliases":[]}]', 'elements', 'Think of the bottom of the periodic table, where famous physicists and chemists live on.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-sci-lab-kit', 'Name a piece of equipment from a school science lab.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Bunsen burner was perfected in 1855 by Robert Bunsen''s lab technician, Peter Desaga, whose name never made it onto the label. Julius Petri did better: he came up with his dish in 1887 and it still carries his name.', 'https://en.wikipedia.org/wiki/Bunsen_burner', 'Wikipedia: Bunsen burner', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Beaker","prior":20,"aliases":["Beakers"]},{"canonical":"Test tube","prior":18,"aliases":["Test tubes"]},{"canonical":"Bunsen burner","prior":14,"aliases":["Bunsen","Burner"]},{"canonical":"Microscope","prior":10,"aliases":[]},{"canonical":"Conical flask","prior":6,"aliases":["Flask","Erlenmeyer flask","Round-bottom flask"]},{"canonical":"Measuring cylinder","prior":4,"aliases":["Graduated cylinder"]},{"canonical":"Pipette","prior":4,"aliases":["Pipet","Dropper"]},{"canonical":"Petri dish","prior":4,"aliases":["Petri plate"]},{"canonical":"Burette","prior":3,"aliases":["Buret"]},{"canonical":"Thermometer","prior":3,"aliases":[]},{"canonical":"Safety goggles","prior":2,"aliases":["Goggles","Lab goggles"]},{"canonical":"Litmus paper","prior":2,"aliases":["Litmus"]},{"canonical":"Funnel","prior":2,"aliases":[]},{"canonical":"Tripod","prior":2,"aliases":["Tripod stand"]},{"canonical":"Gauze","prior":1,"aliases":["Wire gauze"]},{"canonical":"Tongs","prior":1,"aliases":["Crucible tongs"]},{"canonical":"Crucible","prior":1,"aliases":[]},{"canonical":"Retort stand","prior":1,"aliases":["Clamp stand","Ring stand"]},{"canonical":"Test tube rack","prior":1,"aliases":[]},{"canonical":"Watch glass","prior":1,"aliases":[]},{"canonical":"Spatula","prior":1,"aliases":[]},{"canonical":"Mortar and pestle","prior":1,"aliases":["Pestle and mortar"]},{"canonical":"Balance","prior":1,"aliases":["Weighing scale","Electronic balance"]},{"canonical":"Magnifying glass","prior":1,"aliases":["Hand lens","Magnifier"]},{"canonical":"Evaporating dish","prior":0.5,"aliases":["Evaporating basin"]},{"canonical":"Centrifuge","prior":0.5,"aliases":[]},{"canonical":"Wash bottle","prior":0.5,"aliases":[]},{"canonical":"Desiccator","prior":0.5,"aliases":[]}]', NULL, 'Think of what you heated, measured, poured and peered through.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-potter', 'Name one of the seven Harry Potter books.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The first book was turned down by a dozen publishers before Bloomsbury took it on in 1997, reportedly after the chairman''s eight-year-old daughter read the first chapter and demanded more. In the US it was renamed Sorcerer''s Stone.', 'https://en.wikipedia.org/wiki/Harry_Potter', 'Wikipedia: Harry Potter', '2026-11-21', 'CC BY-SA 4.0', 'books', 1, 0, '[{"canonical":"Philosopher''s Stone","prior":26,"aliases":["Harry Potter and the Philosopher''s Stone","Sorcerer''s Stone","Harry Potter and the Sorcerer''s Stone"]},{"canonical":"Chamber of Secrets","prior":14,"aliases":["Harry Potter and the Chamber of Secrets"]},{"canonical":"Prisoner of Azkaban","prior":14,"aliases":["Harry Potter and the Prisoner of Azkaban"]},{"canonical":"Goblet of Fire","prior":14,"aliases":["Harry Potter and the Goblet of Fire"]},{"canonical":"Deathly Hallows","prior":14,"aliases":["Harry Potter and the Deathly Hallows"]},{"canonical":"Order of the Phoenix","prior":8,"aliases":["Harry Potter and the Order of the Phoenix"]},{"canonical":"Half-Blood Prince","prior":8,"aliases":["Harry Potter and the Half-Blood Prince"]}]', NULL, 'Think of the later books, from the tournament onwards.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-cul-world-cup', 'Name a country that has hosted the men''s FIFA World Cup.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Mexico became the first country to host three times when the 2026 tournament opened at the Estadio Azteca, sharing the job with the United States and Canada. Japan and South Korea split 2002, the first World Cup held in Asia.', 'https://en.wikipedia.org/wiki/FIFA_World_Cup_hosts', 'Wikipedia: FIFA World Cup hosts', '2026-11-21', 'CC BY-SA 4.0', 'sport', 2, 0, '[{"canonical":"Qatar","prior":14,"aliases":[]},{"canonical":"Brazil","prior":12,"aliases":[]},{"canonical":"Russia","prior":10,"aliases":[]},{"canonical":"Germany","prior":8,"aliases":["West Germany"]},{"canonical":"United States","prior":8,"aliases":["USA","US","U.S.","America","United States of America"]},{"canonical":"France","prior":6,"aliases":[]},{"canonical":"South Africa","prior":6,"aliases":[]},{"canonical":"Mexico","prior":5,"aliases":[]},{"canonical":"Canada","prior":4,"aliases":[]},{"canonical":"Japan","prior":4,"aliases":[]},{"canonical":"South Korea","prior":3,"aliases":["Korea","Republic of Korea"]},{"canonical":"Italy","prior":3,"aliases":[]},{"canonical":"Spain","prior":3,"aliases":[]},{"canonical":"Argentina","prior":3,"aliases":[]},{"canonical":"United Kingdom","prior":3,"aliases":["UK","England","Britain","Great Britain"]},{"canonical":"Uruguay","prior":2,"aliases":[]},{"canonical":"Sweden","prior":1,"aliases":[]},{"canonical":"Switzerland","prior":1,"aliases":[]},{"canonical":"Chile","prior":1,"aliases":[]}]', 'countries', 'Think of the very first tournaments in the 1930s, and of Asia this century.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-cancer', 'Name a country the Tropic of Cancer passes through.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'In India the Tropic of Cancer crosses eight states, from Gujarat to Mizoram. The line is not fixed, either: as Earth''s tilt slowly changes, it is creeping south by about 15 metres a year.', 'https://en.wikipedia.org/wiki/Tropic_of_Cancer', 'Wikipedia: Tropic of Cancer', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"India","prior":40,"aliases":["Bharat"]},{"canonical":"Egypt","prior":10,"aliases":[]},{"canonical":"Saudi Arabia","prior":10,"aliases":["KSA"]},{"canonical":"Mexico","prior":8,"aliases":[]},{"canonical":"China","prior":8,"aliases":["PRC"]},{"canonical":"Bangladesh","prior":6,"aliases":[]},{"canonical":"Oman","prior":3,"aliases":[]},{"canonical":"United Arab Emirates","prior":3,"aliases":["UAE"]},{"canonical":"Myanmar","prior":3,"aliases":["Burma"]},{"canonical":"Taiwan","prior":3,"aliases":[]},{"canonical":"Libya","prior":2,"aliases":[]},{"canonical":"Algeria","prior":2,"aliases":[]},{"canonical":"Niger","prior":1,"aliases":[]},{"canonical":"Mali","prior":1,"aliases":[]},{"canonical":"Mauritania","prior":1,"aliases":[]},{"canonical":"Bahamas","prior":1,"aliases":["The Bahamas"]},{"canonical":"Western Sahara","prior":0.5,"aliases":[]}]', NULL, 'Think of the Sahara, the Arabian Peninsula and Southeast Asia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-long-meridian', 'Name a country the Prime Meridian passes through. Greenwich is not a country.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'From the North Pole the line crosses just eight countries before it leaves the land at Tema in Ghana, with nothing but sea until Antarctica. The brass line at Greenwich is about 100 metres west of where GPS puts zero.', 'https://en.wikipedia.org/wiki/Prime_meridian', 'Wikipedia: Prime meridian', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"United Kingdom","prior":40,"aliases":["UK","England","Britain","Great Britain"]},{"canonical":"France","prior":18,"aliases":[]},{"canonical":"Spain","prior":14,"aliases":[]},{"canonical":"Ghana","prior":8,"aliases":[]},{"canonical":"Algeria","prior":6,"aliases":[]},{"canonical":"Mali","prior":4,"aliases":[]},{"canonical":"Burkina Faso","prior":4,"aliases":[]},{"canonical":"Togo","prior":4,"aliases":[]}]', 'countries', 'Think of West Africa.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-berry', 'Name a fruit that botanists call a berry. Warning: the strawberry is a fraud.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'To a botanist, a berry is a fleshy fruit grown from one flower with one ovary, usually with several seeds. That makes bananas, tomatoes, grapes and avocados berries, and melons and citrus count as modified berries. Strawberries and raspberries grow from flowers with many ovaries, so they are not.', 'https://en.wikipedia.org/wiki/Berry_(botany)', 'Wikipedia: Berry (botany)', '2026-11-21', 'CC BY-SA 4.0', 'food', 2, 0, '[{"canonical":"Banana","prior":22,"aliases":["Bananas"]},{"canonical":"Tomato","prior":14,"aliases":["Tomatoes"]},{"canonical":"Grape","prior":14,"aliases":["Grapes"]},{"canonical":"Blueberry","prior":10,"aliases":["Blueberries"]},{"canonical":"Avocado","prior":6,"aliases":["Avocados"]},{"canonical":"Kiwi","prior":5,"aliases":["Kiwifruit","Kiwi fruit"]},{"canonical":"Cranberry","prior":4,"aliases":["Cranberries"]},{"canonical":"Eggplant","prior":3,"aliases":["Aubergine","Brinjal","Baingan"]},{"canonical":"Chili pepper","prior":2,"aliases":["Chilli","Chili","Chile pepper","Hot pepper","Mirchi"]},{"canonical":"Bell pepper","prior":2,"aliases":["Capsicum","Sweet pepper"]},{"canonical":"Watermelon","prior":3,"aliases":["Watermelons"]},{"canonical":"Melon","prior":2,"aliases":["Melons","Cantaloupe","Muskmelon","Honeydew","Kharbooja"]},{"canonical":"Pumpkin","prior":2,"aliases":[]},{"canonical":"Cucumber","prior":2,"aliases":[]},{"canonical":"Gooseberry","prior":2,"aliases":["Gooseberries"]},{"canonical":"Blackcurrant","prior":1,"aliases":["Black currant"]},{"canonical":"Redcurrant","prior":1,"aliases":["Red currant"]},{"canonical":"Persimmon","prior":1,"aliases":[]},{"canonical":"Guava","prior":2,"aliases":[]},{"canonical":"Papaya","prior":1,"aliases":[]},{"canonical":"Date","prior":1,"aliases":["Dates"]},{"canonical":"Orange","prior":2,"aliases":["Oranges"]},{"canonical":"Lemon","prior":1,"aliases":[]},{"canonical":"Lime","prior":1,"aliases":[]},{"canonical":"Grapefruit","prior":0.5,"aliases":[]}]', NULL, 'Look past the fruit bowl. Plenty of the ''vegetables'' in your kitchen are berries in disguise.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-nut', 'Name a so-called nut that botanists say is not a true nut.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A true nut is a hard shell that never splits open, with one seed inside, like a hazelnut, chestnut or acorn. Peanuts are legumes, almonds and cashews are seeds from drupes, and a coconut is one giant drupe. Nature''s labelling department is a mess.', 'https://en.wikipedia.org/wiki/Nut_(fruit)', 'Wikipedia: Nut (fruit)', '2026-11-21', 'CC BY-SA 4.0', 'food', 2, 0, '[{"canonical":"Peanut","prior":28,"aliases":["Peanuts","Groundnut","Groundnuts","Moongphali"]},{"canonical":"Almond","prior":18,"aliases":["Almonds","Badam"]},{"canonical":"Cashew","prior":14,"aliases":["Cashews","Kaju"]},{"canonical":"Walnut","prior":10,"aliases":["Walnuts","Akhrot"]},{"canonical":"Pistachio","prior":8,"aliases":["Pistachios","Pista"]},{"canonical":"Coconut","prior":7,"aliases":["Coconuts"]},{"canonical":"Brazil nut","prior":4,"aliases":["Brazil nuts"]},{"canonical":"Pecan","prior":3,"aliases":["Pecans"]},{"canonical":"Pine nut","prior":3,"aliases":["Pine nuts","Chilgoza","Pinon"]},{"canonical":"Macadamia","prior":3,"aliases":["Macadamia nut","Macadamias"]},{"canonical":"Nutmeg","prior":1,"aliases":[]},{"canonical":"Tiger nut","prior":0.5,"aliases":["Tigernut","Chufa"]}]', NULL, 'Think of what goes into trail mix or a laddoo. Most of it is really a seed or a legume.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-cheese', 'Name a cheese that is named after a real place.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Cheddar is a village in Somerset, Gouda and Edam are Dutch towns, and Parmesan comes from Parma. India has its own: Bandel cheese, from Bandel in West Bengal. Mozzarella, paneer and feta are named after how they are made, not where.', 'https://en.wikipedia.org/wiki/List_of_cheeses', 'Wikipedia: List of cheeses', '2026-11-21', 'CC BY-SA 4.0', 'food', 1, 0, '[{"canonical":"Cheddar","prior":24,"aliases":[]},{"canonical":"Parmesan","prior":16,"aliases":["Parmigiano","Parmigiano Reggiano","Parmigiano-Reggiano"]},{"canonical":"Gouda","prior":10,"aliases":[]},{"canonical":"Brie","prior":8,"aliases":[]},{"canonical":"Camembert","prior":6,"aliases":[]},{"canonical":"Edam","prior":4,"aliases":[]},{"canonical":"Swiss cheese","prior":4,"aliases":["Swiss"]},{"canonical":"Roquefort","prior":3,"aliases":[]},{"canonical":"Gorgonzola","prior":3,"aliases":[]},{"canonical":"Stilton","prior":3,"aliases":[]},{"canonical":"Emmental","prior":3,"aliases":["Emmentaler","Emmenthal"]},{"canonical":"Gruyère","prior":3,"aliases":["Gruyere"]},{"canonical":"Manchego","prior":2,"aliases":[]},{"canonical":"Monterey Jack","prior":2,"aliases":["Monterey"]},{"canonical":"American cheese","prior":2,"aliases":["American"]},{"canonical":"Philadelphia","prior":2,"aliases":["Philadelphia cream cheese","Philly"]},{"canonical":"Wensleydale","prior":1,"aliases":[]},{"canonical":"Red Leicester","prior":1,"aliases":["Leicester"]},{"canonical":"Double Gloucester","prior":1,"aliases":["Gloucester"]},{"canonical":"Cheshire","prior":1,"aliases":[]},{"canonical":"Lancashire","prior":1,"aliases":[]},{"canonical":"Caerphilly","prior":0.5,"aliases":[]},{"canonical":"Limburger","prior":0.5,"aliases":[]},{"canonical":"Munster","prior":0.5,"aliases":["Muenster"]},{"canonical":"Comté","prior":0.5,"aliases":["Comte"]},{"canonical":"Asiago","prior":0.5,"aliases":[]},{"canonical":"Colby","prior":0.5,"aliases":[]},{"canonical":"Taleggio","prior":0.5,"aliases":[]},{"canonical":"Tilsit","prior":0.5,"aliases":["Tilsiter"]},{"canonical":"Jarlsberg","prior":0.5,"aliases":[]},{"canonical":"Pecorino Romano","prior":0.5,"aliases":["Romano"]},{"canonical":"Bandel","prior":0.5,"aliases":["Bandel cheese"]},{"canonical":"Kalimpong cheese","prior":0.5,"aliases":["Kalimpong"]}]', NULL, 'Picture a map of Europe. English counties and Dutch, French and Italian towns all lent their names.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-dish', 'Name a dish or drink that is named after a real person.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The sandwich is named after the 4th Earl of Sandwich, who reportedly wanted a meal he could eat without leaving the card table. Nachos are named after Ignacio ''Nacho'' Anaya, the cook who first made them, and Bengal''s ledikeni sweet after Lady Canning, wife of a Viceroy of India.', 'https://en.wikipedia.org/wiki/List_of_foods_named_after_people', 'Wikipedia: List of foods named after people', '2026-11-21', 'CC BY-SA 4.0', 'food', 2, 0, '[{"canonical":"Sandwich","prior":16,"aliases":["Sandwiches"]},{"canonical":"Margherita pizza","prior":12,"aliases":["Margherita","Pizza Margherita"]},{"canonical":"Nachos","prior":8,"aliases":["Nacho"]},{"canonical":"Caesar salad","prior":8,"aliases":["Caesar"]},{"canonical":"Eggs Benedict","prior":8,"aliases":["Benedict"]},{"canonical":"Beef Wellington","prior":6,"aliases":["Wellington"]},{"canonical":"Pavlova","prior":5,"aliases":[]},{"canonical":"Earl Grey","prior":5,"aliases":["Earl Grey tea"]},{"canonical":"Peach Melba","prior":4,"aliases":["Melba"]},{"canonical":"Beef Stroganoff","prior":4,"aliases":["Stroganoff"]},{"canonical":"Fettuccine Alfredo","prior":3,"aliases":["Alfredo","Fettuccine"]},{"canonical":"Granny Smith","prior":2,"aliases":["Granny Smith apple"]},{"canonical":"Carpaccio","prior":2,"aliases":[]},{"canonical":"Bellini","prior":1,"aliases":[]},{"canonical":"Lamington","prior":1,"aliases":["Lamingtons"]},{"canonical":"Graham cracker","prior":1,"aliases":["Graham crackers"]},{"canonical":"Salisbury steak","prior":1,"aliases":[]},{"canonical":"Oysters Rockefeller","prior":1,"aliases":["Rockefeller"]},{"canonical":"Crêpes Suzette","prior":1,"aliases":["Crepes Suzette","Crepe Suzette"]},{"canonical":"Praline","prior":0.5,"aliases":["Pralines"]},{"canonical":"Garibaldi biscuit","prior":0.5,"aliases":["Garibaldi"]},{"canonical":"Ledikeni","prior":1,"aliases":["Lady Kenny","Lady Canning"]},{"canonical":"Bloody Mary","prior":1,"aliases":[]},{"canonical":"Shirley Temple","prior":1,"aliases":[]},{"canonical":"Sachertorte","prior":0.5,"aliases":["Sacher torte","Sacher"]},{"canonical":"Tarte Tatin","prior":0.5,"aliases":["Tatin"]}]', NULL, 'Think of earls, dancers, opera singers and a gambling lord who did not want to leave the card table.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-flower', 'Name something we eat that is actually a flower or a flower bud.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Broccoli and cauliflower are bunches of flower buds picked before they bloom. Cloves are dried flower buds, saffron is part of a crocus flower, and an artichoke is one giant thistle bud.', 'https://en.wikipedia.org/wiki/Edible_flower', 'Wikipedia: Edible flower', '2026-11-21', 'CC BY-SA 4.0', 'food', 1, 0, '[{"canonical":"Broccoli","prior":30,"aliases":[]},{"canonical":"Cauliflower","prior":26,"aliases":["Gobhi","Phool gobhi"]},{"canonical":"Artichoke","prior":10,"aliases":["Globe artichoke","Artichokes"]},{"canonical":"Saffron","prior":6,"aliases":["Kesar"]},{"canonical":"Clove","prior":5,"aliases":["Cloves","Laung"]},{"canonical":"Capers","prior":4,"aliases":["Caper"]},{"canonical":"Banana flower","prior":4,"aliases":["Banana blossom"]},{"canonical":"Romanesco","prior":2,"aliases":[]},{"canonical":"Squash blossom","prior":2,"aliases":["Zucchini flower","Courgette flower","Pumpkin flower"]},{"canonical":"Broccolini","prior":1,"aliases":[]},{"canonical":"Hibiscus","prior":2,"aliases":[]},{"canonical":"Chamomile","prior":2,"aliases":["Camomile"]},{"canonical":"Rose","prior":2,"aliases":["Rose petals","Gulkand"]},{"canonical":"Lavender","prior":1,"aliases":[]},{"canonical":"Nasturtium","prior":0.5,"aliases":[]}]', NULL, 'Think of spices and vegetables that grow as buds, and petals that end up in tea.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-citrus', 'Name a citrus fruit. The more obscure, the more points.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Nearly every citrus is a cross of three wild ancestors: the citron, the pomelo and the mandarin. Sweet oranges, lemons and grapefruit are all hybrids, and Nagpur''s famous oranges are really mandarins.', 'https://en.wikipedia.org/wiki/Citrus', 'Wikipedia: Citrus', '2026-11-21', 'CC BY-SA 4.0', 'food', 1, 0, '[{"canonical":"Orange","prior":24,"aliases":["Oranges","Sweet orange"]},{"canonical":"Lemon","prior":22,"aliases":["Lemons","Nimbu"]},{"canonical":"Lime","prior":14,"aliases":["Limes","Key lime"]},{"canonical":"Mandarin","prior":8,"aliases":["Mandarins","Mandarin orange","Santra"]},{"canonical":"Grapefruit","prior":6,"aliases":[]},{"canonical":"Sweet lime","prior":4,"aliases":["Mosambi","Musambi","Mausambi","Sweet lemon"]},{"canonical":"Tangerine","prior":4,"aliases":["Tangerines"]},{"canonical":"Kinnow","prior":3,"aliases":[]},{"canonical":"Clementine","prior":3,"aliases":["Clementines"]},{"canonical":"Pomelo","prior":2,"aliases":["Pummelo","Chakotra","Shaddock"]},{"canonical":"Kumquat","prior":1,"aliases":["Cumquat"]},{"canonical":"Yuzu","prior":1,"aliases":[]},{"canonical":"Citron","prior":1,"aliases":["Etrog"]},{"canonical":"Bergamot","prior":1,"aliases":["Bergamot orange"]},{"canonical":"Blood orange","prior":1,"aliases":[]},{"canonical":"Satsuma","prior":1,"aliases":[]},{"canonical":"Calamansi","prior":0.5,"aliases":["Calamondin"]},{"canonical":"Finger lime","prior":0.5,"aliases":[]},{"canonical":"Tangelo","prior":0.5,"aliases":["Ugli fruit","Ugli"]},{"canonical":"Makrut lime","prior":0.5,"aliases":["Kaffir lime","Kafir lime"]}]', NULL, 'Think beyond the fruit bowl: Japanese kitchens, Indian juice carts and the flavour in a famous tea.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-ferment', 'Name a food or drink made by fermentation. Microbes did the cooking.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fermentation is microbes such as yeast and bacteria turning sugar into acid, gas or alcohol. Idli and dosa batter rises overnight thanks to wild ones, and every bar of chocolate starts as cacao beans left to ferment in heaps for about a week.', 'https://en.wikipedia.org/wiki/Fermentation_in_food_processing', 'Wikipedia: Fermentation in food processing', '2026-11-21', 'CC BY-SA 4.0', 'food', 1, 0, '[{"canonical":"Yogurt","prior":14,"aliases":["Yoghurt","Curd","Dahi"]},{"canonical":"Cheese","prior":10,"aliases":[]},{"canonical":"Idli","prior":8,"aliases":["Idly"]},{"canonical":"Bread","prior":8,"aliases":["Sourdough","Sourdough bread"]},{"canonical":"Dosa","prior":6,"aliases":["Dosai"]},{"canonical":"Beer","prior":6,"aliases":[]},{"canonical":"Wine","prior":6,"aliases":[]},{"canonical":"Kimchi","prior":5,"aliases":[]},{"canonical":"Dhokla","prior":3,"aliases":["Khaman"]},{"canonical":"Kombucha","prior":3,"aliases":[]},{"canonical":"Soy sauce","prior":3,"aliases":["Soya sauce"]},{"canonical":"Sauerkraut","prior":3,"aliases":[]},{"canonical":"Pickle","prior":3,"aliases":["Pickles","Achar","Achaar"]},{"canonical":"Buttermilk","prior":2,"aliases":["Chaas","Chhaas"]},{"canonical":"Appam","prior":2,"aliases":["Hoppers"]},{"canonical":"Vinegar","prior":2,"aliases":[]},{"canonical":"Miso","prior":2,"aliases":[]},{"canonical":"Kefir","prior":1,"aliases":[]},{"canonical":"Jalebi","prior":1,"aliases":[]},{"canonical":"Kanji","prior":1,"aliases":[]},{"canonical":"Chocolate","prior":1,"aliases":["Cocoa","Cacao"]},{"canonical":"Salami","prior":1,"aliases":[]},{"canonical":"Sake","prior":1,"aliases":[]},{"canonical":"Cider","prior":1,"aliases":[]},{"canonical":"Tempeh","prior":1,"aliases":[]},{"canonical":"Natto","prior":1,"aliases":[]}]', NULL, 'Think of a South Indian breakfast, a Korean side dish, or anything with a sour tang.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-joey', 'Name an animal whose baby is called a joey.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Every baby marsupial is a joey, from kangaroos to koalas to opossums. Baby echidnas, which hatch from eggs, are called puggles, which is objectively a better word.', 'https://en.wikipedia.org/wiki/Marsupial', 'Wikipedia: Marsupial', '2026-11-21', 'CC BY-SA 4.0', 'animals', 1, 0, '[{"canonical":"Kangaroo","prior":50,"aliases":["Kangaroos","Roo"]},{"canonical":"Koala","prior":14,"aliases":["Koalas"]},{"canonical":"Wallaby","prior":10,"aliases":["Wallabies"]},{"canonical":"Wombat","prior":6,"aliases":["Wombats"]},{"canonical":"Possum","prior":4,"aliases":["Brushtail possum"]},{"canonical":"Opossum","prior":3,"aliases":["Virginia opossum"]},{"canonical":"Tasmanian devil","prior":3,"aliases":[]},{"canonical":"Quokka","prior":3,"aliases":[]},{"canonical":"Sugar glider","prior":2,"aliases":[]},{"canonical":"Bandicoot","prior":1,"aliases":[]},{"canonical":"Bilby","prior":1,"aliases":[]},{"canonical":"Numbat","prior":1,"aliases":[]},{"canonical":"Quoll","prior":1,"aliases":[]},{"canonical":"Tree kangaroo","prior":1,"aliases":[]},{"canonical":"Wallaroo","prior":1,"aliases":[]},{"canonical":"Pademelon","prior":0.5,"aliases":[]},{"canonical":"Cuscus","prior":0.5,"aliases":[]},{"canonical":"Bettong","prior":0.5,"aliases":[]},{"canonical":"Potoroo","prior":0.5,"aliases":[]},{"canonical":"Dunnart","prior":0.5,"aliases":[]}]', NULL, 'They all carry their babies in a pouch, and almost all of them live in Australia.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-blue', 'Name an animal with blue blood. Royalty does not count.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'These animals carry oxygen with hemocyanin, a copper-based protein that turns blue when it picks up oxygen, instead of the iron-based hemoglobin in our red blood. Horseshoe crab blood is even collected to test medicines and vaccines for bacteria.', 'https://en.wikipedia.org/wiki/Hemocyanin', 'Wikipedia: Hemocyanin', '2026-11-21', 'CC BY-SA 4.0', 'animals', 2, 0, '[{"canonical":"Octopus","prior":34,"aliases":["Octopuses","Octopi"]},{"canonical":"Horseshoe crab","prior":16,"aliases":["Horseshoe crabs"]},{"canonical":"Squid","prior":12,"aliases":[]},{"canonical":"Crab","prior":8,"aliases":["Crabs"]},{"canonical":"Lobster","prior":7,"aliases":["Lobsters"]},{"canonical":"Spider","prior":4,"aliases":["Spiders","Tarantula"]},{"canonical":"Snail","prior":4,"aliases":["Snails"]},{"canonical":"Cuttlefish","prior":3,"aliases":[]},{"canonical":"Scorpion","prior":2,"aliases":["Scorpions"]},{"canonical":"Shrimp","prior":2,"aliases":["Prawn","Prawns"]},{"canonical":"Crayfish","prior":1,"aliases":["Crawfish","Crawdad"]},{"canonical":"Krill","prior":1,"aliases":[]},{"canonical":"Nautilus","prior":1,"aliases":[]},{"canonical":"Slug","prior":1,"aliases":["Slugs"]}]', NULL, 'Think of creatures with shells, eight legs or eight arms.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-brainless', 'Name a sea creature that gets through life without a brain.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Jellyfish, sea stars and sea urchins run on a loose net of nerves with no central brain, and sponges have no nerves at all. A starfish can still hunt and prise open a clam. It just never has to think about it.', 'https://en.wikipedia.org/wiki/Nerve_net', 'Wikipedia: Nerve net', '2026-11-21', 'CC BY-SA 4.0', 'animals', 2, 0, '[{"canonical":"Jellyfish","prior":40,"aliases":[]},{"canonical":"Starfish","prior":22,"aliases":["Sea star","Sea stars","Starfishes"]},{"canonical":"Sea sponge","prior":8,"aliases":["Sponge","Sponges"]},{"canonical":"Coral","prior":6,"aliases":["Corals"]},{"canonical":"Sea anemone","prior":5,"aliases":["Anemone"]},{"canonical":"Sea cucumber","prior":5,"aliases":[]},{"canonical":"Sea urchin","prior":4,"aliases":["Urchin"]},{"canonical":"Sand dollar","prior":2,"aliases":[]},{"canonical":"Oyster","prior":2,"aliases":["Oysters"]},{"canonical":"Clam","prior":2,"aliases":["Clams"]},{"canonical":"Mussel","prior":1,"aliases":["Mussels"]},{"canonical":"Scallop","prior":1,"aliases":["Scallops"]},{"canonical":"Comb jelly","prior":1,"aliases":["Ctenophore"]},{"canonical":"Portuguese man o'' war","prior":1,"aliases":["Man o'' war","Portuguese man of war","Bluebottle"]},{"canonical":"Brittle star","prior":0.5,"aliases":[]},{"canonical":"Sea lily","prior":0.5,"aliases":["Crinoid"]}]', NULL, 'Think of things that sit stuck to a reef, or drift wherever the tide takes them.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-regrow', 'Name an animal that can regrow a lost body part.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Axolotls can regrow legs, parts of their heart and even bits of their brain. Lizards drop their tails to escape and grow new ones, a planarian flatworm can regrow from a tiny piece, and deer grow a brand new set of antlers every year.', 'https://en.wikipedia.org/wiki/Regeneration_(biology)', 'Wikipedia: Regeneration (biology)', '2026-11-21', 'CC BY-SA 4.0', 'animals', 1, 0, '[{"canonical":"Starfish","prior":24,"aliases":["Sea star","Sea stars"]},{"canonical":"Lizard","prior":22,"aliases":["Lizards"]},{"canonical":"Axolotl","prior":12,"aliases":["Axolotls"]},{"canonical":"Salamander","prior":8,"aliases":["Salamanders"]},{"canonical":"Octopus","prior":6,"aliases":["Octopuses"]},{"canonical":"Gecko","prior":6,"aliases":["Geckos"]},{"canonical":"Earthworm","prior":4,"aliases":["Worm","Worms"]},{"canonical":"Flatworm","prior":3,"aliases":["Planarian","Planaria"]},{"canonical":"Crab","prior":3,"aliases":["Crabs"]},{"canonical":"Newt","prior":3,"aliases":["Newts"]},{"canonical":"Spider","prior":2,"aliases":["Spiders"]},{"canonical":"Deer","prior":2,"aliases":["Antlers"]},{"canonical":"Sea cucumber","prior":1,"aliases":[]},{"canonical":"Zebrafish","prior":1,"aliases":[]},{"canonical":"Lobster","prior":1,"aliases":[]},{"canonical":"Hydra","prior":1,"aliases":[]},{"canonical":"Sponge","prior":1,"aliases":["Sea sponge"]}]', NULL, 'Think of creatures that drop a tail to escape, or grow back an arm or even a head.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-zodiac', 'Name an animal from the Chinese zodiac.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The twelve animals repeat in a twelve-year cycle, starting with the Rat. Legend says the Rat won the Great Race by riding on the Ox''s back and jumping off at the finish line. The cat overslept and never made the list.', 'https://en.wikipedia.org/wiki/Chinese_zodiac', 'Wikipedia: Chinese zodiac', '2026-11-21', 'CC BY-SA 4.0', 'animals', 1, 0, '[{"canonical":"Dragon","prior":20,"aliases":[]},{"canonical":"Tiger","prior":14,"aliases":[]},{"canonical":"Rat","prior":10,"aliases":["Mouse"]},{"canonical":"Ox","prior":8,"aliases":["Cow","Buffalo","Bull"]},{"canonical":"Rabbit","prior":8,"aliases":["Hare"]},{"canonical":"Snake","prior":8,"aliases":[]},{"canonical":"Horse","prior":7,"aliases":[]},{"canonical":"Monkey","prior":7,"aliases":[]},{"canonical":"Goat","prior":6,"aliases":["Sheep","Ram"]},{"canonical":"Rooster","prior":5,"aliases":["Chicken","Hen","Cockerel"]},{"canonical":"Dog","prior":5,"aliases":[]},{"canonical":"Pig","prior":4,"aliases":["Boar","Hog"]}]', NULL, 'Twelve animals, one for each year. Think of the farmyard, the forest, and one creature that is not real.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-colour', 'Name an animal that can change colour. Mood swings optional.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Chameleons change colour mostly to show mood and control their temperature, not to hide, by stretching a layer of tiny crystals in their skin. Octopuses and cuttlefish can do it in under a second, which is impressive for animals that are mostly colour-blind.', 'https://en.wikipedia.org/wiki/Chameleon', 'Wikipedia: Chameleon', '2026-11-21', 'CC BY-SA 4.0', 'animals', 1, 0, '[{"canonical":"Chameleon","prior":40,"aliases":["Chameleons"]},{"canonical":"Octopus","prior":14,"aliases":["Octopuses","Octopi"]},{"canonical":"Cuttlefish","prior":8,"aliases":[]},{"canonical":"Squid","prior":5,"aliases":[]},{"canonical":"Arctic fox","prior":3,"aliases":[]},{"canonical":"Flounder","prior":2,"aliases":["Flatfish","Peacock flounder"]},{"canonical":"Seahorse","prior":2,"aliases":["Sea horse","Seahorses"]},{"canonical":"Anole","prior":2,"aliases":["Green anole","Anolis"]},{"canonical":"Tree frog","prior":2,"aliases":["Pacific tree frog","Grey tree frog","Gray tree frog"]},{"canonical":"Garden lizard","prior":2,"aliases":["Oriental garden lizard","Changeable lizard","Girgit"]},{"canonical":"Snowshoe hare","prior":1,"aliases":[]},{"canonical":"Mountain hare","prior":0.5,"aliases":[]},{"canonical":"Stoat","prior":1,"aliases":["Ermine","Short-tailed weasel"]},{"canonical":"Ptarmigan","prior":1,"aliases":["Willow ptarmigan","Rock ptarmigan"]},{"canonical":"Golden tortoise beetle","prior":1,"aliases":["Tortoise beetle"]},{"canonical":"Crab spider","prior":1,"aliases":["Goldenrod crab spider"]}]', NULL, 'Think of masters of camouflage in the sea, and animals that turn white for winter.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-old', 'Name an animal that can live for more than 100 years. You may nominate yourself.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Greenland shark is the longest-lived known vertebrate: one was estimated at 272 to 512 years old, and they only grow up at around 150. Jonathan, a giant tortoise on Saint Helena, hatched around 1832 and had an official 190th birthday party in 2022.', 'https://en.wikipedia.org/wiki/List_of_longest-living_organisms', 'Wikipedia: List of longest-living organisms', '2026-11-21', 'CC BY-SA 4.0', 'animals', 2, 0, '[{"canonical":"Tortoise","prior":30,"aliases":["Tortoises","Giant tortoise","Galapagos tortoise","Aldabra tortoise","Aldabra giant tortoise","Turtle"]},{"canonical":"Human","prior":10,"aliases":["Humans","People","Person","Me","Myself","Homo sapiens"]},{"canonical":"Greenland shark","prior":8,"aliases":[]},{"canonical":"Bowhead whale","prior":6,"aliases":["Bowhead"]},{"canonical":"Koi","prior":3,"aliases":["Koi carp"]},{"canonical":"Lobster","prior":2,"aliases":["Lobsters"]},{"canonical":"Ocean quahog","prior":2,"aliases":["Quahog","Clam","Ming the clam"]},{"canonical":"Lake sturgeon","prior":2,"aliases":["Sturgeon"]},{"canonical":"Immortal jellyfish","prior":2,"aliases":["Turritopsis","Turritopsis dohrnii"]},{"canonical":"Tuatara","prior":1,"aliases":[]},{"canonical":"Red sea urchin","prior":1,"aliases":["Sea urchin"]},{"canonical":"Tube worm","prior":1,"aliases":["Tubeworm"]},{"canonical":"Freshwater pearl mussel","prior":0.5,"aliases":["Pearl mussel"]},{"canonical":"Rougheye rockfish","prior":0.5,"aliases":["Rockfish"]},{"canonical":"Orange roughy","prior":0.5,"aliases":[]},{"canonical":"Glass sponge","prior":0.5,"aliases":["Sponge"]}]', NULL, 'Think slow, cold and armoured. Several record holders live in icy water.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-olympics', 'Name a country that has hosted the Summer Olympics.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Nineteen countries have hosted the Summer Games since Athens in 1896. The United States has done it four times, with Los Angeles up again in 2028. India has hosted the Asian Games and the Commonwealth Games, but never the Olympics.', 'https://en.wikipedia.org/wiki/Summer_Olympic_Games', 'Wikipedia: Summer Olympic Games', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"United States","prior":18,"aliases":["USA","US","U.S.","America","United States of America"]},{"canonical":"China","prior":12,"aliases":[]},{"canonical":"United Kingdom","prior":10,"aliases":["UK","Britain","Great Britain","England"]},{"canonical":"France","prior":10,"aliases":[]},{"canonical":"Japan","prior":10,"aliases":[]},{"canonical":"Greece","prior":8,"aliases":[]},{"canonical":"Australia","prior":8,"aliases":[]},{"canonical":"Brazil","prior":6,"aliases":[]},{"canonical":"Germany","prior":4,"aliases":["West Germany"]},{"canonical":"Spain","prior":3,"aliases":[]},{"canonical":"Russia","prior":3,"aliases":["Soviet Union","USSR"]},{"canonical":"Italy","prior":2,"aliases":[]},{"canonical":"Mexico","prior":2,"aliases":[]},{"canonical":"South Korea","prior":2,"aliases":["Korea","Republic of Korea"]},{"canonical":"Canada","prior":2,"aliases":[]},{"canonical":"Sweden","prior":1,"aliases":[]},{"canonical":"Netherlands","prior":1,"aliases":["Holland"]},{"canonical":"Belgium","prior":1,"aliases":[]},{"canonical":"Finland","prior":1,"aliases":[]}]', 'countries', 'The Games have been to every inhabited continent but Africa. Think beyond the big three.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-water', 'Name a Summer Olympic sport that happens in or on water.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Swimming, diving, water polo and artistic swimming share the pool, while rowing, canoeing, sailing and surfing take to open water. Beach volleyball has sand and sunscreen, but no water.', 'https://en.wikipedia.org/wiki/Olympic_sports', 'Wikipedia: Olympic sports', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Swimming","prior":40,"aliases":[]},{"canonical":"Diving","prior":14,"aliases":[]},{"canonical":"Water polo","prior":12,"aliases":[]},{"canonical":"Rowing","prior":8,"aliases":[]},{"canonical":"Artistic swimming","prior":5,"aliases":["Synchronised swimming","Synchronized swimming","Synchro"]},{"canonical":"Canoeing","prior":4,"aliases":["Canoe","Kayaking","Kayak","Canoe sprint","Canoe slalom"]},{"canonical":"Sailing","prior":4,"aliases":["Yachting"]},{"canonical":"Surfing","prior":4,"aliases":[]},{"canonical":"Marathon swimming","prior":2,"aliases":["Open water swimming"]},{"canonical":"Triathlon","prior":3,"aliases":[]}]', NULL, 'Think of boats, boards and anything you would need goggles for.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-pokemon', 'Name a Pokémon type. You only have to name one, not catch them all.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are 18 types. Fairy was the newest, added in 2013 partly to take overpowered dragons down a peg. Every type is strong or weak against others, like a very complicated game of rock, paper, scissors.', 'https://en.wikipedia.org/wiki/Gameplay_of_Pok%C3%A9mon', 'Wikipedia: Gameplay of Pokémon', '2026-11-21', 'CC BY-SA 4.0', 'games', 1, 0, '[{"canonical":"Fire","prior":18,"aliases":[]},{"canonical":"Water","prior":16,"aliases":[]},{"canonical":"Grass","prior":12,"aliases":[]},{"canonical":"Electric","prior":12,"aliases":[]},{"canonical":"Psychic","prior":6,"aliases":[]},{"canonical":"Ghost","prior":5,"aliases":[]},{"canonical":"Dragon","prior":5,"aliases":[]},{"canonical":"Normal","prior":4,"aliases":[]},{"canonical":"Ice","prior":3,"aliases":[]},{"canonical":"Fighting","prior":3,"aliases":[]},{"canonical":"Poison","prior":3,"aliases":[]},{"canonical":"Flying","prior":3,"aliases":[]},{"canonical":"Rock","prior":3,"aliases":[]},{"canonical":"Ground","prior":2,"aliases":[]},{"canonical":"Bug","prior":2,"aliases":[]},{"canonical":"Dark","prior":2,"aliases":[]},{"canonical":"Fairy","prior":2,"aliases":[]},{"canonical":"Steel","prior":1,"aliases":[]}]', NULL, 'Think of the elements, the weather, and the kind of creature that hides under a log.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-india-games', 'Name a game that was invented in India.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Chess grew out of chaturanga in India around the 6th century, and snakes and ladders began as moksha patam, a game about good and bad deeds. Modern polo took its rules from games British officers saw in Manipur. Cricket, sadly, was invented in England.', 'https://en.wikipedia.org/wiki/Chaturanga', 'Wikipedia: Chaturanga', '2026-11-21', 'CC BY-SA 4.0', 'games', 2, 0, '[{"canonical":"Chess","prior":34,"aliases":["Chaturanga","Shatranj"]},{"canonical":"Ludo","prior":18,"aliases":["Pachisi","Chaupar","Chausar"]},{"canonical":"Snakes and ladders","prior":16,"aliases":["Snakes & ladders","Snake and ladder","Snakes and ladder","Moksha patam","Gyan chaupar"]},{"canonical":"Kabaddi","prior":14,"aliases":[]},{"canonical":"Kho kho","prior":6,"aliases":["Kho-kho"]},{"canonical":"Badminton","prior":3,"aliases":[]},{"canonical":"Carrom","prior":3,"aliases":[]},{"canonical":"Polo","prior":2,"aliases":[]},{"canonical":"Gilli danda","prior":2,"aliases":["Gilli-danda"]},{"canonical":"Lagori","prior":1,"aliases":["Pittu","Pitthu","Seven stones"]}]', NULL, 'Think of board games your grandparents played, and games for a dusty schoolyard.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-chess', 'Name a piece that starts the game on a chessboard.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'In India the rook is often called the elephant, the bishop the camel and the knight the horse, closer to chaturanga''s original army. The queen started out as a minister who could only shuffle one square diagonally, and became the strongest piece around 1500.', 'https://en.wikipedia.org/wiki/Chess', 'Wikipedia: Chess', '2026-11-21', 'CC BY-SA 4.0', 'games', 1, 0, '[{"canonical":"King","prior":30,"aliases":["Raja"]},{"canonical":"Queen","prior":25,"aliases":["Wazir","Vazir","Minister"]},{"canonical":"Pawn","prior":13,"aliases":["Pawns","Pyada","Soldier"]},{"canonical":"Knight","prior":12,"aliases":["Horse","Ghoda"]},{"canonical":"Rook","prior":10,"aliases":["Castle","Elephant","Haathi","Hathi"]},{"canonical":"Bishop","prior":10,"aliases":["Camel","Oont","Unt"]}]', NULL, 'Think of the back row: royalty, the clergy, the cavalry and a tower in each corner.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-ice', 'Name a sport played on ice. Falling over by accident does not count.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Bobsleigh, luge and skeleton all race down the same iced track. Bobsleighs carry a crew in a shell, luge sliders lie on their backs feet first, and skeleton sliders go head first on their fronts at well over 120 km/h.', 'https://en.wikipedia.org/wiki/Winter_Olympic_Games', 'Wikipedia: Winter Olympic Games', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Ice hockey","prior":35,"aliases":["Hockey"]},{"canonical":"Figure skating","prior":20,"aliases":["Skating","Ice skating","Ice dance","Ice dancing"]},{"canonical":"Curling","prior":15,"aliases":[]},{"canonical":"Speed skating","prior":10,"aliases":["Long track speed skating"]},{"canonical":"Bobsleigh","prior":6,"aliases":["Bobsled","Bobsledding"]},{"canonical":"Short track","prior":3,"aliases":["Short track speed skating"]},{"canonical":"Luge","prior":3,"aliases":[]},{"canonical":"Skeleton","prior":2,"aliases":[]},{"canonical":"Bandy","prior":1,"aliases":[]},{"canonical":"Para ice hockey","prior":0.5,"aliases":["Sledge hockey"]},{"canonical":"Ringette","prior":0.5,"aliases":[]},{"canonical":"Ice stock sport","prior":0.5,"aliases":["Ice stock","Eisstockschiessen"]},{"canonical":"Ice climbing","prior":0.5,"aliases":[]},{"canonical":"Ice cross downhill","prior":0.5,"aliases":["Crashed Ice"]}]', NULL, 'Think of the Winter Olympics: sliding, sweeping, racing and spinning.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-eleven', 'Name a team sport with eleven players per side on the field.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Bandy is the one that surprises people: football on ice with a small ball and curved sticks, eleven a side, and a big deal in Sweden, Finland and Russia. Kho kho fields nine and kabaddi seven, so they miss out.', 'https://en.wikipedia.org/wiki/Bandy', 'Wikipedia: Bandy', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Football","prior":40,"aliases":["Soccer","Association football"]},{"canonical":"Cricket","prior":35,"aliases":[]},{"canonical":"Field hockey","prior":12,"aliases":["Hockey"]},{"canonical":"American football","prior":6,"aliases":["Gridiron","NFL"]},{"canonical":"Bandy","prior":1,"aliases":[]}]', NULL, 'Think of the world''s most popular sports, then of their cousins on grass and on ice.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-four', 'Name a country with only four letters in its name.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are ten: Chad, Cuba, Fiji, Iran, Iraq, Laos, Mali, Oman, Peru and Togo. Iran and Iraq differ by one letter and share a long border, which must keep postal workers on their toes.', 'https://en.wikipedia.org/wiki/List_of_sovereign_states', 'Wikipedia: List of sovereign states', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Peru","prior":14,"aliases":[]},{"canonical":"Cuba","prior":14,"aliases":[]},{"canonical":"Iran","prior":12,"aliases":[]},{"canonical":"Iraq","prior":12,"aliases":[]},{"canonical":"Fiji","prior":10,"aliases":[]},{"canonical":"Chad","prior":8,"aliases":[]},{"canonical":"Mali","prior":8,"aliases":[]},{"canonical":"Oman","prior":8,"aliases":[]},{"canonical":"Laos","prior":6,"aliases":[]},{"canonical":"Togo","prior":6,"aliases":[]}]', 'countries', 'Think of the Middle East, the Pacific and the middle of Africa.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-land', 'Name a country whose name ends in -land.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Seven UN members end in -land. Swaziland renamed itself Eswatini in 2018, Scotland and England play football as countries but are not UN members, and Greenland belongs to Denmark.', 'https://en.wikipedia.org/wiki/List_of_sovereign_states', 'Wikipedia: List of sovereign states', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Finland","prior":18,"aliases":[]},{"canonical":"Iceland","prior":16,"aliases":[]},{"canonical":"Ireland","prior":14,"aliases":["Republic of Ireland","Eire"]},{"canonical":"Poland","prior":14,"aliases":[]},{"canonical":"Switzerland","prior":14,"aliases":[]},{"canonical":"Thailand","prior":12,"aliases":[]},{"canonical":"New Zealand","prior":10,"aliases":[]}]', 'countries', 'Think of northern Europe, plus one country in Southeast Asia and one in the far south.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-zed', 'Name a country with the letter Z in its name.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fifteen UN members have a Z somewhere, from Brazil to Bosnia and Herzegovina. Only Zambia and Zimbabwe start with one, and they share a border along the Zambezi river.', 'https://en.wikipedia.org/wiki/List_of_sovereign_states', 'Wikipedia: List of sovereign states', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Brazil","prior":18,"aliases":[]},{"canonical":"New Zealand","prior":14,"aliases":[]},{"canonical":"Switzerland","prior":12,"aliases":[]},{"canonical":"Zimbabwe","prior":10,"aliases":[]},{"canonical":"Zambia","prior":8,"aliases":[]},{"canonical":"Venezuela","prior":8,"aliases":[]},{"canonical":"Tanzania","prior":6,"aliases":[]},{"canonical":"Kazakhstan","prior":6,"aliases":[]},{"canonical":"Uzbekistan","prior":4,"aliases":[]},{"canonical":"Mozambique","prior":4,"aliases":[]},{"canonical":"Czechia","prior":3,"aliases":["Czech Republic"]},{"canonical":"Azerbaijan","prior":3,"aliases":[]},{"canonical":"Belize","prior":2,"aliases":[]},{"canonical":"Kyrgyzstan","prior":1,"aliases":[]},{"canonical":"Bosnia and Herzegovina","prior":1,"aliases":["Bosnia","Herzegovina","Bosnia & Herzegovina"]}]', 'countries', 'Think of Central Asia, southern Africa and the Alps.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-stan', 'Name a country whose name ends in -stan.', 'name_one', NULL, 'higher', NULL, '[]', '[]', '-stan comes from a Persian word for ''place of'', so Afghanistan is roughly ''land of the Afghans''. There are seven, and five of them were part of the Soviet Union until 1991.', 'https://en.wikipedia.org/wiki/-stan', 'Wikipedia: -stan', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Pakistan","prior":40,"aliases":[]},{"canonical":"Afghanistan","prior":24,"aliases":[]},{"canonical":"Kazakhstan","prior":14,"aliases":[]},{"canonical":"Uzbekistan","prior":8,"aliases":[]},{"canonical":"Turkmenistan","prior":6,"aliases":[]},{"canonical":"Tajikistan","prior":5,"aliases":[]},{"canonical":"Kyrgyzstan","prior":3,"aliases":[]}]', 'countries', 'They all sit between the Caspian Sea and the Himalaya.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-neighbour', 'Name a country that shares a land border with exactly one other country.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fourteen countries have just one neighbour by land, from Portugal (Spain) to Lesotho, which South Africa surrounds completely. Canada and Denmark used to be on this list, until they split tiny Hans Island down the middle in 2022 and became neighbours.', 'https://en.wikipedia.org/wiki/List_of_countries_and_territories_by_number_of_land_borders', 'Wikipedia: List of countries and territories by number of land borders', '2026-11-21', 'CC BY-SA 4.0', 'geography', 3, 0, '[{"canonical":"Portugal","prior":14,"aliases":[]},{"canonical":"Ireland","prior":10,"aliases":["Republic of Ireland"]},{"canonical":"Haiti","prior":6,"aliases":[]},{"canonical":"Dominican Republic","prior":5,"aliases":[]},{"canonical":"South Korea","prior":6,"aliases":["Korea","Republic of Korea"]},{"canonical":"Monaco","prior":5,"aliases":[]},{"canonical":"San Marino","prior":4,"aliases":[]},{"canonical":"Vatican City","prior":5,"aliases":["Vatican","Holy See"]},{"canonical":"Lesotho","prior":4,"aliases":[]},{"canonical":"Gambia","prior":3,"aliases":["The Gambia"]},{"canonical":"Qatar","prior":3,"aliases":[]},{"canonical":"Brunei","prior":3,"aliases":[]},{"canonical":"Timor-Leste","prior":2,"aliases":["East Timor"]},{"canonical":"Papua New Guinea","prior":2,"aliases":["PNG"]}]', 'countries', 'Think of countries at the tip of a peninsula, on a shared island, or wrapped inside another country.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-same-letter', 'Name a country whose name starts and ends with the same letter.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Nine of the eleven countries that start with A also end with A; only Afghanistan and Azerbaijan spoil it. Outside the A''s the club is tiny: Seychelles, the Solomon Islands, the Central African Republic and two Saints.', 'https://en.wikipedia.org/wiki/List_of_sovereign_states', 'Wikipedia: List of sovereign states', '2026-11-21', 'CC BY-SA 4.0', 'words', 2, 0, '[{"canonical":"Australia","prior":18,"aliases":[]},{"canonical":"Argentina","prior":16,"aliases":[]},{"canonical":"Austria","prior":12,"aliases":[]},{"canonical":"Algeria","prior":8,"aliases":[]},{"canonical":"Albania","prior":7,"aliases":[]},{"canonical":"Angola","prior":6,"aliases":[]},{"canonical":"Armenia","prior":6,"aliases":[]},{"canonical":"Andorra","prior":4,"aliases":[]},{"canonical":"Antigua and Barbuda","prior":2,"aliases":["Antigua"]},{"canonical":"Central African Republic","prior":2,"aliases":["CAR"]},{"canonical":"Seychelles","prior":2,"aliases":[]},{"canonical":"Solomon Islands","prior":1,"aliases":["Solomons"]},{"canonical":"Saint Kitts and Nevis","prior":1,"aliases":["St Kitts and Nevis","Saint Kitts","St Kitts"]},{"canonical":"Saint Vincent and the Grenadines","prior":0.5,"aliases":["St Vincent and the Grenadines","Saint Vincent","St Vincent"]}]', 'countries', 'Most of the easy ones start with A. The rarer ones start with S or C.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-hindi-words', 'Name an English word borrowed from Hindi or Urdu. You have probably used three today.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Shampoo comes from chāmpo, to press or knead: it was a head massage long before it came in a bottle. Yoga, karma and curry are Indian too, but they came from Sanskrit and Tamil, so they sit on a different list.', 'https://en.wikipedia.org/wiki/List_of_English_words_of_Hindi_or_Urdu_origin', 'Wikipedia: List of English words of Hindi or Urdu origin', '2026-11-21', 'CC BY-SA 4.0', 'words', 2, 0, '[{"canonical":"Shampoo","prior":16,"aliases":[]},{"canonical":"Jungle","prior":14,"aliases":[]},{"canonical":"Pyjamas","prior":12,"aliases":["Pajamas","Pyjama","Pajama","PJs"]},{"canonical":"Bungalow","prior":8,"aliases":[]},{"canonical":"Loot","prior":8,"aliases":[]},{"canonical":"Guru","prior":6,"aliases":[]},{"canonical":"Thug","prior":6,"aliases":[]},{"canonical":"Chutney","prior":5,"aliases":[]},{"canonical":"Pundit","prior":5,"aliases":["Pandit"]},{"canonical":"Cheetah","prior":4,"aliases":[]},{"canonical":"Bandana","prior":3,"aliases":["Bandanna"]},{"canonical":"Khaki","prior":3,"aliases":[]},{"canonical":"Cot","prior":2,"aliases":[]},{"canonical":"Juggernaut","prior":2,"aliases":[]},{"canonical":"Cushy","prior":2,"aliases":[]},{"canonical":"Dinghy","prior":2,"aliases":[]},{"canonical":"Bangle","prior":2,"aliases":[]},{"canonical":"Chit","prior":1,"aliases":[]},{"canonical":"Dungarees","prior":1,"aliases":[]},{"canonical":"Blighty","prior":1,"aliases":[]},{"canonical":"Dekko","prior":0.5,"aliases":[]},{"canonical":"Chintz","prior":0.5,"aliases":[]}]', NULL, 'Think of clothes you sleep in, bath time, houses with one floor, and words for a crook.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-ancient', 'Name one of the Seven Wonders of the Ancient World. Only one is still standing, so no pressure.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Only the Great Pyramid survives, and it was already more than 2,000 years old when the list was written. The tomb of King Mausolus was so grand that every big tomb since has been called a mausoleum.', 'https://en.wikipedia.org/wiki/Seven_Wonders_of_the_Ancient_World', 'Wikipedia: Seven Wonders of the Ancient World', '2026-11-21', 'CC BY-SA 4.0', 'history', 2, 0, '[{"canonical":"Great Pyramid of Giza","prior":30,"aliases":["Great Pyramid","Pyramids","Pyramids of Giza","Pyramid of Giza","Giza pyramid"]},{"canonical":"Hanging Gardens of Babylon","prior":20,"aliases":["Hanging Gardens","Gardens of Babylon"]},{"canonical":"Colossus of Rhodes","prior":14,"aliases":["Colossus"]},{"canonical":"Lighthouse of Alexandria","prior":12,"aliases":["Pharos","Pharos of Alexandria","Lighthouse"]},{"canonical":"Statue of Zeus at Olympia","prior":8,"aliases":["Statue of Zeus"]},{"canonical":"Temple of Artemis","prior":6,"aliases":["Temple of Artemis at Ephesus","Artemision"]},{"canonical":"Mausoleum at Halicarnassus","prior":4,"aliases":["Mausoleum","Mausoleum of Halicarnassus","Tomb of Mausolus"]}]', NULL, 'Think of Greek and Egyptian cities around the Mediterranean, and one garden far to the east.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-new7', 'Name one of the New 7 Wonders of the World, picked in a global vote in 2007.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The organisers said around 100 million votes came in by phone and online. The Great Pyramid of Giza was made an honorary member, as the last of the original seven, and the Taj Mahal is the only winner in India.', 'https://en.wikipedia.org/wiki/New_7_Wonders_of_the_World', 'Wikipedia: New 7 Wonders of the World', '2026-11-21', 'CC BY-SA 4.0', 'history', 1, 0, '[{"canonical":"Taj Mahal","prior":30,"aliases":[]},{"canonical":"Great Wall of China","prior":20,"aliases":["Great Wall"]},{"canonical":"Machu Picchu","prior":12,"aliases":[]},{"canonical":"Colosseum","prior":10,"aliases":["Coliseum","Roman Colosseum"]},{"canonical":"Petra","prior":8,"aliases":[]},{"canonical":"Christ the Redeemer","prior":8,"aliases":["Cristo Redentor"]},{"canonical":"Chichén Itzá","prior":6,"aliases":["Chichen Itza"]},{"canonical":"Great Pyramid of Giza","prior":2,"aliases":["Great Pyramid","Pyramids","Pyramids of Giza"]}]', NULL, 'Think of South America, Rome, Jordan and India.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-olympians', 'Name one of the gods who lived on Mount Olympus.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The twelve Olympians shifted over time, and in some versions Hestia gives up her seat to Dionysus. Hades does not count: he lived in the underworld, which is a long commute.', 'https://en.wikipedia.org/wiki/Twelve_Olympians', 'Wikipedia: Twelve Olympians', '2026-11-21', 'CC BY-SA 4.0', 'history', 1, 0, '[{"canonical":"Zeus","prior":30,"aliases":[]},{"canonical":"Poseidon","prior":12,"aliases":[]},{"canonical":"Athena","prior":10,"aliases":["Athene"]},{"canonical":"Hera","prior":8,"aliases":[]},{"canonical":"Apollo","prior":8,"aliases":[]},{"canonical":"Aphrodite","prior":8,"aliases":[]},{"canonical":"Hermes","prior":6,"aliases":[]},{"canonical":"Ares","prior":5,"aliases":[]},{"canonical":"Artemis","prior":4,"aliases":[]},{"canonical":"Hephaestus","prior":3,"aliases":["Hephaistos"]},{"canonical":"Dionysus","prior":3,"aliases":["Dionysos"]},{"canonical":"Demeter","prior":2,"aliases":[]},{"canonical":"Hestia","prior":1,"aliases":[]}]', NULL, 'Think of the gods of the sea, war, love, wine, hunting and the forge.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-pandavas', 'Name one of the five Pandava brothers from the Mahabharata.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Yudhishthira, Bhima and Arjuna were sons of Kunti, and the twins Nakula and Sahadeva were sons of Madri. Karna was Kunti''s son too, which made him a secret sixth brother, but he fought on the other side.', 'https://en.wikipedia.org/wiki/Pandava', 'Wikipedia: Pandava', '2026-11-21', 'CC BY-SA 4.0', 'history', 1, 0, '[{"canonical":"Arjuna","prior":34,"aliases":["Arjun"]},{"canonical":"Bhima","prior":22,"aliases":["Bheem","Bhim","Bhimsen","Bhimasena"]},{"canonical":"Yudhishthira","prior":20,"aliases":["Yudhishthir","Yudhisthira","Yudhishtir","Dharmaraj"]},{"canonical":"Nakula","prior":12,"aliases":["Nakul"]},{"canonical":"Sahadeva","prior":12,"aliases":["Sahdev","Sahadev"]}]', NULL, 'Think of the archer, the strongman, the eldest who never lied, and the twins.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-reindeer', 'Name one of Santa''s reindeer.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The original eight come from the 1823 poem A Visit from St. Nicholas. Rudolph only joined in 1939, in a booklet a department store wrote to give away at Christmas.', 'https://en.wikipedia.org/wiki/Santa_Claus%27s_reindeer', 'Wikipedia: Santa Claus''s reindeer', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Rudolph","prior":40,"aliases":[]},{"canonical":"Dasher","prior":10,"aliases":[]},{"canonical":"Dancer","prior":8,"aliases":[]},{"canonical":"Prancer","prior":8,"aliases":[]},{"canonical":"Vixen","prior":6,"aliases":[]},{"canonical":"Comet","prior":6,"aliases":[]},{"canonical":"Cupid","prior":6,"aliases":[]},{"canonical":"Donner","prior":5,"aliases":["Donder","Dunder"]},{"canonical":"Blitzen","prior":5,"aliases":["Blixem"]}]', NULL, 'Think of the poem ''The Night Before Christmas'', where eight of them are named in a row.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-norse', 'Name a god or goddess from Norse mythology. Hammer optional.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Four days of the English week belong to this crowd: Tuesday to Tyr, Wednesday to Odin (Woden), Thursday to Thor and, most likely, Friday to Frigg. Loki was strictly a giant who lived among the gods, not one of them.', 'https://en.wikipedia.org/wiki/Norse_mythology', 'Wikipedia: Norse mythology', '2026-11-21', 'CC BY-SA 4.0', 'myth', 1, 0, '[{"canonical":"Thor","prior":40,"aliases":[]},{"canonical":"Odin","prior":22,"aliases":["Woden","Wotan"]},{"canonical":"Loki","prior":18,"aliases":[]},{"canonical":"Freyja","prior":4,"aliases":["Freya"]},{"canonical":"Frigg","prior":3,"aliases":["Frigga"]},{"canonical":"Heimdall","prior":3,"aliases":["Heimdallr","Heimdal"]},{"canonical":"Baldr","prior":2,"aliases":["Balder","Baldur"]},{"canonical":"Tyr","prior":2,"aliases":["Tiw"]},{"canonical":"Freyr","prior":1,"aliases":["Frey"]},{"canonical":"Njord","prior":1,"aliases":["Njordr"]},{"canonical":"Hel","prior":1,"aliases":["Hela"]},{"canonical":"Sif","prior":1,"aliases":[]},{"canonical":"Bragi","prior":0.5,"aliases":[]},{"canonical":"Idun","prior":0.5,"aliases":["Idunn","Iduna"]},{"canonical":"Vidar","prior":0.5,"aliases":["Vidarr"]},{"canonical":"Ullr","prior":0.5,"aliases":["Ull","Uller"]},{"canonical":"Hodr","prior":0.5,"aliases":["Hod","Hoder"]},{"canonical":"Forseti","prior":0.5,"aliases":[]},{"canonical":"Skadi","prior":0.5,"aliases":[]},{"canonical":"Vali","prior":0.5,"aliases":[]}]', NULL, 'Think of Marvel films, the days of the week, and the gods of the sea and of the gate to Asgard.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-knights', 'Name a Knight of the Round Table. The king himself does not count.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The table was round so that no knight could claim the head of it. Galahad, the purest of them, found the Holy Grail, and the most famous knight of all, Lancelot, was his father.', 'https://en.wikipedia.org/wiki/Knights_of_the_Round_Table', 'Wikipedia: Knights of the Round Table', '2026-11-21', 'CC BY-SA 4.0', 'myth', 2, 0, '[{"canonical":"Lancelot","prior":40,"aliases":["Sir Lancelot","Lancelot du Lac"]},{"canonical":"Galahad","prior":14,"aliases":["Sir Galahad"]},{"canonical":"Gawain","prior":12,"aliases":["Sir Gawain","Gawaine"]},{"canonical":"Percival","prior":8,"aliases":["Sir Percival","Perceval","Parzival"]},{"canonical":"Mordred","prior":5,"aliases":["Modred"]},{"canonical":"Tristan","prior":4,"aliases":["Sir Tristan","Tristram"]},{"canonical":"Kay","prior":3,"aliases":["Sir Kay"]},{"canonical":"Bedivere","prior":3,"aliases":["Sir Bedivere","Bedwyr"]},{"canonical":"Gareth","prior":1,"aliases":[]},{"canonical":"Bors","prior":1,"aliases":["Sir Bors"]},{"canonical":"Lamorak","prior":0.5,"aliases":[]},{"canonical":"Gaheris","prior":0.5,"aliases":[]},{"canonical":"Agravain","prior":0.5,"aliases":[]},{"canonical":"Pellinore","prior":0.5,"aliases":["King Pellinore"]},{"canonical":"Ector","prior":0.5,"aliases":["Sir Ector"]},{"canonical":"Yvain","prior":0.5,"aliases":["Owain","Ywain"]},{"canonical":"Palamedes","prior":0.5,"aliases":[]}]', NULL, 'Think of the quest for the Holy Grail, and the traitor who brought Camelot down.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-noble', 'Name a noble gas. They are far too posh to react with anything.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Noble gases have full outer shells of electrons, so they rarely bother bonding with anyone. Krypton is real and is not Superman''s home planet, and oganesson, the newest, has only ever existed a few atoms at a time.', 'https://en.wikipedia.org/wiki/Noble_gas', 'Wikipedia: Noble gas', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Helium","prior":30,"aliases":[]},{"canonical":"Neon","prior":24,"aliases":[]},{"canonical":"Argon","prior":16,"aliases":[]},{"canonical":"Krypton","prior":10,"aliases":[]},{"canonical":"Xenon","prior":10,"aliases":[]},{"canonical":"Radon","prior":8,"aliases":[]},{"canonical":"Oganesson","prior":2,"aliases":[]}]', 'elements', 'Think of party balloons, glowing shop signs and Superman''s home planet.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-rainbow', 'Name one of the seven classic colours of the rainbow.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Isaac Newton settled on seven colours partly because he wanted them to match the seven notes of a musical scale. That is why indigo made the list, even though most people struggle to spot it.', 'https://en.wikipedia.org/wiki/ROYGBIV', 'Wikipedia: ROYGBIV', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Red","prior":20,"aliases":[]},{"canonical":"Blue","prior":16,"aliases":[]},{"canonical":"Green","prior":14,"aliases":[]},{"canonical":"Yellow","prior":14,"aliases":[]},{"canonical":"Orange","prior":12,"aliases":[]},{"canonical":"Violet","prior":12,"aliases":["Purple"]},{"canonical":"Indigo","prior":8,"aliases":[]}]', NULL, 'Think of ROYGBIV, and especially the colours at each end.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-machines', 'Name one of the six classic simple machines.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Renaissance scientists listed six simple machines, and nearly every gadget is built from them. A zip is a set of wedges, scissors are two levers with wedge edges, and a jar lid is a screw.', 'https://en.wikipedia.org/wiki/Simple_machine', 'Wikipedia: Simple machine', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Lever","prior":26,"aliases":["Levers"]},{"canonical":"Pulley","prior":22,"aliases":["Pulleys"]},{"canonical":"Wheel and axle","prior":16,"aliases":["Wheel","Wheel & axle","Axle"]},{"canonical":"Inclined plane","prior":14,"aliases":["Ramp","Slope"]},{"canonical":"Screw","prior":10,"aliases":[]},{"canonical":"Wedge","prior":8,"aliases":[]}]', NULL, 'Think of a seesaw, a flagpole, a doorstop and the thing that holds a jar lid on.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-length', 'Name a unit for measuring length or distance. Any country, any century.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The metre was first defined as one ten-millionth of the distance from the North Pole to the equator. A furlong is the length of furrow an ox could plough without resting, and in 1958 MIT students measured a bridge in ''smoots'', using a classmate called Oliver Smoot as the ruler.', 'https://en.wikipedia.org/wiki/Unit_of_length', 'Wikipedia: Unit of length', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Metre","prior":18,"aliases":["Meter","Metres","Meters","m"]},{"canonical":"Kilometre","prior":14,"aliases":["Kilometer","Kilometres","Kilometers","km"]},{"canonical":"Centimetre","prior":10,"aliases":["Centimeter","Centimetres","Centimeters","cm"]},{"canonical":"Inch","prior":10,"aliases":["Inches"]},{"canonical":"Foot","prior":10,"aliases":["Feet","ft"]},{"canonical":"Mile","prior":8,"aliases":["Miles"]},{"canonical":"Millimetre","prior":5,"aliases":["Millimeter","mm"]},{"canonical":"Yard","prior":5,"aliases":["Yards","Gaj","Gaz"]},{"canonical":"Light-year","prior":5,"aliases":["Light year","Lightyear","Light years"]},{"canonical":"Nautical mile","prior":2,"aliases":["Nautical miles"]},{"canonical":"Nanometre","prior":2,"aliases":["Nanometer","nm"]},{"canonical":"Micrometre","prior":1,"aliases":["Micron","Micrometer"]},{"canonical":"Astronomical unit","prior":1,"aliases":["AU"]},{"canonical":"Parsec","prior":1,"aliases":[]},{"canonical":"Angstrom","prior":1,"aliases":["Ångström"]},{"canonical":"Furlong","prior":1,"aliases":[]},{"canonical":"Fathom","prior":1,"aliases":[]},{"canonical":"Cubit","prior":1,"aliases":["Haath","Hath"]},{"canonical":"League","prior":0.5,"aliases":[]},{"canonical":"Hand","prior":0.5,"aliases":["Hands"]},{"canonical":"Chain","prior":0.5,"aliases":[]},{"canonical":"Rod","prior":0.5,"aliases":["Perch","Pole"]},{"canonical":"Kos","prior":0.5,"aliases":["Koss"]},{"canonical":"Decimetre","prior":0.5,"aliases":["Decimeter"]},{"canonical":"Picometre","prior":0.5,"aliases":["Picometer"]},{"canonical":"Span","prior":0.5,"aliases":["Bitta","Balisht"]},{"canonical":"Smoot","prior":0.5,"aliases":[]}]', NULL, 'Think old: sailors, horse races, ancient Egypt, Indian roads and outer space.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-vitamin', 'Name a vitamin.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are 13 vitamins, and eight of them are the B family. The letters jump from E to K because the ones in between were renamed or turned out not to be vitamins, and K comes from Koagulation, the German and Danish word for clotting.', 'https://en.wikipedia.org/wiki/Vitamin', 'Wikipedia: Vitamin', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Vitamin C","prior":26,"aliases":["C","Ascorbic acid"]},{"canonical":"Vitamin D","prior":18,"aliases":["D","Calciferol","Sunshine vitamin"]},{"canonical":"Vitamin A","prior":14,"aliases":["A","Retinol"]},{"canonical":"Vitamin B12","prior":8,"aliases":["B12","Cobalamin"]},{"canonical":"Vitamin E","prior":8,"aliases":["E","Tocopherol"]},{"canonical":"Vitamin B","prior":6,"aliases":["B","B complex","Vitamin B complex"]},{"canonical":"Vitamin K","prior":5,"aliases":["K"]},{"canonical":"Vitamin B1","prior":2,"aliases":["B1","Thiamine","Thiamin"]},{"canonical":"Vitamin B2","prior":2,"aliases":["B2","Riboflavin"]},{"canonical":"Vitamin B3","prior":2,"aliases":["B3","Niacin"]},{"canonical":"Vitamin B6","prior":2,"aliases":["B6","Pyridoxine"]},{"canonical":"Vitamin B9","prior":2,"aliases":["B9","Folate","Folic acid"]},{"canonical":"Vitamin B5","prior":1,"aliases":["B5","Pantothenic acid"]},{"canonical":"Vitamin B7","prior":1,"aliases":["B7","Biotin","Vitamin H"]}]', NULL, 'Think of the B family. It has more members than most people remember.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-unit-people', 'Name a scientist who had a unit of measurement named after them.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'A unit named after a person is written in lower case (newton, watt) but its symbol gets a capital (N, W); the degree Celsius is the one exception. Lord Kelvin was born William Thomson and took his title from the River Kelvin in Glasgow.', 'https://en.wikipedia.org/wiki/SI_derived_unit', 'Wikipedia: SI derived unit', '2026-11-21', 'CC BY-SA 4.0', 'science', 2, 0, '[{"canonical":"Isaac Newton","prior":22,"aliases":["Newton","Newtons"]},{"canonical":"James Watt","prior":12,"aliases":["Watt","Watts"]},{"canonical":"Alessandro Volta","prior":8,"aliases":["Volta","Volt","Volts"]},{"canonical":"André-Marie Ampère","prior":6,"aliases":["Ampère","Ampere","Amp","Amps"]},{"canonical":"Lord Kelvin","prior":6,"aliases":["Kelvin","William Thomson"]},{"canonical":"James Prescott Joule","prior":6,"aliases":["Joule","Joules","James Joule"]},{"canonical":"Nikola Tesla","prior":6,"aliases":["Tesla"]},{"canonical":"Blaise Pascal","prior":5,"aliases":["Pascal"]},{"canonical":"Heinrich Hertz","prior":4,"aliases":["Hertz"]},{"canonical":"Georg Ohm","prior":4,"aliases":["Ohm","Ohms","Georg Simon Ohm"]},{"canonical":"Anders Celsius","prior":4,"aliases":["Celsius"]},{"canonical":"Albert Einstein","prior":3,"aliases":["Einstein"]},{"canonical":"Marie Curie","prior":3,"aliases":["Curie","Pierre Curie"]},{"canonical":"Daniel Gabriel Fahrenheit","prior":2,"aliases":["Fahrenheit","Daniel Fahrenheit"]},{"canonical":"Charles-Augustin de Coulomb","prior":2,"aliases":["Coulomb","Charles Coulomb"]},{"canonical":"Michael Faraday","prior":2,"aliases":["Faraday","Farad"]},{"canonical":"Alexander Graham Bell","prior":1,"aliases":["Graham Bell","Bell","Decibel"]},{"canonical":"Joseph Henry","prior":1,"aliases":["Henry"]},{"canonical":"Werner von Siemens","prior":1,"aliases":["Siemens"]},{"canonical":"Carl Friedrich Gauss","prior":0.5,"aliases":["Gauss"]},{"canonical":"Wilhelm Weber","prior":0.5,"aliases":["Weber"]},{"canonical":"Henri Becquerel","prior":0.5,"aliases":["Becquerel"]},{"canonical":"Louis Harold Gray","prior":0.5,"aliases":["Gray","Hal Gray"]},{"canonical":"Rolf Sievert","prior":0.5,"aliases":["Sievert"]},{"canonical":"Anders Ångström","prior":0.5,"aliases":["Ångström","Angstrom"]}]', NULL, 'Think of electricity, temperature, pressure and radioactivity.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-cell', 'Name a part of a living cell. The powerhouse is allowed.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Mitochondria carry their own DNA, which you inherit only from your mother. They are thought to be the descendants of free-living bacteria that were swallowed by another cell, well over a billion years ago, and never left.', 'https://en.wikipedia.org/wiki/Organelle', 'Wikipedia: Organelle', '2026-11-21', 'CC BY-SA 4.0', 'science', 1, 0, '[{"canonical":"Nucleus","prior":30,"aliases":["Nuclei"]},{"canonical":"Mitochondria","prior":22,"aliases":["Mitochondrion"]},{"canonical":"Cell membrane","prior":10,"aliases":["Plasma membrane","Membrane"]},{"canonical":"Cytoplasm","prior":8,"aliases":[]},{"canonical":"Ribosome","prior":6,"aliases":["Ribosomes"]},{"canonical":"Chloroplast","prior":5,"aliases":["Chloroplasts"]},{"canonical":"Cell wall","prior":4,"aliases":[]},{"canonical":"Vacuole","prior":4,"aliases":["Vacuoles"]},{"canonical":"Golgi apparatus","prior":3,"aliases":["Golgi body","Golgi complex","Golgi"]},{"canonical":"Endoplasmic reticulum","prior":3,"aliases":["ER","Rough ER","Smooth ER"]},{"canonical":"Chromosome","prior":2,"aliases":["Chromosomes","DNA"]},{"canonical":"Lysosome","prior":2,"aliases":["Lysosomes"]},{"canonical":"Nucleolus","prior":1,"aliases":[]},{"canonical":"Centriole","prior":1,"aliases":["Centrioles","Centrosome"]},{"canonical":"Cytoskeleton","prior":1,"aliases":["Microtubules","Microtubule"]},{"canonical":"Vesicle","prior":0.5,"aliases":["Vesicles"]},{"canonical":"Peroxisome","prior":0.5,"aliases":[]},{"canonical":"Flagellum","prior":0.5,"aliases":["Flagella"]},{"canonical":"Cilia","prior":0.5,"aliases":["Cilium"]}]', NULL, 'Think of what a plant cell has that ours does not, and the little factories that build proteins.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-borders', 'Name a country that shares a land border with India.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'India borders seven countries if you count Afghanistan, which touches the part of Kashmir that India claims. The longest border, about 4,100 km, is with Bangladesh. Sri Lanka is close, but the Palk Strait is in the way.', 'https://en.wikipedia.org/wiki/Borders_of_India', 'Wikipedia: Borders of India', '2026-11-21', 'CC BY-SA 4.0', 'geography', 1, 0, '[{"canonical":"Pakistan","prior":30,"aliases":[]},{"canonical":"China","prior":24,"aliases":[]},{"canonical":"Nepal","prior":14,"aliases":[]},{"canonical":"Bangladesh","prior":12,"aliases":[]},{"canonical":"Bhutan","prior":8,"aliases":[]},{"canonical":"Myanmar","prior":6,"aliases":["Burma"]},{"canonical":"Afghanistan","prior":3,"aliases":[]}]', 'countries', 'Think of the Himalaya, and the countries to India''s east.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-ut', 'Name a union territory of India.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'There are eight. Two were merged in 2020 into the gloriously long Dadra and Nagar Haveli and Daman and Diu. Delhi is a union territory with its own elected government, which keeps things interesting.', 'https://en.wikipedia.org/wiki/Union_territory', 'Wikipedia: Union territory', '2026-11-21', 'CC BY-SA 4.0', 'geography', 2, 0, '[{"canonical":"Delhi","prior":28,"aliases":["New Delhi","NCT of Delhi","National Capital Territory"]},{"canonical":"Chandigarh","prior":14,"aliases":[]},{"canonical":"Puducherry","prior":12,"aliases":["Pondicherry","Pondy"]},{"canonical":"Jammu and Kashmir","prior":12,"aliases":["J&K","Jammu & Kashmir","Kashmir"]},{"canonical":"Ladakh","prior":10,"aliases":[]},{"canonical":"Andaman and Nicobar Islands","prior":10,"aliases":["Andaman and Nicobar","Andaman & Nicobar","Andaman","Andamans"]},{"canonical":"Lakshadweep","prior":8,"aliases":[]},{"canonical":"Dadra and Nagar Haveli and Daman and Diu","prior":4,"aliases":["Daman and Diu","Dadra and Nagar Haveli","Daman","Diu","DNHDD"]}]', NULL, 'Think of island groups in the Arabian Sea and the Bay of Bengal, and one planned city in the north.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-dance', 'Name an Indian classical dance form.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Sangeet Natak Akademi recognises eight classical forms, and the Ministry of Culture adds Chhau. Kathakali performers can spend hours on their make-up, and their eye movements are trained like a sport.', 'https://en.wikipedia.org/wiki/Indian_classical_dance', 'Wikipedia: Indian classical dance', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Bharatanatyam","prior":30,"aliases":["Bharatnatyam","Bharata natyam"]},{"canonical":"Kathak","prior":26,"aliases":[]},{"canonical":"Kathakali","prior":12,"aliases":[]},{"canonical":"Kuchipudi","prior":10,"aliases":[]},{"canonical":"Odissi","prior":10,"aliases":[]},{"canonical":"Manipuri","prior":5,"aliases":[]},{"canonical":"Mohiniyattam","prior":4,"aliases":["Mohiniattam"]},{"canonical":"Sattriya","prior":2,"aliases":["Sattriya Nritya","Satriya"]},{"canonical":"Chhau","prior":1,"aliases":["Chau"]}]', NULL, 'Every region has one. Think of Kerala''s two, the north-east, and a dance performed in masks.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-symbols', 'Name one of India''s official national symbols.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The tiger, peacock and lotus are official, the Ganga river dolphin is the national aquatic animal and the elephant is the national heritage animal. Hockey is not the national game: a 2012 government reply said India has never declared one.', 'https://en.wikipedia.org/wiki/National_symbols_of_India', 'Wikipedia: National symbols of India', '2026-11-21', 'CC BY-SA 4.0', 'culture', 1, 0, '[{"canonical":"Tiger","prior":22,"aliases":["Bengal tiger","Royal Bengal tiger"]},{"canonical":"Peacock","prior":18,"aliases":["Peafowl","Indian peafowl","Mor"]},{"canonical":"Lotus","prior":16,"aliases":["Kamal"]},{"canonical":"Mango","prior":8,"aliases":["Aam"]},{"canonical":"Tricolour","prior":6,"aliases":["Tiranga","National flag","Flag","Tricolor"]},{"canonical":"Jana Gana Mana","prior":6,"aliases":["National anthem"]},{"canonical":"Banyan","prior":5,"aliases":["Banyan tree","Bargad"]},{"canonical":"Ashoka emblem","prior":4,"aliases":["State emblem","Lion Capital","Lion Capital of Ashoka","Ashoka lions"]},{"canonical":"Vande Mataram","prior":3,"aliases":["National song"]},{"canonical":"Ganga","prior":3,"aliases":["Ganges","Ganga river"]},{"canonical":"Gangetic dolphin","prior":1,"aliases":["Ganges river dolphin","River dolphin","Dolphin"]},{"canonical":"Elephant","prior":1,"aliases":[]},{"canonical":"Rupee symbol","prior":1,"aliases":["Rupee sign"]},{"canonical":"Saka calendar","prior":0.5,"aliases":["National calendar"]}]', NULL, 'Think of the national animal, bird, flower, fruit, tree, river and song.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-chhena', 'Name a sweet made from chhena, fresh curdled milk.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Odisha and West Bengal both claim the rasgulla, and each now holds a Geographical Indication tag for its own version. Gulab jamun does not count: it is made from khoa, milk cooked down until it is nearly solid.', 'https://en.wikipedia.org/wiki/Chhena', 'Wikipedia: Chhena', '2026-11-21', 'CC BY-SA 4.0', 'food', 1, 0, '[{"canonical":"Rasgulla","prior":40,"aliases":["Rasagola","Rosogolla","Roshogolla","Rasgolla","Rossogolla"]},{"canonical":"Rasmalai","prior":22,"aliases":["Ras malai"]},{"canonical":"Sandesh","prior":14,"aliases":["Sondesh"]},{"canonical":"Cham cham","prior":6,"aliases":["Chamcham","Chomchom","Cham-cham"]},{"canonical":"Chhena poda","prior":4,"aliases":["Chenna poda","Chena poda"]},{"canonical":"Kalakand","prior":4,"aliases":["Kalakhand"]},{"canonical":"Rajbhog","prior":3,"aliases":["Raj bhog"]},{"canonical":"Chhena jalebi","prior":2,"aliases":["Chhena jhili","Chenna jalebi"]},{"canonical":"Malai chop","prior":1,"aliases":[]},{"canonical":"Pantua","prior":1,"aliases":[]},{"canonical":"Chhena gaja","prior":1,"aliases":["Chenna gaja"]},{"canonical":"Chhena murki","prior":1,"aliases":["Chenna murki"]},{"canonical":"Khira sagara","prior":0.5,"aliases":["Kheer sagar"]}]', NULL, 'Think of the sweet shops of Bengal and Odisha: soaked in syrup, pressed, baked or fried.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-avatar', 'Name one of the Dashavatara, the ten avatars of Vishnu.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The order runs fish, tortoise, boar, man-lion and dwarf, then Parashurama, Rama, Krishna, a ninth (Balarama in some lists, the Buddha in others) and Kalki, who has not arrived yet. Some readers see a rough sketch of evolution in it, from sea to land to people.', 'https://en.wikipedia.org/wiki/Dashavatara', 'Wikipedia: Dashavatara', '2026-11-21', 'CC BY-SA 4.0', 'myth', 2, 0, '[{"canonical":"Rama","prior":26,"aliases":["Ram","Lord Rama","Shri Ram","Sri Rama"]},{"canonical":"Krishna","prior":24,"aliases":["Lord Krishna"]},{"canonical":"Narasimha","prior":10,"aliases":["Narsimha","Narasimhan","Narsingh","Nrisimha"]},{"canonical":"Matsya","prior":6,"aliases":[]},{"canonical":"Parashurama","prior":6,"aliases":["Parshuram","Parasurama","Parashuram"]},{"canonical":"Kalki","prior":6,"aliases":[]},{"canonical":"Kurma","prior":5,"aliases":["Koorma"]},{"canonical":"Varaha","prior":5,"aliases":["Varah"]},{"canonical":"Vamana","prior":5,"aliases":["Vaman","Vamanan"]},{"canonical":"Buddha","prior":3,"aliases":["Gautama Buddha","Gautam Buddha"]},{"canonical":"Balarama","prior":3,"aliases":["Balram","Balaram","Baladeva"]}]', NULL, 'Think of a fish, a tortoise, a boar, a dwarf and a man-lion, before the famous princes.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('q-fun-classical', 'Name one of India''s eleven official classical languages.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Tamil was first, in 2004, and Marathi, Pali, Prakrit, Assamese and Bengali all joined in one go in October 2024. Hindi is not on the list: the title goes to languages with a long, independent literary record, not to the most spoken.', 'https://en.wikipedia.org/wiki/Classical_languages_of_India', 'Wikipedia: Classical languages of India', '2026-11-21', 'CC BY-SA 4.0', 'india', 2, 0, '[{"canonical":"Sanskrit","prior":26,"aliases":[]},{"canonical":"Tamil","prior":24,"aliases":[]},{"canonical":"Telugu","prior":10,"aliases":[]},{"canonical":"Kannada","prior":10,"aliases":[]},{"canonical":"Malayalam","prior":8,"aliases":[]},{"canonical":"Bengali","prior":6,"aliases":["Bangla"]},{"canonical":"Marathi","prior":6,"aliases":[]},{"canonical":"Odia","prior":4,"aliases":["Oriya"]},{"canonical":"Assamese","prior":2,"aliases":["Asamiya","Axomiya"]},{"canonical":"Pali","prior":2,"aliases":[]},{"canonical":"Prakrit","prior":2,"aliases":[]}]', NULL, 'Think of South India and the east, plus the old languages of Buddhist and Jain texts.');
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-cricket-tests', 'Name a country that plays Test cricket.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Twelve teams have Test status, and Ireland and Afghanistan were the newest, both promoted in 2017. A Test can last five days and still end in a draw, which is either beautiful or baffling depending on who you ask.', 'https://en.wikipedia.org/wiki/Test_cricket', 'Wikipedia: Test cricket', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"India","prior":26,"aliases":[]},{"canonical":"Australia","prior":20,"aliases":[]},{"canonical":"England","prior":16,"aliases":[]},{"canonical":"Pakistan","prior":8,"aliases":[]},{"canonical":"South Africa","prior":6,"aliases":[]},{"canonical":"New Zealand","prior":6,"aliases":[]},{"canonical":"Sri Lanka","prior":5,"aliases":[]},{"canonical":"West Indies","prior":4,"aliases":["Windies"]},{"canonical":"Bangladesh","prior":4,"aliases":[]},{"canonical":"Zimbabwe","prior":2,"aliases":[]},{"canonical":"Afghanistan","prior":2,"aliases":[]},{"canonical":"Ireland","prior":1,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-cricket-cwc', 'Name a team that has won the men''s Cricket World Cup, the 50-over one.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Australia has won it six times. West Indies won the first two, in 1975 and 1979, India won in 1983 and 2011, and England finally won in 2019 on boundaries, after even the Super Over was tied.', 'https://en.wikipedia.org/wiki/Cricket_World_Cup', 'Wikipedia: Cricket World Cup', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"India","prior":34,"aliases":[]},{"canonical":"Australia","prior":30,"aliases":[]},{"canonical":"West Indies","prior":12,"aliases":["Windies"]},{"canonical":"Pakistan","prior":8,"aliases":[]},{"canonical":"Sri Lanka","prior":8,"aliases":[]},{"canonical":"England","prior":8,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-cricket-ipl', 'Name one of the ten teams in the IPL.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Chennai Super Kings and Mumbai Indians are the most decorated. Teams that came and went include the Deccan Chargers, Kochi Tuskers Kerala and Pune Warriors India, so naming those scores nothing.', 'https://en.wikipedia.org/wiki/Indian_Premier_League', 'Wikipedia: Indian Premier League', '2026-11-21', 'CC BY-SA 4.0', 'sport', 1, 0, '[{"canonical":"Chennai Super Kings","prior":22,"aliases":["CSK","Chennai"]},{"canonical":"Mumbai Indians","prior":20,"aliases":["MI","Mumbai"]},{"canonical":"Royal Challengers Bengaluru","prior":16,"aliases":["RCB","Royal Challengers Bangalore","Royal Challengers","Bangalore","Bengaluru"]},{"canonical":"Kolkata Knight Riders","prior":12,"aliases":["KKR","Kolkata"]},{"canonical":"Sunrisers Hyderabad","prior":7,"aliases":["SRH","Hyderabad","Sunrisers"]},{"canonical":"Delhi Capitals","prior":6,"aliases":["DC","Delhi Daredevils","Delhi"]},{"canonical":"Rajasthan Royals","prior":6,"aliases":["RR","Rajasthan"]},{"canonical":"Punjab Kings","prior":5,"aliases":["PBKS","Kings XI Punjab","KXIP","Punjab"]},{"canonical":"Gujarat Titans","prior":4,"aliases":["GT","Gujarat"]},{"canonical":"Lucknow Super Giants","prior":4,"aliases":["LSG","Lucknow"]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-cricket-out', 'Name a way a batter can be given out in cricket.', 'name_one', NULL, 'higher', NULL, '[]', '[]', '''Timed out'', for taking too long to reach the crease, was used in a men''s international for the first time in 2023, against Angelo Mathews. ''Handled the ball'' was folded into obstructing the field in 2017.', 'https://en.wikipedia.org/wiki/Dismissal_(cricket)', 'Wikipedia: Dismissal (cricket)', '2026-11-21', 'CC BY-SA 4.0', 'sport', 2, 0, '[{"canonical":"Bowled","prior":24,"aliases":[]},{"canonical":"Caught","prior":24,"aliases":["Catch","Caught out","Caught behind","Caught and bowled"]},{"canonical":"LBW","prior":18,"aliases":["Leg before wicket","Leg before"]},{"canonical":"Run out","prior":14,"aliases":["Runout","Mankad"]},{"canonical":"Stumped","prior":10,"aliases":["Stumping"]},{"canonical":"Hit wicket","prior":5,"aliases":[]},{"canonical":"Obstructing the field","prior":2,"aliases":["Obstruction","Handled the ball"]},{"canonical":"Timed out","prior":2,"aliases":[]},{"canonical":"Hit the ball twice","prior":1,"aliases":[]},{"canonical":"Retired out","prior":1,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-cricket-field', 'Name a fielding position in cricket. The sillier the name, the better.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Cow corner is a real, if unofficial, spot out between deep midwicket and long-on, where few textbook shots ever go. Silly point and silly mid-off stand so close to the batter that it is silly to be there at all.', 'https://en.wikipedia.org/wiki/Fielding_(cricket)', 'Wikipedia: Fielding (cricket)', '2026-11-21', 'CC BY-SA 4.0', 'sport', 2, 0, '[{"canonical":"Slip","prior":18,"aliases":["Slips","First slip","Second slip","Third slip"]},{"canonical":"Gully","prior":10,"aliases":[]},{"canonical":"Point","prior":8,"aliases":["Deep point","Backward point"]},{"canonical":"Cover","prior":8,"aliases":["Covers","Extra cover","Cover point","Deep cover","Sweeper"]},{"canonical":"Mid-off","prior":8,"aliases":["Mid off"]},{"canonical":"Mid-on","prior":8,"aliases":["Mid on"]},{"canonical":"Midwicket","prior":6,"aliases":["Mid-wicket","Mid wicket","Deep midwicket"]},{"canonical":"Square leg","prior":6,"aliases":["Deep square leg","Backward square leg"]},{"canonical":"Fine leg","prior":6,"aliases":["Deep fine leg","Short fine leg","Long leg"]},{"canonical":"Third man","prior":6,"aliases":[]},{"canonical":"Wicketkeeper","prior":4,"aliases":["Keeper","Wicket keeper","Wicket-keeper"]},{"canonical":"Long on","prior":3,"aliases":["Long-on"]},{"canonical":"Long off","prior":3,"aliases":["Long-off"]},{"canonical":"Silly point","prior":3,"aliases":[]},{"canonical":"Short leg","prior":2,"aliases":["Forward short leg","Bat pad"]},{"canonical":"Cow corner","prior":2,"aliases":[]},{"canonical":"Silly mid-off","prior":1,"aliases":["Silly mid off"]},{"canonical":"Silly mid-on","prior":1,"aliases":["Silly mid on"]},{"canonical":"Leg slip","prior":1,"aliases":[]},{"canonical":"Fly slip","prior":1,"aliases":[]},{"canonical":"Leg gully","prior":0.5,"aliases":[]},{"canonical":"Long stop","prior":0.5,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-screen-dwarfs', 'Name one of the Seven Dwarfs from Disney''s Snow White.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Disney''s story team tried dozens of names before settling on these seven, including Jumpy, Deafy and Wheezy. Dopey is the only one who never speaks.', 'https://en.wikipedia.org/wiki/Seven_Dwarfs', 'Wikipedia: Seven Dwarfs', '2026-11-21', 'CC BY-SA 4.0', 'screen', 1, 0, '[{"canonical":"Dopey","prior":18,"aliases":[]},{"canonical":"Grumpy","prior":18,"aliases":[]},{"canonical":"Happy","prior":14,"aliases":[]},{"canonical":"Sleepy","prior":14,"aliases":[]},{"canonical":"Sneezy","prior":12,"aliases":[]},{"canonical":"Doc","prior":12,"aliases":[]},{"canonical":"Bashful","prior":12,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-screen-friends', 'Name one of the six main characters in Friends.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Phoebe''s twin sister Ursula first appeared in another sitcom, Mad About You, which technically puts both shows in one universe. Joey is the only one of the six who got his own spin-off.', 'https://en.wikipedia.org/wiki/Friends', 'Wikipedia: Friends', '2026-11-21', 'CC BY-SA 4.0', 'screen', 1, 0, '[{"canonical":"Rachel Green","prior":18,"aliases":["Rachel"]},{"canonical":"Chandler Bing","prior":18,"aliases":["Chandler"]},{"canonical":"Joey Tribbiani","prior":18,"aliases":["Joey"]},{"canonical":"Ross Geller","prior":16,"aliases":["Ross"]},{"canonical":"Monica Geller","prior":16,"aliases":["Monica"]},{"canonical":"Phoebe Buffay","prior":14,"aliases":["Phoebe"]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-screen-simpsons', 'Name a member of the Simpson family. Pets count.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Matt Groening named Homer, Marge, Lisa, Maggie and Abraham after his own family, and Bart is an anagram of ''brat''. Marge''s sisters Patty and Selma are Bouviers, so they do not count.', 'https://en.wikipedia.org/wiki/Simpson_family', 'Wikipedia: Simpson family', '2026-11-21', 'CC BY-SA 4.0', 'screen', 1, 0, '[{"canonical":"Homer","prior":28,"aliases":["Homer Simpson","Homer J. Simpson"]},{"canonical":"Bart","prior":22,"aliases":["Bart Simpson"]},{"canonical":"Marge","prior":16,"aliases":["Marge Simpson"]},{"canonical":"Lisa","prior":16,"aliases":["Lisa Simpson"]},{"canonical":"Maggie","prior":10,"aliases":["Maggie Simpson"]},{"canonical":"Abe","prior":3,"aliases":["Grampa","Grandpa","Grampa Simpson","Abraham","Abraham Simpson","Abe Simpson"]},{"canonical":"Santa''s Little Helper","prior":3,"aliases":["Santas Little Helper"]},{"canonical":"Snowball II","prior":1,"aliases":["Snowball","Snowball 2"]},{"canonical":"Mona","prior":0.5,"aliases":["Mona Simpson"]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-screen-princess', 'Name an official Disney Princess.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Mulan is in the official line-up even though she is not royalty, because saving China counts. Elsa and Anna from Frozen are hugely popular, but they sit in their own franchise.', 'https://en.wikipedia.org/wiki/Disney_Princess', 'Wikipedia: Disney Princess', '2026-11-21', 'CC BY-SA 4.0', 'screen', 1, 0, '[{"canonical":"Cinderella","prior":16,"aliases":[]},{"canonical":"Ariel","prior":14,"aliases":["Little Mermaid"]},{"canonical":"Belle","prior":12,"aliases":[]},{"canonical":"Jasmine","prior":10,"aliases":[]},{"canonical":"Snow White","prior":10,"aliases":[]},{"canonical":"Aurora","prior":8,"aliases":["Sleeping Beauty","Briar Rose"]},{"canonical":"Mulan","prior":8,"aliases":[]},{"canonical":"Rapunzel","prior":6,"aliases":[]},{"canonical":"Pocahontas","prior":6,"aliases":[]},{"canonical":"Tiana","prior":4,"aliases":[]},{"canonical":"Moana","prior":3,"aliases":[]},{"canonical":"Merida","prior":2,"aliases":[]},{"canonical":"Raya","prior":1,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-screen-bond', 'Name an actor who played James Bond in the official films.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'George Lazenby played Bond only once, in 1969, then turned down a contract for more. David Niven played Bond too, in the 1967 spoof Casino Royale, which is not one of the official films.', 'https://en.wikipedia.org/wiki/James_Bond_in_film', 'Wikipedia: James Bond in film', '2026-11-21', 'CC BY-SA 4.0', 'screen', 1, 0, '[{"canonical":"Daniel Craig","prior":26,"aliases":["Craig"]},{"canonical":"Sean Connery","prior":22,"aliases":["Connery"]},{"canonical":"Pierce Brosnan","prior":18,"aliases":["Brosnan"]},{"canonical":"Roger Moore","prior":16,"aliases":["Moore"]},{"canonical":"Timothy Dalton","prior":8,"aliases":["Dalton"]},{"canonical":"George Lazenby","prior":4,"aliases":["Lazenby"]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-space-landers', 'Name a country that has soft-landed a spacecraft on the Moon.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'The Soviet Luna 9 made the first soft landing in 1966. India''s Chandrayaan-3 was the first to land near the Moon''s south pole, in 2023, and Japan''s SLIM landed in 2024 upside down, and still worked.', 'https://en.wikipedia.org/wiki/List_of_landings_on_extraterrestrial_bodies', 'Wikipedia: List of landings on extraterrestrial bodies', '2026-11-21', 'CC BY-SA 4.0', 'space', 1, 0, '[{"canonical":"United States","prior":34,"aliases":["USA","US","America","United States of America"]},{"canonical":"Russia","prior":22,"aliases":["Soviet Union","USSR"]},{"canonical":"India","prior":22,"aliases":[]},{"canonical":"China","prior":16,"aliases":[]},{"canonical":"Japan","prior":6,"aliases":[]}]', 'countries', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-space-dwarf', 'Name one of the five official dwarf planets.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Pluto was demoted in 2006, after astronomers found Eris, which has more mass. Ceres is the only dwarf planet in the asteroid belt, and Makemake is named after a creator god of Easter Island.', 'https://en.wikipedia.org/wiki/Dwarf_planet', 'Wikipedia: Dwarf planet', '2026-11-21', 'CC BY-SA 4.0', 'space', 2, 0, '[{"canonical":"Pluto","prior":50,"aliases":[]},{"canonical":"Ceres","prior":18,"aliases":[]},{"canonical":"Eris","prior":14,"aliases":[]},{"canonical":"Haumea","prior":10,"aliases":[]},{"canonical":"Makemake","prior":8,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-space-elements', 'Name a chemical element named after something in the sky: the Sun, the Moon, a planet or an asteroid.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Helium was spotted in the Sun''s light before anyone found it on Earth. Uranium, neptunium and plutonium follow the planets in order, selenium is named for the Moon and tellurium for the Earth, and palladium for the asteroid Pallas, which had just been discovered.', 'https://en.wikipedia.org/wiki/List_of_chemical_element_name_etymologies', 'Wikipedia: List of chemical element name etymologies', '2026-11-21', 'CC BY-SA 4.0', 'space', 2, 0, '[{"canonical":"Uranium","prior":24,"aliases":[]},{"canonical":"Plutonium","prior":22,"aliases":[]},{"canonical":"Helium","prior":14,"aliases":[]},{"canonical":"Neptunium","prior":14,"aliases":[]},{"canonical":"Mercury","prior":10,"aliases":[]},{"canonical":"Cerium","prior":6,"aliases":[]},{"canonical":"Palladium","prior":4,"aliases":[]},{"canonical":"Selenium","prior":3,"aliases":[]},{"canonical":"Tellurium","prior":3,"aliases":[]}]', 'elements', NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-space-moons', 'Name a planet in our solar system that has at least one moon.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Mercury and Venus have none. Saturn holds the record, with well over 200 known moons, and Mars has two tiny ones, Phobos and Deimos, whose names mean Fear and Dread.', 'https://en.wikipedia.org/wiki/Natural_satellite', 'Wikipedia: Natural satellite', '2026-11-21', 'CC BY-SA 4.0', 'space', 1, 0, '[{"canonical":"Earth","prior":26,"aliases":[]},{"canonical":"Jupiter","prior":22,"aliases":[]},{"canonical":"Saturn","prior":20,"aliases":[]},{"canonical":"Mars","prior":14,"aliases":[]},{"canonical":"Uranus","prior":10,"aliases":[]},{"canonical":"Neptune","prior":8,"aliases":[]}]', NULL, NULL);
INSERT INTO questions (id, prompt, type, unit, polarity, scale, fact_ids, display_ids, context, source_url, source_name, retrieved_at, license, topic, difficulty, verified, accepted_json, entity_set, nudge) VALUES ('pq-space-animals', 'Name an animal that has been to space. Astronauts do not count.', 'name_one', NULL, 'higher', NULL, '[]', '[]', 'Fruit flies went first, on a rocket in 1947, to test radiation. Two Russian tortoises flew around the Moon in 1968, before any human did, and tardigrades have survived being left outside a spacecraft in open space.', 'https://en.wikipedia.org/wiki/Animals_in_space', 'Wikipedia: Animals in space', '2026-11-21', 'CC BY-SA 4.0', 'space', 1, 0, '[{"canonical":"Dog","prior":30,"aliases":["Dogs","Laika"]},{"canonical":"Monkey","prior":20,"aliases":["Monkeys","Rhesus monkey","Macaque"]},{"canonical":"Chimpanzee","prior":8,"aliases":["Chimp","Chimps","Chimpanzees"]},{"canonical":"Mouse","prior":8,"aliases":["Mice"]},{"canonical":"Cat","prior":4,"aliases":["Cats","Felicette"]},{"canonical":"Fruit fly","prior":4,"aliases":["Fruit flies","Drosophila","Fly","Flies"]},{"canonical":"Rat","prior":3,"aliases":["Rats"]},{"canonical":"Tortoise","prior":3,"aliases":["Tortoises","Turtle"]},{"canonical":"Spider","prior":3,"aliases":["Spiders"]},{"canonical":"Frog","prior":2,"aliases":["Frogs"]},{"canonical":"Fish","prior":2,"aliases":[]},{"canonical":"Tardigrade","prior":2,"aliases":["Tardigrades","Water bear","Water bears"]},{"canonical":"Jellyfish","prior":1,"aliases":[]},{"canonical":"Ant","prior":1,"aliases":["Ants"]},{"canonical":"Bee","prior":1,"aliases":["Bees","Honeybee"]},{"canonical":"Cockroach","prior":1,"aliases":["Cockroaches","Roach"]},{"canonical":"Worm","prior":1,"aliases":["Worms","Nematode","Nematodes","Flatworm"]},{"canonical":"Rabbit","prior":1,"aliases":["Rabbits"]},{"canonical":"Guinea pig","prior":1,"aliases":[]},{"canonical":"Newt","prior":0.5,"aliases":["Newts"]},{"canonical":"Quail","prior":0.5,"aliases":[]},{"canonical":"Cricket","prior":0.5,"aliases":["Crickets"]},{"canonical":"Gecko","prior":0.5,"aliases":["Geckos"]},{"canonical":"Squid","prior":0.5,"aliases":[]},{"canonical":"Silkworm","prior":0.5,"aliases":["Silkworms"]},{"canonical":"Butterfly","prior":0.5,"aliases":["Butterflies"]},{"canonical":"Snail","prior":0.5,"aliases":["Snails"]},{"canonical":"Sea urchin","prior":0.5,"aliases":[]}]', NULL, NULL);
